import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import matplotlib.pyplot as plt

# ======================
# Setup
# ======================
torch.manual_seed(42)
random.seed(42)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# ======================
# Helpers
# ======================
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

def make_batch(batch_size=8, size=64, device="cpu", thickness=2):
    obs = torch.zeros(batch_size, 2, size, size, device=device)
    target = torch.zeros(batch_size, 1, size, size, device=device)

    for b in range(batch_size):
        x0 = random.randint(8, size - 9)
        y0 = random.randint(8, size - 9)
        x1 = random.randint(8, size - 9)
        y1 = random.randint(8, size - 9)

        obs[b, 0, y0, x0] = 1.0
        obs[b, 1, y1, x1] = 1.0

        steps = max(abs(x1 - x0), abs(y1 - y0)) + 1
        xs = torch.linspace(x0, x1, steps).round().long().clamp(0, size - 1)
        ys = torch.linspace(y0, y1, steps).round().long().clamp(0, size - 1)
        target[b, 0, ys, xs] = 1.0

        # thicken the path so the task is learnable on a tiny model
        target[b:b+1] = F.max_pool2d(target[b:b+1], kernel_size=2 * thickness + 1, stride=1, padding=thickness)

    return obs, target

def soft_iou_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def hard_iou_from_logits(logits, target, thresh=0.3, eps=1e-6):
    prob = torch.sigmoid(logits)
    pred = (prob > thresh).float()
    inter = (pred * target).sum(dim=(1, 2, 3))
    union = ((pred + target) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    dice = 1.0 - (2.0 * inter + eps) / (union + eps)
    return dice.mean()

# ======================
# Model
# ======================
class PF2V_Minimal(nn.Module):
    def __init__(self, size=64, inner_steps=3):
        super().__init__()
        self.size = size
        self.inner_steps = inner_steps
        self.l = 0.8

        self.encoder = nn.Sequential(
            nn.Conv2d(2, 32, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(32, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        # QDMN directional stiffness: N, S, E, W
        self.qdmn_log_stiff = nn.Parameter(torch.zeros(4))

        # Spiral prior
        self.register_buffer("spiral_bias", self._make_spiral(size))

        # Base toughness
        self.log_gc = nn.Parameter(torch.tensor(0.0))

        # Readout from final latent fields to path logits
        self.readout = nn.Sequential(
            nn.Conv2d(4, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 1),
        )

    def _make_spiral(self, size):
        y, x = torch.meshgrid(torch.arange(size), torch.arange(size), indexing="ij")
        y = y.float()
        x = x.float()
        cx = size / 2
        cy = size / 2
        r = torch.sqrt((x - cx) ** 2 + (y - cy) ** 2) + 1e-6
        theta = torch.atan2(y - cy, x - cx)
        spiral = torch.sin(2.5 * theta + 1.1 * torch.log(r))
        return (1.0 + 0.15 * spiral).view(1, 1, size, size).to(device)

    def forward(self, obs):
        # IMPORTANT:
        # We enable grad inside the solver even during evaluation,
        # because the inner variational steps need autograd.grad.
        with torch.enable_grad():
            phi = self.encoder(obs)
            z_d = torch.zeros_like(phi, requires_grad=True)

            gc = torch.exp(self.log_gc) * self.spiral_bias
            stiff = F.softplus(self.qdmn_log_stiff) + 0.1

            for _ in range(self.inner_steps):
                d = torch.sigmoid(z_d)

                phi_x = grad_x(phi)
                phi_y = grad_y(phi)
                d_x = grad_x(d)
                d_y = grad_y(d)

                # QDMN anisotropic elastic energy
                elastic = 0.5 * (
                    stiff[0] * phi_y**2 +        # North
                    stiff[1] * (-phi_y)**2 +     # South
                    stiff[2] * phi_x**2 +        # East
                    stiff[3] * (-phi_x)**2       # West
                )

                degraded = (1.0 - d) ** 2 * elastic

                # Phase-field fracture regularization
                fracture = gc * (
                    d**2 / (2.0 * self.l) +
                    0.5 * self.l * (d_x**2 + d_y**2)
                )

                # Double-well term
                well = d**2 * (1.0 - d)**2

                energy = (degraded + fracture + well).mean()

                grad_zd = torch.autograd.grad(
                    energy, z_d, create_graph=True, retain_graph=True
                )[0]
                grad_phi = torch.autograd.grad(
                    energy, phi, create_graph=True
                )[0]

                z_d = z_d - 0.12 * grad_zd
                phi = phi - 0.06 * grad_phi

            d = torch.sigmoid(z_d)
            logits = self.readout(torch.cat([obs, d, phi], dim=1))

        # During eval, return detached tensors so visualization is cheap
        if not self.training:
            return logits.detach(), d.detach(), phi.detach()

        return logits, d, phi

# ======================
# Train
# ======================
model = PF2V_Minimal(size=64, inner_steps=3).to(device)
optimizer = torch.optim.Adam(model.parameters(), lr=1e-3)

for epoch in range(1, 201):
    model.train()
    obs, target = make_batch(batch_size=8, size=64, device=device, thickness=2)
    logits, d, phi = model(obs)

    # Positive class weighting helps because the path pixels are very sparse
    pos = target.sum().clamp_min(1.0)
    neg = target.numel() - pos
    pos_weight = (neg / pos).clamp(1.0, 50.0)

    bce = F.binary_cross_entropy_with_logits(logits, target, pos_weight=pos_weight)
    dice = dice_loss_from_logits(logits, target)

    prob = torch.sigmoid(logits)
    tv = (prob[:, :, :, 1:] - prob[:, :, :, :-1]).abs().mean() + (prob[:, :, 1:, :] - prob[:, :, :-1, :]).abs().mean()

    # Slightly stronger dice term and a little regularization
    loss = 1.2 * bce + 0.9 * dice + 0.03 * tv

    optimizer.zero_grad()
    loss.backward()
    torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
    optimizer.step()

    if epoch == 1 or epoch % 25 == 0:
        model.eval()
        with torch.no_grad():
            soft_iou = soft_iou_from_logits(logits, target).item()
            hard_iou = hard_iou_from_logits(logits, target, thresh=0.3).item()
        print(
            f"epoch {epoch:03d} | loss {loss.item():.4f} | "
            f"bce {bce.item():.4f} | dice {dice.item():.4f} | "
            f"soft_iou {soft_iou:.4f} | hard_iou {hard_iou:.4f}"
        )

print("training done")

# ======================
# Visualize
# ======================
model.eval()
obs, target = make_batch(batch_size=4, size=64, device=device, thickness=2)

# No error now, because the model internally enables grad for the solver
logits, d, phi = model(obs)
pred = torch.sigmoid(logits)

for i in range(4):
    plt.figure(figsize=(12, 4))

    plt.subplot(1, 3, 1)
    plt.title("Start + Goal")
    plt.imshow(obs[i].sum(dim=0).cpu(), cmap="gray")
    plt.axis("off")

    plt.subplot(1, 3, 2)
    plt.title("Prediction")
    plt.imshow(pred[i, 0].cpu(), cmap="hot", vmin=0, vmax=1)
    plt.axis("off")

    plt.subplot(1, 3, 3)
    plt.title("Target")
    plt.imshow(target[i, 0].cpu(), cmap="hot", vmin=0, vmax=1)
    plt.axis("off")

    plt.tight_layout()
    plt.show()

import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import matplotlib.pyplot as plt

# ======================
# Setup
# ======================
torch.manual_seed(42)
random.seed(42)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# ======================
# Helpers
# ======================
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

def gaussian_blob(size, x0, y0, sigma=1.25, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    dist2 = (x.float() - x0) ** 2 + (y.float() - y0) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def soft_line_mask(size, x0, y0, x1, y1, sigma=2.0, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    x = x.float()
    y = y.float()

    x0 = float(x0)
    y0 = float(y0)
    x1 = float(x1)
    y1 = float(y1)

    vx = x1 - x0
    vy = y1 - y0
    denom = vx * vx + vy * vy + 1e-6

    t = ((x - x0) * vx + (y - y0) * vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px) ** 2 + (y - py) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def make_batch(batch_size=8, size=64, device="cpu"):
    obs = torch.zeros(batch_size, 5, size, size, device=device)
    target = torch.zeros(batch_size, 1, size, size, device=device)

    yy, xx = torch.meshgrid(
        torch.linspace(-1, 1, size, device=device),
        torch.linspace(-1, 1, size, device=device),
        indexing="ij"
    )
    coord_x = xx.unsqueeze(0).unsqueeze(0)
    coord_y = yy.unsqueeze(0).unsqueeze(0)

    for b in range(batch_size):
        x0 = random.randint(8, size - 9)
        y0 = random.randint(8, size - 9)
        x1 = random.randint(8, size - 9)
        y1 = random.randint(8, size - 9)

        source = gaussian_blob(size, x0, y0, sigma=1.25, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.25, device=device)
        charge = source - goal
        target_map = soft_line_mask(size, x0, y0, x1, y1, sigma=2.0, device=device)

        obs[b:b+1, 0:1] = source
        obs[b:b+1, 1:2] = goal
        obs[b:b+1, 2:3] = charge
        obs[b:b+1, 3:4] = coord_x
        obs[b:b+1, 4:5] = coord_y
        target[b:b+1] = target_map

    return obs, target

def soft_iou_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def hard_iou_from_logits(logits, target, thresh=0.5, eps=1e-6):
    prob = torch.sigmoid(logits)
    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()
    inter = (pred * tgt).sum(dim=(1, 2, 3))
    union = ((pred + tgt) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    dice = 1.0 - (2.0 * inter + eps) / (union + eps)
    return dice.mean()

# ======================
# Model
# ======================
class PF2V_Minimal(nn.Module):
    def __init__(self, size=64, inner_steps=5):
        super().__init__()
        self.size = size
        self.inner_steps = inner_steps
        self.l = 0.8

        self.encoder = nn.Sequential(
            nn.Conv2d(5, 32, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(32, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.damage_init = nn.Sequential(
            nn.Conv2d(5, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.qdmn_log_stiff = nn.Parameter(torch.zeros(4))
        self.register_buffer("spiral_bias", self._make_spiral(size))
        self.log_gc = nn.Parameter(torch.tensor(-0.4))

        self.readout = nn.Sequential(
            nn.Conv2d(7, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 1),
        )

    def _make_spiral(self, size):
        y, x = torch.meshgrid(torch.arange(size), torch.arange(size), indexing="ij")
        y = y.float()
        x = x.float()
        cx = size / 2
        cy = size / 2
        r = torch.sqrt((x - cx) ** 2 + (y - cy) ** 2) + 1e-6
        theta = torch.atan2(y - cy, x - cx)
        spiral = torch.sin(2.5 * theta + 1.1 * torch.log(r))
        return (1.0 + 0.08 * spiral).view(1, 1, size, size).to(device)

    def forward(self, obs):
        phi = self.encoder(obs)
        z_d = self.damage_init(obs)

        gc = torch.exp(self.log_gc) * self.spiral_bias
        stiff = F.softplus(self.qdmn_log_stiff) + 0.15

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        charge = obs[:, 2:3]
        endpoints = source + goal

        for _ in range(self.inner_steps):
            d = torch.sigmoid(z_d)

            phi_x = grad_x(phi)
            phi_y = grad_y(phi)
            d_x = grad_x(d)
            d_y = grad_y(d)

            elastic = 0.5 * (
                stiff[0] * phi_y**2 +
                stiff[1] * (-phi_y)**2 +
                stiff[2] * phi_x**2 +
                stiff[3] * (-phi_x)**2
            )

            degraded = (1.0 - d) ** 2 * elastic

            fracture = gc * (
                d**2 / (2.0 * self.l) +
                0.5 * self.l * (d_x**2 + d_y**2)
            )

            well = d**2 * (1.0 - d)**2

            bridge_pressure = 0.08 * endpoints + 0.04 * charge.abs()

            d_drive = (
                bridge_pressure
                + 0.12 * degraded
                - gc * (
                    d / self.l
                    + 0.35 * laplacian(d)
                    + 2.0 * d * (1.0 - d) * (1.0 - 2.0 * d)
                )
            )

            phi_drive = (
                0.7 * laplacian(phi)
                + 0.9 * charge
                + 0.4 * endpoints
                - 0.08 * phi
                - 0.15 * d * phi
            )

            z_d = z_d + 0.14 * torch.tanh(d_drive)
            phi = phi + 0.05 * torch.tanh(phi_drive)

        d = torch.sigmoid(z_d)
        logits = self.readout(torch.cat([obs, d, phi], dim=1)) + 0.35 * z_d
        return logits, d, phi

# ======================
# Train
# ======================
model = PF2V_Minimal(size=64, inner_steps=5).to(device)
optimizer = torch.optim.Adam(model.parameters(), lr=1e-3)

for epoch in range(1, 251):
    model.train()
    obs, target = make_batch(batch_size=8, size=64, device=device)
    logits, d, phi = model(obs)

    pos = target.sum().clamp_min(1.0)
    neg = target.numel() - pos
    pos_weight = (neg / pos).clamp(1.0, 25.0)

    bce_main = F.binary_cross_entropy_with_logits(logits, target, pos_weight=pos_weight)
    bce_latent = F.binary_cross_entropy(d.clamp(1e-4, 1 - 1e-4), target)
    dice = dice_loss_from_logits(logits, target)

    prob = torch.sigmoid(logits)
    tv = (prob[:, :, :, 1:] - prob[:, :, :, :-1]).abs().mean() + (prob[:, :, 1:, :] - prob[:, :, :-1, :]).abs().mean()

    loss = 1.0 * bce_main + 0.7 * bce_latent + 0.8 * dice + 0.02 * tv

    optimizer.zero_grad()
    loss.backward()
    torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
    optimizer.step()

    if epoch == 1 or epoch % 25 == 0:
        model.eval()
        with torch.no_grad():
            logits_eval, _, _ = model(obs)
            soft_iou = soft_iou_from_logits(logits_eval, target).item()
            hard_iou = hard_iou_from_logits(logits_eval, target, thresh=0.5).item()
        print(
            f"epoch {epoch:03d} | loss {loss.item():.4f} | "
            f"bce {bce_main.item():.4f} | latent {bce_latent.item():.4f} | "
            f"dice {dice.item():.4f} | soft_iou {soft_iou:.4f} | hard_iou {hard_iou:.4f}"
        )

print("training done")

# ======================
# Visualize: single figure
# ======================
model.eval()
with torch.no_grad():
    obs, target = make_batch(batch_size=1, size=64, device=device)
    logits, d, phi = model(obs)
    pred = torch.sigmoid(logits)

inp = (obs[0, 0] + obs[0, 1]).detach().cpu()
tgt = target[0, 0].detach().cpu()
prd = pred[0, 0].detach().cpu()
latent = d[0, 0].detach().cpu()

fig, axes = plt.subplots(2, 2, figsize=(10, 10))

axes[0, 0].imshow(inp, cmap="gray")
axes[0, 0].set_title("Input: Start + Goal")
axes[0, 0].axis("off")

axes[0, 1].imshow(tgt, cmap="hot", vmin=0, vmax=1)
axes[0, 1].set_title("Target Corridor")
axes[0, 1].axis("off")

axes[1, 0].imshow(prd, cmap="hot", vmin=0, vmax=1)
axes[1, 0].set_title("Prediction")
axes[1, 0].axis("off")

axes[1, 1].imshow(latent, cmap="hot", vmin=0, vmax=1)
axes[1, 1].set_title("Latent Damage Field d")
axes[1, 1].axis("off")

plt.tight_layout()
plt.show()

import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import matplotlib.pyplot as plt

# ======================
# Setup
# ======================
torch.manual_seed(42)
random.seed(42)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# ======================
# Helpers
# ======================
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

def gaussian_blob(size, x0, y0, sigma=1.25, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    dist2 = (x.float() - x0) ** 2 + (y.float() - y0) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def soft_line_mask(size, x0, y0, x1, y1, sigma=2.0, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    x = x.float()
    y = y.float()

    x0 = float(x0)
    y0 = float(y0)
    x1 = float(x1)
    y1 = float(y1)

    vx = x1 - x0
    vy = y1 - y0
    denom = vx * vx + vy * vy + 1e-6

    t = ((x - x0) * vx + (y - y0) * vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px) ** 2 + (y - py) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def make_batch(batch_size=8, size=64, device="cpu"):
    obs = torch.zeros(batch_size, 5, size, size, device=device)
    target = torch.zeros(batch_size, 1, size, size, device=device)

    yy, xx = torch.meshgrid(
        torch.linspace(-1, 1, size, device=device),
        torch.linspace(-1, 1, size, device=device),
        indexing="ij"
    )
    coord_x = xx.unsqueeze(0).unsqueeze(0)
    coord_y = yy.unsqueeze(0).unsqueeze(0)

    for b in range(batch_size):
        x0 = random.randint(8, size - 9)
        y0 = random.randint(8, size - 9)
        x1 = random.randint(8, size - 9)
        y1 = random.randint(8, size - 9)

        source = gaussian_blob(size, x0, y0, sigma=1.25, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.25, device=device)
        charge = source - goal
        target_map = soft_line_mask(size, x0, y0, x1, y1, sigma=2.0, device=device)

        obs[b:b+1, 0:1] = source
        obs[b:b+1, 1:2] = goal
        obs[b:b+1, 2:3] = charge
        obs[b:b+1, 3:4] = coord_x
        obs[b:b+1, 4:5] = coord_y
        target[b:b+1] = target_map

    return obs, target

def soft_iou_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def hard_iou_from_logits(logits, target, thresh=0.5, eps=1e-6):
    prob = torch.sigmoid(logits)
    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()
    inter = (pred * tgt).sum(dim=(1, 2, 3))
    union = ((pred + tgt) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    dice = 1.0 - (2.0 * inter + eps) / (union + eps)
    return dice.mean()

# ======================
# Model
# ======================
class PF2V_Minimal(nn.Module):
    def __init__(self, size=64, inner_steps=5):
        super().__init__()
        self.size = size
        self.inner_steps = inner_steps
        self.l = 0.8

        self.encoder = nn.Sequential(
            nn.Conv2d(5, 32, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(32, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.damage_init = nn.Sequential(
            nn.Conv2d(5, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.qdmn_log_stiff = nn.Parameter(torch.zeros(4))
        self.register_buffer("spiral_bias", self._make_spiral(size))
        self.log_gc = nn.Parameter(torch.tensor(-0.4))

        self.readout = nn.Sequential(
            nn.Conv2d(7, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 1),
        )

    def _make_spiral(self, size):
        y, x = torch.meshgrid(torch.arange(size), torch.arange(size), indexing="ij")
        y = y.float()
        x = x.float()
        cx = size / 2
        cy = size / 2
        r = torch.sqrt((x - cx) ** 2 + (y - cy) ** 2) + 1e-6
        theta = torch.atan2(y - cy, x - cx)
        spiral = torch.sin(2.5 * theta + 1.1 * torch.log(r))
        return (1.0 + 0.08 * spiral).view(1, 1, size, size).to(device)

    def forward(self, obs):
        phi = self.encoder(obs)
        z_d = self.damage_init(obs)

        gc = torch.exp(self.log_gc) * self.spiral_bias
        stiff = F.softplus(self.qdmn_log_stiff) + 0.15

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        charge = obs[:, 2:3]
        endpoints = source + goal

        for _ in range(self.inner_steps):
            d = torch.sigmoid(z_d)

            phi_x = grad_x(phi)
            phi_y = grad_y(phi)
            d_x = grad_x(d)
            d_y = grad_y(d)

            elastic = 0.5 * (
                stiff[0] * phi_y**2 +
                stiff[1] * (-phi_y)**2 +
                stiff[2] * phi_x**2 +
                stiff[3] * (-phi_x)**2
            )

            degraded = (1.0 - d) ** 2 * elastic

            fracture = gc * (
                d**2 / (2.0 * self.l) +
                0.5 * self.l * (d_x**2 + d_y**2)
            )

            well = d**2 * (1.0 - d)**2

            bridge_pressure = 0.08 * endpoints + 0.04 * charge.abs()

            d_drive = (
                bridge_pressure
                + 0.12 * degraded
                - gc * (
                    d / self.l
                    + 0.35 * laplacian(d)
                    + 2.0 * d * (1.0 - d) * (1.0 - 2.0 * d)
                )
            )

            phi_drive = (
                0.7 * laplacian(phi)
                + 0.9 * charge
                + 0.4 * endpoints
                - 0.08 * phi
                - 0.15 * d * phi
            )

            z_d = z_d + 0.14 * torch.tanh(d_drive)
            phi = phi + 0.05 * torch.tanh(phi_drive)

        d = torch.sigmoid(z_d)
        logits = self.readout(torch.cat([obs, d, phi], dim=1)) + 0.35 * z_d
        return logits, d, phi

# ======================
# Train
# ======================
model = PF2V_Minimal(size=64, inner_steps=5).to(device)
optimizer = torch.optim.Adam(model.parameters(), lr=1e-3)

for epoch in range(1, 251):
    model.train()
    obs, target = make_batch(batch_size=8, size=64, device=device)
    logits, d, phi = model(obs)

    pos = target.sum().clamp_min(1.0)
    neg = target.numel() - pos
    pos_weight = (neg / pos).clamp(1.0, 25.0)

    bce_main = F.binary_cross_entropy_with_logits(logits, target, pos_weight=pos_weight)
    bce_latent = F.binary_cross_entropy(d.clamp(1e-4, 1 - 1e-4), target)
    dice = dice_loss_from_logits(logits, target)

    prob = torch.sigmoid(logits)
    tv = (prob[:, :, :, 1:] - prob[:, :, :, :-1]).abs().mean() + (prob[:, :, 1:, :] - prob[:, :, :-1, :]).abs().mean()

    loss = 1.0 * bce_main + 0.7 * bce_latent + 0.8 * dice + 0.02 * tv

    optimizer.zero_grad()
    loss.backward()
    torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
    optimizer.step()

    if epoch == 1 or epoch % 25 == 0:
        model.eval()
        with torch.no_grad():
            logits_eval, _, _ = model(obs)
            soft_iou = soft_iou_from_logits(logits_eval, target).item()
            hard_iou = hard_iou_from_logits(logits_eval, target, thresh=0.5).item()
        print(
            f"epoch {epoch:03d} | loss {loss.item():.4f} | "
            f"bce {bce_main.item():.4f} | latent {bce_latent.item():.4f} | "
            f"dice {dice.item():.4f} | soft_iou {soft_iou:.4f} | hard_iou {hard_iou:.4f}"
        )

print("training done")

# ======================
# Visualize: single figure
# ======================
model.eval()
with torch.no_grad():
    obs, target = make_batch(batch_size=1, size=64, device=device)
    logits, d, phi = model(obs)
    pred = torch.sigmoid(logits)

inp = (obs[0, 0] + obs[0, 1]).detach().cpu().numpy()
tgt = target[0, 0].detach().cpu().numpy()
prd = pred[0, 0].detach().cpu().numpy()
latent = d[0, 0].detach().cpu().numpy()

fig, axes = plt.subplots(2, 2, figsize=(10, 10))

axes[0, 0].imshow(inp, cmap="gray")
axes[0, 0].set_title("Input: Start + Goal")
axes[0, 0].axis("off")

axes[0, 1].imshow(tgt, cmap="hot", vmin=0, vmax=1)
axes[0, 1].set_title("Target Corridor")
axes[0, 1].axis("off")

axes[1, 0].imshow(prd, cmap="hot", vmin=0, vmax=1)
axes[1, 0].set_title("Prediction")
axes[1, 0].axis("off")

axes[1, 1].imshow(latent, cmap="hot", vmin=0, vmax=1)
axes[1, 1].set_title("Latent Damage Field d")
axes[1, 1].axis("off")

plt.tight_layout()
plt.show()

import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import matplotlib.pyplot as plt

# ======================
# Setup
# ======================
torch.manual_seed(42)
random.seed(42)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# ======================
# Helpers
# ======================
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

def gaussian_blob(size, x0, y0, sigma=1.25, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    dist2 = (x.float() - x0) ** 2 + (y.float() - y0) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def soft_line_mask(size, x0, y0, x1, y1, sigma=1.5, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    x = x.float()
    y = y.float()

    x0 = float(x0)
    y0 = float(y0)
    x1 = float(x1)
    y1 = float(y1)

    vx = x1 - x0
    vy = y1 - y0
    denom = vx * vx + vy * vy + 1e-6

    t = ((x - x0) * vx + (y - y0) * vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px) ** 2 + (y - py) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def make_batch(batch_size=8, size=64, device="cpu"):
    # 7 channels:
    # 0 source blob
    # 1 goal blob
    # 2 charge = source - goal
    # 3 x coordinate
    # 4 y coordinate
    # 5 direction x from source to goal
    # 6 direction y from source to goal
    obs = torch.zeros(batch_size, 7, size, size, device=device)
    target = torch.zeros(batch_size, 1, size, size, device=device)

    yy, xx = torch.meshgrid(
        torch.linspace(-1, 1, size, device=device),
        torch.linspace(-1, 1, size, device=device),
        indexing="ij"
    )
    coord_x = xx.unsqueeze(0).unsqueeze(0)
    coord_y = yy.unsqueeze(0).unsqueeze(0)

    for b in range(batch_size):
        x0 = random.randint(8, size - 9)
        y0 = random.randint(8, size - 9)
        x1 = random.randint(8, size - 9)
        y1 = random.randint(8, size - 9)

        source = gaussian_blob(size, x0, y0, sigma=1.25, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.25, device=device)
        charge = source - goal
        target_map = soft_line_mask(size, x0, y0, x1, y1, sigma=1.5, device=device)

        dx = float(x1 - x0)
        dy = float(y1 - y0)
        norm = (dx * dx + dy * dy) ** 0.5 + 1e-6
        dir_x = torch.full((1, 1, size, size), dx / norm, device=device)
        dir_y = torch.full((1, 1, size, size), dy / norm, device=device)

        obs[b:b+1, 0:1] = source
        obs[b:b+1, 1:2] = goal
        obs[b:b+1, 2:3] = charge
        obs[b:b+1, 3:4] = coord_x
        obs[b:b+1, 4:5] = coord_y
        obs[b:b+1, 5:6] = dir_x
        obs[b:b+1, 6:7] = dir_y
        target[b:b+1] = target_map

    return obs, target

def soft_iou_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def hard_iou_from_logits(logits, target, thresh=0.5, eps=1e-6):
    prob = torch.sigmoid(logits)
    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()
    inter = (pred * tgt).sum(dim=(1, 2, 3))
    union = ((pred + tgt) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    dice = 1.0 - (2.0 * inter + eps) / (union + eps)
    return dice.mean()

# ======================
# Model
# ======================
class PF2V_MinimalSharp(nn.Module):
    def __init__(self, size=64, inner_steps=6):
        super().__init__()
        self.size = size
        self.inner_steps = inner_steps
        self.l = 0.45   # smaller length scale -> sharper paths

        self.encoder = nn.Sequential(
            nn.Conv2d(7, 32, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(32, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.damage_init = nn.Sequential(
            nn.Conv2d(7, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.qdmn_log_stiff = nn.Parameter(torch.zeros(4))
        self.log_gc = nn.Parameter(torch.tensor(-0.8))
        self.register_buffer("spiral_bias", self._make_spiral(size))

    def _make_spiral(self, size):
        y, x = torch.meshgrid(torch.arange(size), torch.arange(size), indexing="ij")
        y = y.float()
        x = x.float()
        cx = size / 2
        cy = size / 2
        r = torch.sqrt((x - cx) ** 2 + (y - cy) ** 2) + 1e-6
        theta = torch.atan2(y - cy, x - cx)
        spiral = torch.sin(2.5 * theta + 1.1 * torch.log(r))
        return (1.0 + 0.05 * spiral).view(1, 1, size, size).to(device)

    def forward(self, obs):
        phi = self.encoder(obs)
        z_d = self.damage_init(obs)

        gc = torch.exp(self.log_gc) * self.spiral_bias
        stiff = F.softplus(self.qdmn_log_stiff) + 0.10

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        charge = obs[:, 2:3]
        dir_x = obs[:, 5:6]
        dir_y = obs[:, 6:7]
        endpoints = source + goal

        # explicit, stable, unrolled solver
        for _ in range(self.inner_steps):
            d = torch.sigmoid(8.0 * z_d)  # sharpened commitment

            phi_x = grad_x(phi)
            phi_y = grad_y(phi)
            d_x = grad_x(d)
            d_y = grad_y(d)

            elastic = 0.5 * (
                stiff[0] * phi_y**2 +
                stiff[1] * (-phi_y)**2 +
                stiff[2] * phi_x**2 +
                stiff[3] * (-phi_x)**2
            )

            degraded = (1.0 - d) ** 2 * elastic

            fracture = gc * (
                d**2 / (2.0 * self.l) +
                0.5 * self.l * (d_x**2 + d_y**2)
            )

            well = 3.5 * d**2 * (1.0 - d)**2

            bridge_pressure = 0.12 * endpoints + 0.08 * charge.abs()
            direction_bias = 0.05 * (dir_x.abs() + dir_y.abs())

            d_drive = (
                bridge_pressure
                + direction_bias
                + 0.10 * degraded
                - gc * (
                    d / self.l
                    + 0.25 * laplacian(d)
                    + 2.0 * d * (1.0 - d) * (1.0 - 2.0 * d)
                )
            )

            phi_drive = (
                0.6 * laplacian(phi)
                + 0.7 * charge
                + 0.3 * endpoints
                + 0.2 * (dir_x + dir_y)
                - 0.08 * phi
                - 0.10 * d * phi
            )

            z_d = z_d + 0.18 * torch.tanh(d_drive)
            phi = phi + 0.04 * torch.tanh(phi_drive)

        d = torch.sigmoid(8.0 * z_d)
        logits = 8.0 * (d - 0.5)   # sharpened output, no fuzzy readout head
        return logits, d, phi

# ======================
# Train
# ======================
model = PF2V_MinimalSharp(size=64, inner_steps=6).to(device)
optimizer = torch.optim.Adam(model.parameters(), lr=8e-4)

for epoch in range(1, 301):
    model.train()
    obs, target = make_batch(batch_size=8, size=64, device=device)
    logits, d, phi = model(obs)

    pos = target.sum().clamp_min(1.0)
    neg = target.numel() - pos
    pos_weight = (neg / pos).clamp(1.0, 30.0)

    bce_main = F.binary_cross_entropy_with_logits(logits, target, pos_weight=pos_weight)
    bce_latent = F.binary_cross_entropy(d.clamp(1e-4, 1 - 1e-4), target)
    dice = dice_loss_from_logits(logits, target)

    prob = torch.sigmoid(logits)
    tv = (prob[:, :, :, 1:] - prob[:, :, :, :-1]).abs().mean() + (prob[:, :, 1:, :] - prob[:, :, :-1, :]).abs().mean()

    commitment = (d * (1.0 - d)).mean()
    edge_loss = (
        F.mse_loss(grad_x(prob), grad_x(target)) +
        F.mse_loss(grad_y(prob), grad_y(target))
    )

    loss = (
        1.0 * bce_main +
        0.7 * bce_latent +
        0.8 * dice +
        0.20 * edge_loss +
        0.15 * commitment +
        0.02 * tv
    )

    optimizer.zero_grad()
    loss.backward()
    torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
    optimizer.step()

    if epoch == 1 or epoch % 25 == 0:
        model.eval()
        with torch.no_grad():
            logits_eval, _, _ = model(obs)
            soft_iou = soft_iou_from_logits(logits_eval, target).item()
            hard_iou = hard_iou_from_logits(logits_eval, target, thresh=0.5).item()
        print(
            f"epoch {epoch:03d} | loss {loss.item():.4f} | "
            f"bce {bce_main.item():.4f} | latent {bce_latent.item():.4f} | "
            f"dice {dice.item():.4f} | edge {edge_loss.item():.4f} | "
            f"soft_iou {soft_iou:.4f} | hard_iou {hard_iou:.4f}"
        )

print("training done")

# ======================
# Visualize: single figure
# ======================
model.eval()
with torch.no_grad():
    obs, target = make_batch(batch_size=1, size=64, device=device)
    logits, d, phi = model(obs)
    pred = torch.sigmoid(logits)

inp = (obs[0, 0] + obs[0, 1]).detach().cpu().numpy()
tgt = target[0, 0].detach().cpu().numpy()
prd = pred[0, 0].detach().cpu().numpy()
latent = d[0, 0].detach().cpu().numpy()

fig, axes = plt.subplots(2, 2, figsize=(10, 10))

axes[0, 0].imshow(inp, cmap="gray")
axes[0, 0].set_title("Input: Start + Goal")
axes[0, 0].axis("off")

axes[0, 1].imshow(tgt, cmap="hot", vmin=0, vmax=1)
axes[0, 1].set_title("Target Corridor")
axes[0, 1].axis("off")

axes[1, 0].imshow(prd, cmap="hot", vmin=0, vmax=1)
axes[1, 0].set_title("Prediction")
axes[1, 0].axis("off")

axes[1, 1].imshow(latent, cmap="hot", vmin=0, vmax=1)
axes[1, 1].set_title("Latent Damage Field d")
axes[1, 1].axis("off")

plt.tight_layout()
plt.show()

import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import matplotlib.pyplot as plt

# ======================
# Setup
# ======================
torch.manual_seed(42)
random.seed(42)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# ======================
# Helpers
# ======================
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

def gaussian_blob(size, x0, y0, sigma=1.25, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    dist2 = (x.float() - x0) ** 2 + (y.float() - y0) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def soft_line_mask(size, x0, y0, x1, y1, sigma=2.2, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    x = x.float()
    y = y.float()

    x0 = float(x0)
    y0 = float(y0)
    x1 = float(x1)
    y1 = float(y1)

    vx = x1 - x0
    vy = y1 - y0
    denom = vx * vx + vy * vy + 1e-6

    t = ((x - x0) * vx + (y - y0) * vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px) ** 2 + (y - py) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def make_batch(batch_size=8, size=64, device="cpu", target_sigma=2.2):
    # 7 channels:
    # 0 source blob
    # 1 goal blob
    # 2 charge = source - goal
    # 3 x coordinate
    # 4 y coordinate
    # 5 direction x from source to goal
    # 6 direction y from source to goal
    obs = torch.zeros(batch_size, 7, size, size, device=device)
    target = torch.zeros(batch_size, 1, size, size, device=device)

    yy, xx = torch.meshgrid(
        torch.linspace(-1, 1, size, device=device),
        torch.linspace(-1, 1, size, device=device),
        indexing="ij"
    )
    coord_x = xx.unsqueeze(0).unsqueeze(0)
    coord_y = yy.unsqueeze(0).unsqueeze(0)

    for b in range(batch_size):
        x0 = random.randint(8, size - 9)
        y0 = random.randint(8, size - 9)
        x1 = random.randint(8, size - 9)
        y1 = random.randint(8, size - 9)

        source = gaussian_blob(size, x0, y0, sigma=1.25, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.25, device=device)
        charge = source - goal
        target_map = soft_line_mask(size, x0, y0, x1, y1, sigma=target_sigma, device=device)

        dx = float(x1 - x0)
        dy = float(y1 - y0)
        norm = (dx * dx + dy * dy) ** 0.5 + 1e-6
        dir_x = torch.full((1, 1, size, size), dx / norm, device=device)
        dir_y = torch.full((1, 1, size, size), dy / norm, device=device)

        obs[b:b+1, 0:1] = source
        obs[b:b+1, 1:2] = goal
        obs[b:b+1, 2:3] = charge
        obs[b:b+1, 3:4] = coord_x
        obs[b:b+1, 4:5] = coord_y
        obs[b:b+1, 5:6] = dir_x
        obs[b:b+1, 6:7] = dir_y
        target[b:b+1] = target_map

    return obs, target

def soft_iou_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def hard_iou_from_logits(logits, target, thresh=0.5, eps=1e-6):
    prob = torch.sigmoid(logits)
    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()
    inter = (pred * tgt).sum(dim=(1, 2, 3))
    union = ((pred + tgt) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    dice = 1.0 - (2.0 * inter + eps) / (union + eps)
    return dice.mean()

# ======================
# Model
# ======================
class PF2V_Annealed(nn.Module):
    def __init__(self, size=64, inner_steps=7):
        super().__init__()
        self.size = size
        self.inner_steps = inner_steps

        self.encoder = nn.Sequential(
            nn.Conv2d(7, 32, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(32, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.damage_init = nn.Sequential(
            nn.Conv2d(7, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.qdmn_log_stiff = nn.Parameter(torch.zeros(4))
        self.log_gc = nn.Parameter(torch.tensor(-0.8))
        self.register_buffer("spiral_bias", self._make_spiral(size))

        self.readout = nn.Sequential(
            nn.Conv2d(9, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 1),
        )

    def _make_spiral(self, size):
        y, x = torch.meshgrid(torch.arange(size), torch.arange(size), indexing="ij")
        y = y.float()
        x = x.float()
        cx = size / 2
        cy = size / 2
        r = torch.sqrt((x - cx) ** 2 + (y - cy) ** 2) + 1e-6
        theta = torch.atan2(y - cy, x - cx)
        spiral = torch.sin(2.5 * theta + 1.1 * torch.log(r))
        return (1.0 + 0.06 * spiral).view(1, 1, size, size).to(device)

    def forward(self, obs, commit_scale=3.0, l_value=0.6):
        phi = self.encoder(obs)
        z_d = self.damage_init(obs)

        gc = torch.exp(self.log_gc) * self.spiral_bias
        stiff = F.softplus(self.qdmn_log_stiff) + 0.10

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        charge = obs[:, 2:3]
        dir_x = obs[:, 5:6]
        dir_y = obs[:, 6:7]
        endpoints = source + goal

        for _ in range(self.inner_steps):
            d = torch.sigmoid(commit_scale * z_d)

            phi_x = grad_x(phi)
            phi_y = grad_y(phi)
            d_x = grad_x(d)
            d_y = grad_y(d)

            elastic = 0.5 * (
                stiff[0] * phi_y**2 +
                stiff[1] * (-phi_y)**2 +
                stiff[2] * phi_x**2 +
                stiff[3] * (-phi_x)**2
            )

            degraded = (1.0 - d) ** 2 * elastic

            fracture = gc * (
                d**2 / (2.0 * l_value) +
                0.5 * l_value * (d_x**2 + d_y**2)
            )

            well = 3.0 * d**2 * (1.0 - d)**2

            bridge_pressure = 0.12 * endpoints + 0.08 * charge.abs()
            direction_bias = 0.06 * (dir_x.abs() + dir_y.abs())

            d_drive = (
                bridge_pressure
                + direction_bias
                + 0.08 * degraded
                - gc * (
                    d / l_value
                    + 0.22 * laplacian(d)
                    + 2.0 * d * (1.0 - d) * (1.0 - 2.0 * d)
                )
            )

            phi_drive = (
                0.55 * laplacian(phi)
                + 0.65 * charge
                + 0.25 * endpoints
                + 0.15 * (dir_x + dir_y)
                - 0.06 * phi
                - 0.10 * d * phi
            )

            z_d = z_d + 0.15 * torch.tanh(d_drive)
            phi = phi + 0.04 * torch.tanh(phi_drive)

        d = torch.sigmoid(commit_scale * z_d)

        # Sharpen the final output without removing the latent field
        logits = 8.0 * (d - 0.5) + 0.25 * self.readout(torch.cat([obs, d, phi], dim=1))
        return logits, d, phi

# ======================
# Train
# ======================
model = PF2V_Annealed(size=64, inner_steps=7).to(device)
optimizer = torch.optim.Adam(model.parameters(), lr=8e-4)

max_epochs = 300

for epoch in range(1, max_epochs + 1):
    model.train()

    t = (epoch - 1) / (max_epochs - 1)
    commit_scale = 2.0 + 8.0 * t     # start fuzzy, end sharp
    l_value = 0.75 - 0.35 * t        # shrink crack width over time
    target_sigma = 2.5 - 1.0 * t     # curriculum on the target corridor

    obs, target = make_batch(batch_size=8, size=64, device=device, target_sigma=target_sigma)
    logits, d, phi = model(obs, commit_scale=commit_scale, l_value=l_value)

    pos = target.sum().clamp_min(1.0)
    neg = target.numel() - pos
    pos_weight = (neg / pos).clamp(1.0, 30.0)

    bce_main = F.binary_cross_entropy_with_logits(logits, target, pos_weight=pos_weight)
    bce_latent = F.binary_cross_entropy(d.clamp(1e-4, 1 - 1e-4), target)
    dice = dice_loss_from_logits(logits, target)

    prob = torch.sigmoid(logits)
    tv = (prob[:, :, :, 1:] - prob[:, :, :, :-1]).abs().mean() + (prob[:, :, 1:, :] - prob[:, :, :-1, :]).abs().mean()

    # Connectivity-friendly terms
    edge_loss = (
        F.mse_loss(grad_x(prob), grad_x(target)) +
        F.mse_loss(grad_y(prob), grad_y(target))
    )
    lap_loss = F.mse_loss(laplacian(prob), laplacian(target))
    commitment = (prob * (1.0 - prob)).mean()
    outside_loss = ((1.0 - target) * prob).mean()

    loss = (
        1.0 * bce_main +
        0.7 * bce_latent +
        0.7 * dice +
        0.20 * edge_loss +
        0.12 * lap_loss +
        0.15 * commitment +
        0.10 * outside_loss +
        0.02 * tv
    )

    optimizer.zero_grad()
    loss.backward()
    torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
    optimizer.step()

    if epoch == 1 or epoch % 25 == 0:
        model.eval()
        with torch.no_grad():
            logits_eval, _, _ = model(obs, commit_scale=commit_scale, l_value=l_value)
            soft_iou = soft_iou_from_logits(logits_eval, target).item()
            hard_iou = hard_iou_from_logits(logits_eval, target, thresh=0.5).item()
        print(
            f"epoch {epoch:03d} | loss {loss.item():.4f} | "
            f"bce {bce_main.item():.4f} | latent {bce_latent.item():.4f} | "
            f"dice {dice.item():.4f} | edge {edge_loss.item():.4f} | lap {lap_loss.item():.4f} | "
            f"soft_iou {soft_iou:.4f} | hard_iou {hard_iou:.4f}"
        )

print("training done")

# ======================
# Visualize: single figure
# ======================
model.eval()
with torch.no_grad():
    obs, target = make_batch(batch_size=1, size=64, device=device, target_sigma=1.5)
    logits, d, phi = model(obs, commit_scale=10.0, l_value=0.40)
    pred = torch.sigmoid(logits)

inp = (obs[0, 0] + obs[0, 1]).detach().cpu().numpy()
tgt = target[0, 0].detach().cpu().numpy()
prd = pred[0, 0].detach().cpu().numpy()
latent = d[0, 0].detach().cpu().numpy()

fig, axes = plt.subplots(2, 2, figsize=(10, 10))

axes[0, 0].imshow(inp, cmap="gray")
axes[0, 0].set_title("Input: Start + Goal")
axes[0, 0].axis("off")

axes[0, 1].imshow(tgt, cmap="hot", vmin=0, vmax=1)
axes[0, 1].set_title("Target Corridor")
axes[0, 1].axis("off")

axes[1, 0].imshow(prd, cmap="hot", vmin=0, vmax=1)
axes[1, 0].set_title("Prediction")
axes[1, 0].axis("off")

axes[1, 1].imshow(latent, cmap="hot", vmin=0, vmax=1)
axes[1, 1].set_title("Latent Damage Field d")
axes[1, 1].axis("off")

plt.tight_layout()
plt.show()

import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import matplotlib.pyplot as plt
import numpy as np

# ======================
# Setup
# ======================
torch.manual_seed(42)
random.seed(42)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# ======================
# Helpers
# ======================
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

def gaussian_blob(size, x0, y0, sigma=1.25, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    dist2 = (x.float() - x0) ** 2 + (y.float() - y0) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def soft_line_mask(size, x0, y0, x1, y1, sigma=1.6, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    x = x.float()
    y = y.float()

    x0 = float(x0)
    y0 = float(y0)
    x1 = float(x1)
    y1 = float(y1)

    vx = x1 - x0
    vy = y1 - y0
    denom = vx * vx + vy * vy + 1e-6

    t = ((x - x0) * vx + (y - y0) * vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px) ** 2 + (y - py) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def make_batch(batch_size=8, size=64, device="cpu", target_sigma=1.6):
    # 7 channels:
    # 0 source blob
    # 1 goal blob
    # 2 charge = source - goal
    # 3 x coordinate
    # 4 y coordinate
    # 5 direction x from source to goal
    # 6 direction y from source to goal
    obs = torch.zeros(batch_size, 7, size, size, device=device)
    target = torch.zeros(batch_size, 1, size, size, device=device)

    yy, xx = torch.meshgrid(
        torch.linspace(-1, 1, size, device=device),
        torch.linspace(-1, 1, size, device=device),
        indexing="ij"
    )
    coord_x = xx.unsqueeze(0).unsqueeze(0)
    coord_y = yy.unsqueeze(0).unsqueeze(0)

    for b in range(batch_size):
        x0 = random.randint(8, size - 9)
        y0 = random.randint(8, size - 9)
        x1 = random.randint(8, size - 9)
        y1 = random.randint(8, size - 9)

        source = gaussian_blob(size, x0, y0, sigma=1.25, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.25, device=device)
        charge = source - goal
        target_map = soft_line_mask(size, x0, y0, x1, y1, sigma=target_sigma, device=device)

        dx = float(x1 - x0)
        dy = float(y1 - y0)
        norm = (dx * dx + dy * dy) ** 0.5 + 1e-6
        dir_x = torch.full((1, 1, size, size), dx / norm, device=device)
        dir_y = torch.full((1, 1, size, size), dy / norm, device=device)

        obs[b:b+1, 0:1] = source
        obs[b:b+1, 1:2] = goal
        obs[b:b+1, 2:3] = charge
        obs[b:b+1, 3:4] = coord_x
        obs[b:b+1, 4:5] = coord_y
        obs[b:b+1, 5:6] = dir_x
        obs[b:b+1, 6:7] = dir_y
        target[b:b+1] = target_map

    return obs, target

def soft_iou_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def hard_iou_from_logits(logits, target, thresh=0.5, eps=1e-6):
    prob = torch.sigmoid(logits)
    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()
    inter = (pred * tgt).sum(dim=(1, 2, 3))
    union = ((pred + tgt) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    dice = 1.0 - (2.0 * inter + eps) / (union + eps)
    return dice.mean()

def connectivity_estimate(prob, thresh=0.5):
    binary = (prob > thresh).float()
    horizontal_links = (binary[:, :, :, 1:] * binary[:, :, :, :-1]).mean().item()
    vertical_links = (binary[:, :, 1:, :] * binary[:, :, :-1, :]).mean().item()
    return horizontal_links + vertical_links

# ======================
# Model
# ======================
class PF2V_NoBypass(nn.Module):
    def __init__(self, size=64, inner_steps=7):
        super().__init__()
        self.size = size
        self.inner_steps = inner_steps

        self.encoder = nn.Sequential(
            nn.Conv2d(7, 32, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(32, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.damage_init = nn.Sequential(
            nn.Conv2d(7, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.qdmn_log_stiff = nn.Parameter(torch.zeros(4))
        self.log_gc = nn.Parameter(torch.tensor(-0.8))
        self.register_buffer("spiral_bias", self._make_spiral(size))

        # Only [d, phi] here — no direct obs shortcut
        self.readout = nn.Sequential(
            nn.Conv2d(2, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 1),
        )

    def _make_spiral(self, size):
        y, x = torch.meshgrid(torch.arange(size), torch.arange(size), indexing="ij")
        y = y.float()
        x = x.float()
        cx = size / 2
        cy = size / 2
        r = torch.sqrt((x - cx) ** 2 + (y - cy) ** 2) + 1e-6
        theta = torch.atan2(y - cy, x - cx)
        spiral = torch.sin(2.5 * theta + 1.1 * torch.log(r))
        return (1.0 + 0.05 * spiral).view(1, 1, size, size).to(device)

    def forward(self, obs, commit_scale=3.0, l_value=0.6):
        phi = self.encoder(obs)
        z_d = self.damage_init(obs)

        gc = torch.exp(self.log_gc) * self.spiral_bias
        stiff = F.softplus(self.qdmn_log_stiff) + 0.10

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        charge = obs[:, 2:3]
        dir_x = obs[:, 5:6]
        dir_y = obs[:, 6:7]
        endpoints = source + goal

        for _ in range(self.inner_steps):
            d = torch.sigmoid(commit_scale * z_d)

            phi_x = grad_x(phi)
            phi_y = grad_y(phi)
            d_x = grad_x(d)
            d_y = grad_y(d)
            phi_grad_mag = torch.sqrt(phi_x**2 + phi_y**2 + 1e-6)

            elastic = 0.5 * (
                stiff[0] * phi_y**2 +
                stiff[1] * (-phi_y)**2 +
                stiff[2] * phi_x**2 +
                stiff[3] * (-phi_x)**2
            )

            degraded = (1.0 - d) ** 2 * elastic

            fracture = gc * (
                d**2 / (2.0 * l_value) +
                0.5 * l_value * (d_x**2 + d_y**2)
            )

            well = 3.0 * d**2 * (1.0 - d)**2

            bridge_pressure = 0.12 * endpoints + 0.08 * charge.abs()
            direction_bias = 0.06 * (dir_x.abs() + dir_y.abs())

            d_drive = (
                bridge_pressure
                + direction_bias
                + 0.35 * phi_grad_mag
                + 0.08 * degraded
                - gc * (
                    d / l_value
                    + 0.22 * laplacian(d)
                    + 2.0 * d * (1.0 - d) * (1.0 - 2.0 * d)
                )
            )

            phi_drive = (
                0.55 * laplacian(phi)
                + 0.65 * charge
                + 0.25 * endpoints
                + 0.15 * (dir_x + dir_y)
                - 0.06 * phi
                - 0.10 * d * phi
            )

            z_d = z_d + 0.15 * torch.tanh(d_drive)
            phi = phi + 0.04 * torch.tanh(phi_drive)

        d = torch.sigmoid(commit_scale * z_d)

        # Only physics state in the head
        logits = 8.0 * (d - 0.5) + 0.25 * self.readout(torch.cat([d, phi], dim=1))
        return logits, d, phi

# ======================
# Train
# ======================
model = PF2V_NoBypass(size=64, inner_steps=7).to(device)
optimizer = torch.optim.Adam(model.parameters(), lr=8e-4)

max_epochs = 300

for epoch in range(1, max_epochs + 1):
    model.train()

    t = (epoch - 1) / (max_epochs - 1)
    commit_scale = 2.0 + 8.0 * t     # start fuzzy, end sharp
    l_value = 0.75 - 0.35 * t        # shrink crack width over time
    target_sigma = 2.5 - 1.0 * t     # curriculum on the target corridor

    obs, target = make_batch(batch_size=8, size=64, device=device, target_sigma=target_sigma)
    logits, d, phi = model(obs, commit_scale=commit_scale, l_value=l_value)

    pos = target.sum().clamp_min(1.0)
    neg = target.numel() - pos
    pos_weight = (neg / pos).clamp(1.0, 30.0)

    bce_main = F.binary_cross_entropy_with_logits(logits, target, pos_weight=pos_weight)
    bce_latent = F.binary_cross_entropy(d.clamp(1e-4, 1 - 1e-4), target)
    dice = dice_loss_from_logits(logits, target)

    prob = torch.sigmoid(logits)
    tv = (prob[:, :, :, 1:] - prob[:, :, :, :-1]).abs().mean() + (prob[:, :, 1:, :] - prob[:, :, :-1, :]).abs().mean()

    edge_loss = (
        F.mse_loss(grad_x(prob), grad_x(target)) +
        F.mse_loss(grad_y(prob), grad_y(target))
    )
    lap_loss = F.mse_loss(laplacian(prob), laplacian(target))
    commitment = (prob * (1.0 - prob)).mean()
    outside_loss = ((1.0 - target) * prob).mean()

    loss = (
        1.0 * bce_main +
        0.12 * bce_latent +
        0.70 * dice +
        0.22 * edge_loss +
        0.12 * lap_loss +
        0.12 * commitment +
        0.08 * outside_loss +
        0.02 * tv
    )

    optimizer.zero_grad()
    loss.backward()
    torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
    optimizer.step()

    if epoch == 1 or epoch % 25 == 0:
        model.eval()
        with torch.no_grad():
            logits_eval, d_eval, phi_eval = model(obs, commit_scale=commit_scale, l_value=l_value)
            prob_eval = torch.sigmoid(logits_eval)

            soft_iou = soft_iou_from_logits(logits_eval, target).item()
            hard_iou = hard_iou_from_logits(logits_eval, target, thresh=0.5).item()

            pred_mass = prob_eval.mean().item()
            target_mass = target.mean().item()
            sharpness = (prob_eval * (1.0 - prob_eval)).mean().item()
            connectivity = connectivity_estimate(prob_eval, thresh=0.5)

            source = obs[:, 0:1]
            goal = obs[:, 1:2]
            source_hit = ((prob_eval * source).sum() / (source.sum() + 1e-6)).item()
            goal_hit = ((prob_eval * goal).sum() / (goal.sum() + 1e-6)).item()

            total_active = (prob_eval > 0.5).float().sum().item()
            target_active = (target > 0.5).float().sum().item()
            compactness = target_active / (total_active + 1e-6)

            d_x = grad_x(d_eval)
            d_y = grad_y(d_eval)
            fracture_energy = (d_x.pow(2).mean() + d_y.pow(2).mean()).item()

            phi_x = grad_x(phi_eval)
            phi_y = grad_y(phi_eval)
            phi_flow = (phi_x.pow(2).mean() + phi_y.pow(2).mean()).item()

            blob_score = pred_mass / (fracture_energy + 1e-6)

        print(
            f"epoch {epoch:03d} | loss {loss.item():.4f} | "
            f"bce {bce_main.item():.4f} | latent {bce_latent.item():.4f} | "
            f"dice {dice.item():.4f} | edge {edge_loss.item():.4f} | lap {lap_loss.item():.4f} | "
            f"soft_iou {soft_iou:.4f} | hard_iou {hard_iou:.4f}"
        )
        print(
            f"  mass={pred_mass:.4f} target_mass={target_mass:.4f} "
            f"sharpness={sharpness:.4f} connectivity={connectivity:.4f} "
            f"compactness={compactness:.4f}"
        )
        print(
            f"  source_hit={source_hit:.4f} goal_hit={goal_hit:.4f} "
            f"fracture_energy={fracture_energy:.6f} phi_flow={phi_flow:.6f} "
            f"blob_score={blob_score:.4f}"
        )
        print("-" * 88)

print("training done")

# ======================
# Final text-only diagnostic sample
# ======================
model.eval()
with torch.no_grad():
    obs, target = make_batch(batch_size=1, size=64, device=device, target_sigma=1.4)
    logits, d, phi = model(obs, commit_scale=10.0, l_value=0.40)
    prob = torch.sigmoid(logits)

soft_iou = soft_iou_from_logits(logits, target).item()
hard_iou = hard_iou_from_logits(logits, target, thresh=0.5).item()

pred = prob[0, 0].detach().cpu().numpy()
tgt = target[0, 0].detach().cpu().numpy()
latent = d[0, 0].detach().cpu().numpy()
phi_np = phi[0, 0].detach().cpu().numpy()
source_np = obs[0, 0].detach().cpu().numpy()
goal_np = obs[0, 1].detach().cpu().numpy()

sy, sx = np.unravel_index(np.argmax(source_np), source_np.shape)
gy, gx = np.unravel_index(np.argmax(goal_np), goal_np.shape)

binary = (pred > 0.5).astype(np.uint8)
horizontal_links = (binary[:, 1:] * binary[:, :-1]).mean()
vertical_links = ((binary[1:, :] * binary[:-1, :]).mean() if binary.shape[0] > 1 else 0.0)
connectivity = float(horizontal_links + vertical_links)

mass = float(pred.mean())
sharpness = float((pred * (1.0 - pred)).mean())
fracture_energy = float((grad_x(torch.tensor(latent[None, None], device=device)).pow(2).mean() +
                         grad_y(torch.tensor(latent[None, None], device=device)).pow(2).mean()).item())
blob_score = mass / (fracture_energy + 1e-6)

print("\nFINAL SAMPLE DIAGNOSTICS")
print(f"soft_iou            : {soft_iou:.4f}")
print(f"hard_iou            : {hard_iou:.4f}")
print(f"mass                : {mass:.4f}")
print(f"sharpness           : {sharpness:.4f}")
print(f"connectivity        : {connectivity:.4f}")
print(f"fracture_energy     : {fracture_energy:.6f}")
print(f"blob_score          : {blob_score:.4f}")
print(f"source_peak         : ({sx}, {sy})")
print(f"goal_peak           : ({gx}, {gy})")
print(f"pred_at_source      : {pred[sy, sx]:.4f}")
print(f"pred_at_goal        : {pred[gy, gx]:.4f}")
print(f"d_at_source         : {latent[sy, sx]:.4f}")
print(f"d_at_goal           : {latent[gy, gx]:.4f}")

# ======================
# Single 2x2 figure
# ======================
inp = (obs[0, 0] + obs[0, 1]).detach().cpu().numpy()

fig, axes = plt.subplots(2, 2, figsize=(10, 10))

axes[0, 0].imshow(inp, cmap="gray")
axes[0, 0].set_title("Input: Start + Goal")
axes[0, 0].axis("off")

axes[0, 1].imshow(tgt, cmap="hot", vmin=0, vmax=1)
