import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import numpy as np

# ======================
# Setup
# ======================
torch.manual_seed(42)
random.seed(42)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# ======================
# Helpers
# ======================
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

def gaussian_blob(size, x0, y0, sigma=1.25, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    dist2 = (x.float() - x0) ** 2 + (y.float() - y0) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def soft_line_mask(size, x0, y0, x1, y1, sigma=1.6, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    x = x.float()
    y = y.float()

    x0 = float(x0)
    y0 = float(y0)
    x1 = float(x1)
    y1 = float(y1)

    vx = x1 - x0
    vy = y1 - y0
    denom = vx * vx + vy * vy + 1e-6

    t = ((x - x0) * vx + (y - y0) * vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px) ** 2 + (y - py) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def make_batch(batch_size=8, size=64, device="cpu", target_sigma=1.6):
    obs = torch.zeros(batch_size, 7, size, size, device=device)
    target = torch.zeros(batch_size, 1, size, size, device=device)

    yy, xx = torch.meshgrid(
        torch.linspace(-1, 1, size, device=device),
        torch.linspace(-1, 1, size, device=device),
        indexing="ij"
    )
    coord_x = xx.unsqueeze(0).unsqueeze(0)
    coord_y = yy.unsqueeze(0).unsqueeze(0)

    for b in range(batch_size):
        x0 = random.randint(8, size - 9)
        y0 = random.randint(8, size - 9)
        x1 = random.randint(8, size - 9)
        y1 = random.randint(8, size - 9)

        source = gaussian_blob(size, x0, y0, sigma=1.25, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.25, device=device)
        charge = source - goal
        target_map = soft_line_mask(size, x0, y0, x1, y1, sigma=target_sigma, device=device)

        dx = float(x1 - x0)
        dy = float(y1 - y0)
        norm = (dx * dx + dy * dy) ** 0.5 + 1e-6
        dir_x = torch.full((1, 1, size, size), dx / norm, device=device)
        dir_y = torch.full((1, 1, size, size), dy / norm, device=device)

        obs[b:b+1, 0:1] = source
        obs[b:b+1, 1:2] = goal
        obs[b:b+1, 2:3] = charge
        obs[b:b+1, 3:4] = coord_x
        obs[b:b+1, 4:5] = coord_y
        obs[b:b+1, 5:6] = dir_x
        obs[b:b+1, 6:7] = dir_y
        target[b:b+1] = target_map

    return obs, target

def soft_iou_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def hard_iou_from_logits(logits, target, thresh=0.5, eps=1e-6):
    prob = torch.sigmoid(logits)
    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()
    inter = (pred * tgt).sum(dim=(1, 2, 3))
    union = ((pred + tgt) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    dice = 1.0 - (2.0 * inter + eps) / (union + eps)
    return dice.mean()

def connectivity_estimate(prob, thresh=0.5):
    binary = (prob > thresh).float()
    horizontal_links = (binary[:, :, :, 1:] * binary[:, :, :, :-1]).mean().item()
    vertical_links = (binary[:, :, 1:, :] * binary[:, :, :-1, :]).mean().item()
    return horizontal_links + vertical_links

def eval_metrics_from_prob(prob, target, obs):
    soft_iou = ((prob * target).sum(dim=(1,2,3)) /
                ((prob + target - prob * target).sum(dim=(1,2,3)) + 1e-6)).mean().item()

    binary = (prob > 0.5).float()
    tgt_bin = (target > 0.5).float()

    inter = (binary * tgt_bin).sum(dim=(1,2,3))
    union = ((binary + tgt_bin) > 0).float().sum(dim=(1,2,3))
    hard_iou = ((inter + 1e-6) / (union + 1e-6)).mean().item()

    mass = prob.mean().item()
    sharpness = (prob * (1.0 - prob)).mean().item()
    connectivity = connectivity_estimate(prob, thresh=0.5)

    source = obs[:, 0:1]
    goal = obs[:, 1:2]
    source_hit = ((prob * source).sum() / (source.sum() + 1e-6)).item()
    goal_hit = ((prob * goal).sum() / (goal.sum() + 1e-6)).item()

    total_active = (prob > 0.5).float().sum().item()
    target_active = (target > 0.5).float().sum().item()
    compactness = target_active / (total_active + 1e-6)

    return {
        "soft_iou": soft_iou,
        "hard_iou": hard_iou,
        "mass": mass,
        "sharpness": sharpness,
        "connectivity": connectivity,
        "source_hit": source_hit,
        "goal_hit": goal_hit,
        "compactness": compactness,
    }

def print_metrics_table(rows, title):
    cols = ["model", "soft_iou", "hard_iou", "mass", "sharpness", "connectivity", "source_hit", "goal_hit", "compactness"]
    print("\n" + "=" * 110)
    print(title)
    print("=" * 110)
    header = f"{'model':<12} {'soft_iou':>9} {'hard_iou':>9} {'mass':>9} {'sharpness':>10} {'connectivity':>13} {'source_hit':>11} {'goal_hit':>9} {'compactness':>12}"
    print(header)
    print("-" * len(header))
    for r in rows:
        print(
            f"{r['model']:<12} "
            f"{r['soft_iou']:>9.4f} {r['hard_iou']:>9.4f} {r['mass']:>9.4f} {r['sharpness']:>10.4f} "
            f"{r['connectivity']:>13.4f} {r['source_hit']:>11.4f} {r['goal_hit']:>9.4f} {r['compactness']:>12.4f}"
        )
    print("=" * 110)

# ======================
# PF²V-WM model
# ======================
class PF2V_NoBypass(nn.Module):
    def __init__(self, size=64, inner_steps=7):
        super().__init__()
        self.size = size
        self.inner_steps = inner_steps

        self.encoder = nn.Sequential(
            nn.Conv2d(7, 32, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(32, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.damage_init = nn.Sequential(
            nn.Conv2d(7, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.qdmn_log_stiff = nn.Parameter(torch.zeros(4))
        self.log_gc = nn.Parameter(torch.tensor(-0.8))
        self.register_buffer("spiral_bias", self._make_spiral(size))

        self.readout = nn.Sequential(
            nn.Conv2d(2, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 1),
        )

    def _make_spiral(self, size):
        y, x = torch.meshgrid(torch.arange(size), torch.arange(size), indexing="ij")
        y = y.float()
        x = x.float()
        cx = size / 2
        cy = size / 2
        r = torch.sqrt((x - cx) ** 2 + (y - cy) ** 2) + 1e-6
        theta = torch.atan2(y - cy, x - cx)
        spiral = torch.sin(2.5 * theta + 1.1 * torch.log(r))
        return (1.0 + 0.05 * spiral).view(1, 1, size, size).to(device)

    def forward(self, obs, commit_scale=3.0, l_value=0.6):
        phi = self.encoder(obs)
        z_d = self.damage_init(obs)

        gc = torch.exp(self.log_gc) * self.spiral_bias
        stiff = F.softplus(self.qdmn_log_stiff) + 0.10

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        charge = obs[:, 2:3]
        dir_x = obs[:, 5:6]
        dir_y = obs[:, 6:7]
        endpoints = source + goal

        for _ in range(self.inner_steps):
            d = torch.sigmoid(commit_scale * z_d)

            phi_x = grad_x(phi)
            phi_y = grad_y(phi)
            d_x = grad_x(d)
            d_y = grad_y(d)
            phi_grad_mag = torch.sqrt(phi_x**2 + phi_y**2 + 1e-6)

            elastic = 0.5 * (
                stiff[0] * phi_y**2 +
                stiff[1] * (-phi_y)**2 +
                stiff[2] * phi_x**2 +
                stiff[3] * (-phi_x)**2
            )

            degraded = (1.0 - d) ** 2 * elastic

            fracture = gc * (
                d**2 / (2.0 * l_value) +
                0.5 * l_value * (d_x**2 + d_y**2)
            )

            bridge_pressure = 0.12 * endpoints + 0.08 * charge.abs()
            direction_bias = 0.06 * (dir_x.abs() + dir_y.abs())

            d_drive = (
                bridge_pressure
                + direction_bias
                + 0.35 * phi_grad_mag
                + 0.08 * degraded
                - gc * (
                    d / l_value
                    + 0.22 * laplacian(d)
                    + 2.0 * d * (1.0 - d) * (1.0 - 2.0 * d)
                )
            )

            phi_drive = (
                0.55 * laplacian(phi)
                + 0.65 * charge
                + 0.25 * endpoints
                + 0.15 * (dir_x + dir_y)
                - 0.06 * phi
                - 0.10 * d * phi
            )

            z_d = z_d + 0.15 * torch.tanh(d_drive)
            phi = phi + 0.04 * torch.tanh(phi_drive)

        d = torch.sigmoid(commit_scale * z_d)
        logits = 8.0 * (d - 0.5) + 0.25 * self.readout(torch.cat([d, phi], dim=1))
        return logits, d, phi

# ======================
# Baseline CNN
# ======================
class PlainCNN(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(
            nn.Conv2d(7, 32, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(32, 32, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(32, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 1),
        )

    def forward(self, obs):
        return self.net(obs)

# ======================
# Training / evaluation helpers
# ======================
def train_pf2v(model, epochs=100, batch_size=8):
    opt = torch.optim.Adam(model.parameters(), lr=8e-4)
    max_epochs = epochs

    for epoch in range(1, max_epochs + 1):
        model.train()

        t = (epoch - 1) / (max_epochs - 1)
        commit_scale = 2.0 + 8.0 * t
        l_value = 0.75 - 0.35 * t
        target_sigma = 2.5 - 1.0 * t

        obs, target = make_batch(batch_size=batch_size, size=64, device=device, target_sigma=target_sigma)
        logits, d, phi = model(obs, commit_scale=commit_scale, l_value=l_value)

        pos = target.sum().clamp_min(1.0)
        neg = target.numel() - pos
        pos_weight = (neg / pos).clamp(1.0, 30.0)

        bce_main = F.binary_cross_entropy_with_logits(logits, target, pos_weight=pos_weight)
        bce_latent = F.binary_cross_entropy(d.clamp(1e-4, 1 - 1e-4), target)
        dice = dice_loss_from_logits(logits, target)

        prob = torch.sigmoid(logits)
        tv = (prob[:, :, :, 1:] - prob[:, :, :, :-1]).abs().mean() + (prob[:, :, 1:, :] - prob[:, :, :-1, :]).abs().mean()

        edge_loss = (
            F.mse_loss(grad_x(prob), grad_x(target)) +
            F.mse_loss(grad_y(prob), grad_y(target))
        )
        lap_loss = F.mse_loss(laplacian(prob), laplacian(target))
        commitment = (prob * (1.0 - prob)).mean()
        outside_loss = ((1.0 - target) * prob).mean()

        loss = (
            1.0 * bce_main +
            0.12 * bce_latent +
            0.70 * dice +
            0.22 * edge_loss +
            0.12 * lap_loss +
            0.12 * commitment +
            0.08 * outside_loss +
            0.02 * tv
        )

        opt.zero_grad()
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
        opt.step()

        if epoch == 1 or epoch % 25 == 0:
            model.eval()
            with torch.no_grad():
                logits_eval, _, _ = model(obs, commit_scale=commit_scale, l_value=l_value)
                prob_eval = torch.sigmoid(logits_eval)
                m = eval_metrics_from_prob(prob_eval, target, obs)

            print(
                f"[PF²V] epoch {epoch:03d} | loss {loss.item():.4f} | "
                f"soft_iou {m['soft_iou']:.4f} | hard_iou {m['hard_iou']:.4f} | "
                f"mass {m['mass']:.4f} | sharpness {m['sharpness']:.4f} | "
                f"connectivity {m['connectivity']:.4f} | compactness {m['compactness']:.4f}"
            )

    return model

def train_cnn(model, epochs=100, batch_size=8):
    opt = torch.optim.Adam(model.parameters(), lr=8e-4)
    max_epochs = epochs

    for epoch in range(1, max_epochs + 1):
        model.train()

        t = (epoch - 1) / (max_epochs - 1)
        target_sigma = 2.5 - 1.0 * t

        obs, target = make_batch(batch_size=batch_size, size=64, device=device, target_sigma=target_sigma)
        logits = model(obs)
        prob = torch.sigmoid(logits)

        pos = target.sum().clamp_min(1.0)
        neg = target.numel() - pos
        pos_weight = (neg / pos).clamp(1.0, 30.0)

        bce_main = F.binary_cross_entropy_with_logits(logits, target, pos_weight=pos_weight)
        dice = dice_loss_from_logits(logits, target)

        tv = (prob[:, :, :, 1:] - prob[:, :, :, :-1]).abs().mean() + (prob[:, :, 1:, :] - prob[:, :, :-1, :]).abs().mean()
        edge_loss = (
            F.mse_loss(grad_x(prob), grad_x(target)) +
            F.mse_loss(grad_y(prob), grad_y(target))
        )
        lap_loss = F.mse_loss(laplacian(prob), laplacian(target))
        commitment = (prob * (1.0 - prob)).mean()
        outside_loss = ((1.0 - target) * prob).mean()

        loss = (
            1.0 * bce_main +
            0.70 * dice +
            0.22 * edge_loss +
            0.12 * lap_loss +
            0.12 * commitment +
            0.08 * outside_loss +
            0.02 * tv
        )

        opt.zero_grad()
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
        opt.step()

        if epoch == 1 or epoch % 25 == 0:
            model.eval()
            with torch.no_grad():
                logits_eval = model(obs)
                prob_eval = torch.sigmoid(logits_eval)
                m = eval_metrics_from_prob(prob_eval, target, obs)

            print(
                f"[CNN ] epoch {epoch:03d} | loss {loss.item():.4f} | "
                f"soft_iou {m['soft_iou']:.4f} | hard_iou {m['hard_iou']:.4f} | "
                f"mass {m['mass']:.4f} | sharpness {m['sharpness']:.4f} | "
                f"connectivity {m['connectivity']:.4f} | compactness {m['compactness']:.4f}"
            )

    return model

def evaluate_model(model, is_pf2v=False):
    model.eval()
    with torch.no_grad():
        obs, target = make_batch(batch_size=32, size=64, device=device, target_sigma=1.4)
        if is_pf2v:
            logits, d, phi = model(obs, commit_scale=10.0, l_value=0.40)
        else:
            logits = model(obs)
            d = None
            phi = None
        prob = torch.sigmoid(logits)

    m = eval_metrics_from_prob(prob, target, obs)

    source = obs[:, 0:1]
    goal = obs[:, 1:2]
    m["source_hit"] = ((prob * source).sum() / (source.sum() + 1e-6)).item()
    m["goal_hit"] = ((prob * goal).sum() / (goal.sum() + 1e-6)).item()

    if is_pf2v:
        d_x = grad_x(d)
        d_y = grad_y(d)
        phi_x = grad_x(phi)
        phi_y = grad_y(phi)
        m["fracture_energy"] = (d_x.pow(2).mean() + d_y.pow(2).mean()).item()
        m["phi_flow"] = (phi_x.pow(2).mean() + phi_y.pow(2).mean()).item()
        m["latent_mass"] = d.mean().item()
    else:
        m["fracture_energy"] = (grad_x(prob).pow(2).mean() + grad_y(prob).pow(2).mean()).item()
        m["phi_flow"] = float("nan")
        m["latent_mass"] = float("nan")

    return m, obs, target, prob, d

# ======================
# Train both models
# ======================
pf2v = PF2V_NoBypass(size=64, inner_steps=7).to(device)
cnn = PlainCNN().to(device)

print("\nTraining PF²V-WM...")
pf2v = train_pf2v(pf2v, epochs=100, batch_size=8)

print("\nTraining baseline CNN...")
cnn = train_cnn(cnn, epochs=100, batch_size=8)

# ======================
# Final evaluation
# ======================
pf2v_metrics, obs_pf, target_pf, prob_pf, d_pf = evaluate_model(pf2v, is_pf2v=True)
cnn_metrics, obs_cnn, target_cnn, prob_cnn, _ = evaluate_model(cnn, is_pf2v=False)

# Comparison table
rows = [
    {"model": "PF2V", **pf2v_metrics},
    {"model": "CNN", **cnn_metrics},
]

print_metrics_table(rows, title="FINAL HOLD-OUT COMPARISON (higher is better for IoU / connectivity / compactness; lower is better for sharpness / mass / blob-like spread)")

# Simple verdict
better_soft = "PF2V" if pf2v_metrics["soft_iou"] > cnn_metrics["soft_iou"] else "CNN"
better_hard = "PF2V" if pf2v_metrics["hard_iou"] > cnn_metrics["hard_iou"] else "CNN"
better_connect = "PF2V" if pf2v_metrics["connectivity"] > cnn_metrics["connectivity"] else "CNN"
better_compact = "PF2V" if pf2v_metrics["compactness"] > cnn_metrics["compactness"] else "CNN"
better_sharp = "PF2V" if pf2v_metrics["sharpness"] < cnn_metrics["sharpness"] else "CNN"

print("\nVERDICT SUMMARY")
