import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import numpy as np
import matplotlib.pyplot as plt

# ============================================================
# PF²V-WM obstacle-bending stress test
# What it measures:
#   - route follow vs straight-line temptation
#   - obstacle avoidance
#   - sharpness vs thickness
#   - effect of core / spread / length-scale / obstacle push
# ============================================================

# ======================
# Setup
# ======================
torch.manual_seed(42)
random.seed(42)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# ======================
# Helpers
# ======================
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

def gaussian_blob(size, x0, y0, sigma=1.25, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    dist2 = (x.float() - x0) ** 2 + (y.float() - y0) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def soft_line_mask(size, x0, y0, x1, y1, sigma=1.6, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    x = x.float()
    y = y.float()

    x0 = float(x0)
    y0 = float(y0)
    x1 = float(x1)
    y1 = float(y1)

    vx = x1 - x0
    vy = y1 - y0
    denom = vx * vx + vy * vy + 1e-6

    t = ((x - x0) * vx + (y - y0) * vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px) ** 2 + (y - py) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def make_batch(batch_size=8, size=64, device="cpu", corridor_sigma=1.6, core_sigma=0.5, obstacle_sigma=5.0):
    # 8 channels:
    # 0 source blob
    # 1 goal blob
    # 2 charge = source - goal
    # 3 x coordinate
    # 4 y coordinate
    # 5 direction x from source to goal
    # 6 direction y from source to goal
    # 7 obstacle field
    obs = torch.zeros(batch_size, 8, size, size, device=device)
    corridor_target = torch.zeros(batch_size, 1, size, size, device=device)
    core_target = torch.zeros(batch_size, 1, size, size, device=device)
    obstacle_mask = torch.zeros(batch_size, 1, size, size, device=device)

    start_xy = torch.zeros(batch_size, 2, device=device)
    waypoint_xy = torch.zeros(batch_size, 2, device=device)
    goal_xy = torch.zeros(batch_size, 2, device=device)

    yy, xx = torch.meshgrid(
        torch.linspace(-1, 1, size, device=device),
        torch.linspace(-1, 1, size, device=device),
        indexing="ij"
    )
    coord_x = xx.unsqueeze(0).unsqueeze(0)
    coord_y = yy.unsqueeze(0).unsqueeze(0)

    for b in range(batch_size):
        x0 = random.randint(8, size - 9)
        y0 = random.randint(8, size - 9)
        x1 = random.randint(8, size - 9)
        y1 = random.randint(8, size - 9)

        # Route bends around a midpoint obstacle using a deterministic side choice
        dx = float(x1 - x0)
        dy = float(y1 - y0)
        dist = (dx * dx + dy * dy) ** 0.5 + 1e-6
        ux = -dy / dist
        uy = dx / dist
        sign = 1.0 if (y1 >= y0) else -1.0
        offset_px = max(8.0, 0.32 * dist)

        mx = 0.5 * (x0 + x1)
        my = 0.5 * (y0 + y1)

        wx = np.clip(mx + sign * ux * offset_px, 6, size - 7)
        wy = np.clip(my + sign * uy * offset_px, 6, size - 7)

        source = gaussian_blob(size, x0, y0, sigma=1.25, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.25, device=device)
        charge = source - goal

        route_1 = soft_line_mask(size, x0, y0, wx, wy, sigma=corridor_sigma, device=device)
        route_2 = soft_line_mask(size, wx, wy, x1, y1, sigma=corridor_sigma, device=device)
        core_1 = soft_line_mask(size, x0, y0, wx, wy, sigma=core_sigma, device=device)
        core_2 = soft_line_mask(size, wx, wy, x1, y1, sigma=core_sigma, device=device)

        corridor = torch.maximum(route_1, route_2)
        core = torch.maximum(core_1, core_2)

        obstacle = gaussian_blob(size, mx, my, sigma=obstacle_sigma, device=device)
        obstacle = obstacle / obstacle.max().clamp_min(1e-6)

        dir_x = torch.full((1, 1, size, size), dx / dist, device=device)
        dir_y = torch.full((1, 1, size, size), dy / dist, device=device)

        obs[b:b+1, 0:1] = source
        obs[b:b+1, 1:2] = goal
        obs[b:b+1, 2:3] = charge
        obs[b:b+1, 3:4] = coord_x
        obs[b:b+1, 4:5] = coord_y
        obs[b:b+1, 5:6] = dir_x
        obs[b:b+1, 6:7] = dir_y
        obs[b:b+1, 7:8] = obstacle

        corridor_target[b:b+1] = corridor
        core_target[b:b+1] = core
        obstacle_mask[b:b+1] = obstacle

        start_xy[b] = torch.tensor([2.0 * x0 / (size - 1) - 1.0, 2.0 * y0 / (size - 1) - 1.0], device=device)
        waypoint_xy[b] = torch.tensor([2.0 * wx / (size - 1) - 1.0, 2.0 * wy / (size - 1) - 1.0], device=device)
        goal_xy[b] = torch.tensor([2.0 * x1 / (size - 1) - 1.0, 2.0 * y1 / (size - 1) - 1.0], device=device)

    return obs, corridor_target, core_target, obstacle_mask, start_xy, waypoint_xy, goal_xy

def soft_iou_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def hard_iou_from_logits(logits, target, thresh=0.5, eps=1e-6):
    prob = torch.sigmoid(logits)
    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()
    inter = (pred * tgt).sum(dim=(1, 2, 3))
    union = ((pred + tgt) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_logits(logits, target, eps=1e-6):
    prob = torch.sigmoid(logits)
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    dice = 1.0 - (2.0 * inter + eps) / (union + eps)
    return dice.mean()

def connectivity_estimate(prob, thresh=0.5):
    binary = (prob > thresh).float()
    horizontal_links = (binary[:, :, :, 1:] * binary[:, :, :, :-1]).mean().item()
    vertical_links = (binary[:, :, 1:, :] * binary[:, :, :-1, :]).mean().item()
    return horizontal_links + vertical_links

def sample_segment_probs(prob, start_xy, goal_xy, num=48, offset=0.0):
    B = prob.shape[0]
    t = torch.linspace(0, 1, num, device=prob.device).view(1, num, 1)

    start = start_xy.view(B, 1, 2)
    goal = goal_xy.view(B, 1, 2)

    direction = goal - start
    norm = torch.linalg.norm(direction, dim=-1, keepdim=True).clamp_min(1e-6)
    unit = direction / norm
    perp = torch.cat([-unit[..., 1:2], unit[..., 0:1]], dim=-1)

    pts = start * (1.0 - t) + goal * t + offset * perp
    pts = pts.clamp(-1.0, 1.0)

    grid = pts.view(B, num, 1, 2)
    sampled = F.grid_sample(prob, grid, mode="bilinear", padding_mode="zeros", align_corners=True)
    return sampled[:, 0, :, 0]

def sample_polyline_probs(prob, p0, p1, p2, num_per_segment=24, offset=0.0):
    a = sample_segment_probs(prob, p0, p1, num=num_per_segment, offset=offset)
    b = sample_segment_probs(prob, p1, p2, num=num_per_segment, offset=offset)
    return torch.cat([a, b], dim=1)

def route_metrics(prob, start_xy, waypoint_xy, goal_xy, obstacle_mask=None):
    direct = sample_segment_probs(prob, start_xy, goal_xy, num=48, offset=0.0)
    route = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=0.0)
    side_p = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=0.08)
    side_m = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=-0.08)

    direct_mean = direct.mean().item()
    route_mean = route.mean().item()
    route_gap = (route < 0.5).float().mean().item()
    route_ratio = route_mean / (direct_mean + 1e-6)

    side_mean = 0.5 * (side_p.mean().item() + side_m.mean().item())
    side_max = max(side_p.max().item(), side_m.max().item())

    out = {
        "direct_mean": direct_mean,
        "route_mean": route_mean,
        "route_gap": route_gap,
        "route_ratio": route_ratio,
        "side_mean": side_mean,
        "side_max": side_max,
    }

    if obstacle_mask is not None:
        out["obstacle_overlap"] = ((prob * obstacle_mask).sum() / (obstacle_mask.sum() + 1e-6)).item()
    else:
        out["obstacle_overlap"] = float("nan")

    return out

def eval_metrics_from_prob(prob, corridor_target, core_target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy, core_prob=None, spread_prob=None):
    soft_iou = soft_iou_from_logits(torch.logit(prob.clamp(1e-4, 1 - 1e-4)), corridor_target).item()
    hard_iou = hard_iou_from_logits(torch.logit(prob.clamp(1e-4, 1 - 1e-4)), corridor_target).item()

    mass = prob.mean().item()
    sharpness = (prob * (1.0 - prob)).mean().item()
    conn = connectivity_estimate(prob, thresh=0.5)

    source = obs[:, 0:1]
    goal = obs[:, 1:2]
    source_hit = ((prob * source).sum() / (source.sum() + 1e-6)).item()
    goal_hit = ((prob * goal).sum() / (goal.sum() + 1e-6)).item()

    route = route_metrics(prob, start_xy, waypoint_xy, goal_xy, obstacle_mask=obstacle_mask)

    out = {
        "soft_iou": soft_iou,
        "hard_iou": hard_iou,
        "mass": mass,
        "sharpness": sharpness,
        "connectivity": conn,
        "source_hit": source_hit,
        "goal_hit": goal_hit,
        **route,
    }

    if core_prob is not None:
        core_route = route_metrics(core_prob, start_xy, waypoint_xy, goal_xy)
        out["core_route_mean"] = core_route["route_mean"]
        out["core_route_gap"] = core_route["route_gap"]
        out["core_route_ratio"] = core_route["route_ratio"]
        out["core_mass"] = core_prob.mean().item()
        out["core_sharpness"] = (core_prob * (1.0 - core_prob)).mean().item()

    if spread_prob is not None:
        out["spread_mass"] = spread_prob.mean().item()
        out["spread_obstacle"] = ((spread_prob * obstacle_mask).sum() / (obstacle_mask.sum() + 1e-6)).item()

    return out

def print_metrics_table(rows, title):
    print("\n" + "=" * 146)
    print(title)
    print("=" * 146)
    header = (
        f"{'setting':<18} "
        f"{'soft_iou':>8} {'hard_iou':>8} {'route_m':>8} {'direct_m':>8} "
        f"{'ratio':>8} {'obs_ov':>8} {'gap':>7} {'sharp':>8} {'conn':>8} {'core_rt':>8}"
    )
    print(header)
    print("-" * len(header))
    for r in rows:
        print(
            f"{r['setting']:<18} "
            f"{r['soft_iou']:>8.4f} {r['hard_iou']:>8.4f} {r['route_mean']:>8.4f} {r['direct_mean']:>8.4f} "
            f"{r['route_ratio']:>8.4f} {r['obstacle_overlap']:>8.4f} {r['route_gap']:>7.4f} "
            f"{r['sharpness']:>8.4f} {r['connectivity']:>8.4f} {r.get('core_route_ratio', float('nan')):>8.4f}"
        )
    print("=" * 146)

def print_ranked(rows, key, reverse=True, topk=5):
    ranked = sorted(rows, key=lambda r: r[key], reverse=reverse)[:topk]
    print(f"\nTop {topk} by {key} ({'high' if reverse else 'low'} is better):")
    for r in ranked:
        print(
            f"  {r['setting']:<18} | {key}={r[key]:.4f} | hard_iou={r['hard_iou']:.4f} | "
            f"route_ratio={r['route_ratio']:.4f} | obs_ov={r['obstacle_overlap']:.4f} | conn={r['connectivity']:.4f}"
        )

# ======================
# Model
# ======================
class PF2V_ObstacleSplit(nn.Module):
    def __init__(self, size=64, inner_steps=6):
        super().__init__()
        self.size = size
        self.inner_steps = inner_steps

        self.encoder = nn.Sequential(
            nn.Conv2d(8, 32, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(32, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.core_init = nn.Sequential(
            nn.Conv2d(8, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.spread_init = nn.Sequential(
            nn.Conv2d(8, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 3, padding=1),
        )

        self.qdmn_log_stiff = nn.Parameter(torch.zeros(4))
        self.log_gc = nn.Parameter(torch.tensor(-0.8))
        self.register_buffer("spiral_bias", self._make_spiral(size))

        self.readout = nn.Sequential(
            nn.Conv2d(3, 16, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(16, 1, 1),
        )

    def _make_spiral(self, size):
        y, x = torch.meshgrid(torch.arange(size), torch.arange(size), indexing="ij")
        y = y.float()
        x = x.float()
        cx = size / 2
        cy = size / 2
        r = torch.sqrt((x - cx) ** 2 + (y - cy) ** 2) + 1e-6
        theta = torch.atan2(y - cy, x - cx)
        spiral = torch.sin(2.5 * theta + 1.1 * torch.log(r))
        return (1.0 + 0.05 * spiral).view(1, 1, size, size).to(device)

    def forward(
        self,
        obs,
        core_scale=4.0,
        spread_scale=3.0,
        l_value=0.45,
        spiral_scale=1.0,
        qdmn_scale=1.0,
        obstacle_push=0.35,
        bridge_scale=0.12,
        dir_scale=0.06,
        phi_drive_scale=0.35,
        spread_penalty=0.18,
        readout_scale=0.15,
    ):
        phi = self.encoder(obs)
        z_core = self.core_init(obs)
        z_spread = self.spread_init(obs)

        spiral_mod = 1.0 + spiral_scale * (self.spiral_bias - 1.0)
        gc = torch.exp(self.log_gc) * spiral_mod
        stiff = (F.softplus(self.qdmn_log_stiff) + 0.10) * qdmn_scale

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        charge = obs[:, 2:3]
        dir_x = obs[:, 5:6]
        dir_y = obs[:, 6:7]
        obstacle = obs[:, 7:8]
        endpoints = source + goal

        obstacle_repulsion = F.avg_pool2d(obstacle, kernel_size=7, stride=1, padding=3)

        for _ in range(self.inner_steps):
            core = torch.sigmoid(core_scale * z_core)
            spread = torch.sigmoid(spread_scale * z_spread)

            phi_x = grad_x(phi)
            phi_y = grad_y(phi)
            phi_grad_mag = torch.sqrt(phi_x**2 + phi_y**2 + 1e-6)

            elastic = 0.5 * (
                stiff[0] * phi_y**2 +
                stiff[1] * (-phi_y)**2 +
                stiff[2] * phi_x**2 +
                stiff[3] * (-phi_x)**2
            )

            degraded = (1.0 - core) ** 2 * elastic

            core_drive = (
                bridge_scale * endpoints
                + 0.08 * charge.abs()
                + dir_scale * (dir_x.abs() + dir_y.abs())
                + phi_drive_scale * phi_grad_mag
                + 0.10 * degraded
                - obstacle_push * obstacle_repulsion
                - gc * (
                    core / l_value
                    + 0.20 * laplacian(core)
                    + 2.0 * core * (1.0 - core) * (1.0 - 2.0 * core)
                )
            )

            spread_drive = (
                0.25 * core
                + 0.10 * phi_grad_mag
                - spread_penalty * (spread - 0.35)
                - obstacle_push * 0.75 * obstacle_repulsion
                - gc * (
                    spread / (l_value * 1.2)
                    + 0.12 * laplacian(spread)
                    + 2.0 * spread * (1.0 - spread) * (1.0 - 2.0 * spread)
                )
            )

            phi_drive = (
                0.55 * laplacian(phi)
                + 0.65 * charge
                + 0.25 * endpoints
                + 0.15 * (dir_x + dir_y)
                - 0.08 * obstacle_repulsion
                - 0.06 * phi
                - 0.10 * core * phi
            )

            z_core = z_core + 0.15 * torch.tanh(core_drive)
            z_spread = z_spread + 0.11 * torch.tanh(spread_drive)
            phi = phi + 0.04 * torch.tanh(phi_drive)

        core = torch.sigmoid(core_scale * z_core)
        spread = torch.sigmoid(spread_scale * z_spread)
        final_prob = core * spread

        logits = 8.0 * (final_prob - 0.5) + readout_scale * self.readout(torch.cat([core, spread, phi], dim=1))
        return logits, final_prob, core, spread, phi

# ======================
# Train
# ======================
model = PF2V_ObstacleSplit(size=64, inner_steps=5).to(device)
optimizer = torch.optim.Adam(model.parameters(), lr=8e-4)

max_epochs = 80

for epoch in range(1, max_epochs + 1):
    model.train()

    t = (epoch - 1) / (max_epochs - 1)
    core_scale = 2.0 + 5.0 * t
    spread_scale = 2.0 + 3.5 * t
    l_value = 0.72 - 0.28 * t
    obstacle_push = 0.18 + 0.35 * t
    corridor_sigma = 1.9 - 0.6 * t
    core_sigma = 0.55 - 0.12 * t
    spread_penalty = 0.10 + 0.18 * t

    obs, corridor_target, core_target, obstacle_mask, start_xy, waypoint_xy, goal_xy = make_batch(
        batch_size=6, size=64, device=device, corridor_sigma=corridor_sigma, core_sigma=core_sigma
    )

    logits, pred, core, spread, phi = model(
        obs,
        core_scale=core_scale,
        spread_scale=spread_scale,
        l_value=l_value,
        spiral_scale=1.0,
        qdmn_scale=1.0,
        obstacle_push=obstacle_push,
        bridge_scale=0.12,
        dir_scale=0.06,
        phi_drive_scale=0.35,
        spread_penalty=spread_penalty,
        readout_scale=0.15,
    )

    prob = torch.sigmoid(logits)

    pos = corridor_target.sum().clamp_min(1.0)
    neg = corridor_target.numel() - pos
    pos_weight = (neg / pos).clamp(1.0, 30.0)

    bce_pred = F.binary_cross_entropy_with_logits(logits, corridor_target, pos_weight=pos_weight)
    bce_core = F.binary_cross_entropy(core.clamp(1e-4, 1 - 1e-4), core_target)
    bce_spread = F.binary_cross_entropy(spread.clamp(1e-4, 1 - 1e-4), corridor_target)

    dice = dice_loss_from_logits(logits, corridor_target)

    tv = (prob[:, :, :, 1:] - prob[:, :, :, :-1]).abs().mean() + (prob[:, :, 1:, :] - prob[:, :, :-1, :]).abs().mean()
    edge_loss = (
        F.mse_loss(grad_x(prob), grad_x(corridor_target)) +
        F.mse_loss(grad_y(prob), grad_y(corridor_target))
    )
    lap_loss = F.mse_loss(laplacian(prob), laplacian(corridor_target))
    commitment = (prob * (1.0 - prob)).mean()
    outside_loss = ((1.0 - corridor_target) * prob).mean()
    obstacle_penalty = ((prob * obstacle_mask).sum() / (obstacle_mask.sum() + 1e-6))

    route_center = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=0.0)
    route_side_p = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=0.08)
    route_side_m = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=-0.08)
    direct_line = sample_segment_probs(prob, start_xy, goal_xy, num=48, offset=0.0)

    core_route = sample_polyline_probs(core, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=0.0)

    route_center_loss = F.binary_cross_entropy(route_center.clamp(1e-4, 1 - 1e-4), torch.ones_like(route_center))
    route_side_loss = 0.5 * (
        F.binary_cross_entropy(route_side_p.clamp(1e-4, 1 - 1e-4), torch.zeros_like(route_side_p)) +
        F.binary_cross_entropy(route_side_m.clamp(1e-4, 1 - 1e-4), torch.zeros_like(route_side_m))
    )
    direct_loss = F.binary_cross_entropy(direct_line.clamp(1e-4, 1 - 1e-4), torch.zeros_like(direct_line))
    route_gap_loss = F.relu(0.82 - route_center).mean()
    core_gap_loss = F.relu(0.88 - core_route).mean()

    loss = (
        1.0 * bce_pred +
        0.35 * bce_core +
        0.18 * bce_spread +
        0.50 * dice +
        0.18 * edge_loss +
        0.10 * lap_loss +
        0.08 * commitment +
        0.06 * outside_loss +
        0.02 * tv +
        0.18 * route_center_loss +
        0.12 * route_side_loss +
        0.10 * direct_loss +
        0.12 * route_gap_loss +
        0.10 * core_gap_loss +
        0.15 * obstacle_penalty
    )

    optimizer.zero_grad()
    loss.backward()
    torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
    optimizer.step()

    if epoch == 1 or epoch % 20 == 0:
        model.eval()
        with torch.no_grad():
            logits_eval, pred_eval, core_eval, spread_eval, phi_eval = model(
                obs,
                core_scale=core_scale,
                spread_scale=spread_scale,
                l_value=l_value,
                spiral_scale=1.0,
                qdmn_scale=1.0,
                obstacle_push=obstacle_push,
                bridge_scale=0.12,
                dir_scale=0.06,
                phi_drive_scale=0.35,
                spread_penalty=spread_penalty,
                readout_scale=0.15,
            )
            prob_eval = torch.sigmoid(logits_eval)
            m = eval_metrics_from_prob(
                prob_eval, corridor_target, core_target, obstacle_mask,
                obs, start_xy, waypoint_xy, goal_xy,
                core_prob=core_eval, spread_prob=spread_eval
            )

        print(
            f"epoch {epoch:03d} | loss {loss.item():.4f} | "
            f"soft_iou {m['soft_iou']:.4f} | hard_iou {m['hard_iou']:.4f} | "
            f"route_m {m['route_mean']:.4f} | direct_m {m['direct_mean']:.4f} | "
            f"ratio {m['route_ratio']:.4f} | obs_ov {m['obstacle_overlap']:.4f}"
        )
        print(
            f"  sharp {m['sharpness']:.4f} | conn {m['connectivity']:.4f} | "
            f"core_rt {m['core_route_ratio']:.4f} | core_gap {m['core_route_gap']:.4f}"
        )
        print("-" * 110)

print("training done")

# ======================
# Held-out sample
# ======================
model.eval()
with torch.no_grad():
    obs0, corridor0, core0, obstacle0, start_xy0, waypoint_xy0, goal_xy0 = make_batch(
        batch_size=1, size=64, device=device, corridor_sigma=1.35, core_sigma=0.45
    )

# ======================
# Stress sweep
# ======================
base = dict(
    core_scale=7.0,
    spread_scale=5.5,
    l_value=0.40,
    spiral_scale=1.0,
    qdmn_scale=1.0,
    obstacle_push=0.35,
    bridge_scale=0.12,
    dir_scale=0.06,
    phi_drive_scale=0.35,
    spread_penalty=0.18,
    readout_scale=0.15,
)

sweep_configs = [
    ("base",              dict(base)),
    ("no_obstacle_input",  {**base}),
    ("weak_obstacle",     {**base, "obstacle_push": 0.00}),
    ("mid_obstacle",      {**base, "obstacle_push": 0.25}),
    ("strong_obstacle",   {**base, "obstacle_push": 0.70}),
    ("low_l_sharp",       {**base, "l_value": 0.22}),
    ("mid_l",             {**base, "l_value": 0.40}),
    ("high_l_wide",       {**base, "l_value": 0.60}),
    ("low_core",          {**base, "core_scale": 3.0}),
    ("high_core",         {**base, "core_scale": 10.0}),
    ("low_spread",        {**base, "spread_scale": 3.0}),
    ("high_spread",       {**base, "spread_scale": 8.0}),
    ("no_spiral",         {**base, "spiral_scale": 0.0}),
    ("strong_spiral",     {**base, "spiral_scale": 2.0}),
    ("no_qdmn",           {**base, "qdmn_scale": 0.0}),
    ("strong_qdmn",       {**base, "qdmn_scale": 2.0}),
    ("weak_dir",          {**base, "dir_scale": 0.00}),
    ("strong_dir",        {**base, "dir_scale": 0.15}),
    ("weak_phi",          {**base, "phi_drive_scale": 0.10}),
    ("strong_phi",        {**base, "phi_drive_scale": 0.60}),
    ("weak_readout",      {**base, "readout_scale": 0.05}),
    ("strong_readout",    {**base, "readout_scale": 0.50}),
    ("low_penalty",       {**base, "spread_penalty": 0.05}),
    ("high_penalty",      {**base, "spread_penalty": 0.40}),
]

results = []

with torch.no_grad():
    for name, cfg in sweep_configs:
        obs_cfg = obs0.clone()

        # Only this setting removes the obstacle channel to test whether the model relies on it.
        if name == "no_obstacle_input":
            obs_cfg[:, 7:8] = 0.0

        logits, pred, core, spread, phi = model(obs_cfg, **cfg)
        prob = torch.sigmoid(logits)

        metrics = eval_metrics_from_prob(
            prob, corridor0, core0, obstacle0, obs_cfg,
            start_xy0, waypoint_xy0, goal_xy0,
            core_prob=core, spread_prob=spread
        )
        metrics["setting"] = name
        results.append(metrics)

# ======================
# Print tables
# ======================
print_metrics_table(results, title="PF²V-WM OBSTACLE / ROUTE STRESS SWEEP ON ONE HELD-OUT SAMPLE")

print_ranked(results, key="hard_iou", reverse=True, topk=5)
print_ranked(results, key="route_ratio", reverse=True, topk=5)
print_ranked(results, key="obstacle_overlap", reverse=False, topk=5)
print_ranked(results, key="connectivity", reverse=True, topk=5)
print_ranked(results, key="sharpness", reverse=False, topk=5)

def find_row(name):
    for r in results:
        if r["setting"] == name:
            return r
    return None

base_row = find_row("base")
no_obs = find_row("no_obstacle_input")
weak_obs = find_row("weak_obstacle")
strong_obs = find_row("strong_obstacle")
low_l = find_row("low_l_sharp")
high_l = find_row("high_l_wide")
