high_pen = find_row("high_penalty")

print("\nINTERPRETATION POINTERS")
print(f"base route_ratio        : {base_row['route_ratio']:.4f}")
print(f"no_obs route_ratio      : {no_obs['route_ratio']:.4f}")
print(f"weak_obstacle ratio     : {weak_obs['route_ratio']:.4f}")
