with torch.no_grad():
    logits, pred, core, spread, phi = model(obs0, **base)
    prob = torch.sigmoid(logits)

m = eval_metrics_from_prob(prob, corridor0, core0, obstacle0, obs0, start_xy0, waypoint_xy0, goal_xy0, core_prob=core, spread_prob=spread)

print("\nFINAL SINGLE-SAMPLE DIAGNOSTICS (BASE CONFIG)")
for k in [
    "soft_iou", "hard_iou", "mass", "sharpness", "connectivity",
    "route_mean", "direct_mean", "route_ratio", "route_gap",
    "obstacle_overlap", "core_route_mean", "core_route_gap",
    "core_route_ratio", "spread_mass"
]:
    print(f"{k:<18}: {m[k]:.4f}")

# ======================
