fig, axes = plt.subplots(2, 2, figsize=(10, 10))

axes[0, 0].imshow(inp, cmap="gray")
axes[0, 0].set_title("Input: Start + Goal + Obstacle")
axes[0, 0].axis("off")

axes[0, 1].imshow(tgt, cmap="hot", vmin=0, vmax=1)
axes[0, 1].set_title("Target Route")
