import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import numpy as np
import matplotlib.pyplot as plt

# ============================================================
# PF²V GEODESIC FLOW EXPERIMENT
# ============================================================

# ------------------------------------------------------------
# setup
# ------------------------------------------------------------

torch.manual_seed(0)
np.random.seed(0)
random.seed(0)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("device:", device)

# ------------------------------------------------------------
# gradients
# ------------------------------------------------------------

def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))


def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))


def laplacian(x):
    kernel = torch.tensor([
        [0.0, 1.0, 0.0],
        [1.0, -4.0, 1.0],
        [0.0, 1.0, 0.0],
    ], device=x.device).view(1,1,3,3)

    return F.conv2d(x, kernel, padding=1)

# ------------------------------------------------------------
# synthetic routing world
# ------------------------------------------------------------

def gaussian_blob(size, x0, y0, sigma=1.5, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )

    dist2 = (x.float() - x0)**2 + (y.float() - y0)**2

    return torch.exp(-dist2 / (2 * sigma**2)).unsqueeze(0).unsqueeze(0)


def line_mask(size, x0, y0, x1, y1, sigma=1.5, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )

    x = x.float()
    y = y.float()

    vx = x1 - x0
    vy = y1 - y0

    denom = vx*vx + vy*vy + 1e-6

    t = ((x - x0)*vx + (y - y0)*vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px)**2 + (y - py)**2

    return torch.exp(-dist2 / (2 * sigma**2)).unsqueeze(0).unsqueeze(0)


def make_batch(batch_size=8, size=64, device="cpu"):

    obs = torch.zeros(batch_size, 4, size, size, device=device)
    target = torch.zeros(batch_size, 1, size, size, device=device)

    starts = []
    goals = []

    for b in range(batch_size):

        x0 = random.randint(6, size-7)
        y0 = random.randint(6, size-7)

        x1 = random.randint(6, size-7)
        y1 = random.randint(6, size-7)

        mx = 0.5 * (x0 + x1)
        my = 0.5 * (y0 + y1)

        obstacle = gaussian_blob(size, mx, my, sigma=5.0, device=device)
        obstacle = obstacle / obstacle.max()

        dx = x1 - x0
        dy = y1 - y0

        dist = (dx*dx + dy*dy)**0.5 + 1e-6

        ux = -dy / dist
        uy = dx / dist

        wx = np.clip(mx + ux * 10, 5, size-6)
        wy = np.clip(my + uy * 10, 5, size-6)

        seg1 = line_mask(size, x0, y0, wx, wy, sigma=1.3, device=device)
        seg2 = line_mask(size, wx, wy, x1, y1, sigma=1.3, device=device)

        route = torch.maximum(seg1, seg2)

        source = gaussian_blob(size, x0, y0, sigma=1.2, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.2, device=device)

        obs[b:b+1,0:1] = source
        obs[b:b+1,1:2] = goal
        obs[b:b+1,2:3] = source - goal
        obs[b:b+1,3:4] = obstacle

        target[b:b+1] = route

        starts.append((x0, y0))
        goals.append((x1, y1))

    return obs, target, starts, goals

# ------------------------------------------------------------
# model
# ------------------------------------------------------------

class GeodesicFlowNet(nn.Module):

    def __init__(self, hidden=32, steps=16):
        super().__init__()

        self.steps = steps

        self.encoder = nn.Sequential(
            nn.Conv2d(4, hidden, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(hidden, hidden, 3, padding=1),
            nn.GELU(),
        )

        self.phi_head = nn.Conv2d(hidden, 1, 1)
        self.wave_head = nn.Conv2d(hidden, 1, 1)

        self.diffusion = nn.Parameter(torch.tensor(0.15))
        self.transport = nn.Parameter(torch.tensor(0.20))
        self.repulsion = nn.Parameter(torch.tensor(0.55))

    def forward(self, obs):

        h = self.encoder(obs)

        phi = self.phi_head(h)
        wave = self.wave_head(h)

        source = obs[:,0:1]
        goal = obs[:,1:2]
        obstacle = obs[:,3:4]

        for _ in range(self.steps):

            gx = grad_x(phi)
            gy = grad_y(phi)

            flow_mag = torch.sqrt(gx**2 + gy**2 + 1e-6)

            phi_update = (
                self.diffusion * laplacian(phi)
                + source
                - goal
                - self.repulsion * obstacle
                - 0.10 * flow_mag
            )

            wave_update = (
                0.35 * laplacian(wave)
                + self.transport * torch.exp(-flow_mag)
                + 0.20 * source
                - 0.30 * obstacle
            )

            phi = phi + 0.10 * torch.tanh(phi_update)
            wave = wave + 0.10 * torch.tanh(wave_update)

        gx = grad_x(phi)
        gy = grad_y(phi)

        flow = torch.cat([-gx, -gy], dim=1)

        prob = torch.sigmoid(
            2.5 * wave
            - 1.2 * obstacle
            - 0.7 * torch.sqrt(gx**2 + gy**2 + 1e-6)
        )

        return {
            "phi": phi,
            "wave": wave,
            "flow": flow,
            "prob": prob,
        }

# ------------------------------------------------------------
# training
# ------------------------------------------------------------

def train_model(model, epochs=40):

    opt = torch.optim.Adam(model.parameters(), lr=1e-3)

    for epoch in range(1, epochs+1):

        obs, target, _, _ = make_batch(
            batch_size=8,
            size=64,
            device=device,
        )

        out = model(obs)

        prob = out["prob"]
        phi = out["phi"]

        bce = F.binary_cross_entropy(prob, target)

        smooth = (
            grad_x(prob).abs().mean()
            + grad_y(prob).abs().mean()
        )

        obstacle = obs[:,3:4]

        obstacle_penalty = (prob * obstacle).mean()

        gx = grad_x(phi)
        gy = grad_y(phi)

        eikonal = ((torch.sqrt(gx**2 + gy**2 + 1e-6) - 1.0)**2).mean()

        loss = (
            1.0 * bce
            + 0.08 * smooth
            + 0.15 * obstacle_penalty
            + 0.05 * eikonal
        )

        opt.zero_grad()
        loss.backward()
        opt.step()

        if epoch % 5 == 0:
            iou = hard_iou(prob, target)
            print(f"epoch {epoch:03d} | loss {loss.item():.4f} | iou {iou:.4f}")

# ------------------------------------------------------------
# metrics
# ------------------------------------------------------------

def hard_iou(prob, target, thresh=0.35):

    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()

    inter = (pred * tgt).sum()
    union = ((pred + tgt) > 0).float().sum()

    return (inter / (union + 1e-6)).item()

# ------------------------------------------------------------
# path extraction
# ------------------------------------------------------------

def extract_path(phi, start_xy, steps=120, alpha=1.0):

    phi = phi[0,0]

    H, W = phi.shape

    x, y = start_xy

    pts = []

    for _ in range(steps):

        x0 = int(np.clip(x, 1, W-2))
        y0 = int(np.clip(y, 1, H-2))

        gx = phi[y0, x0+1] - phi[y0, x0-1]
        gy = phi[y0+1, x0] - phi[y0-1, x0]

        gx = gx.item()
        gy = gy.item()

        norm = (gx*gx + gy*gy)**0.5 + 1e-6

        x = x - alpha * gx / norm
        y = y - alpha * gy / norm

        pts.append((x,y))

    return pts

# ------------------------------------------------------------
# run
# ------------------------------------------------------------

model = GeodesicFlowNet().to(device)

train_model(model, epochs=40)

obs, target, starts, goals = make_batch(
    batch_size=1,
    size=64,
    device=device,
)

with torch.no_grad():
    out = model(obs)

phi = out["phi"]
prob = out["prob"]
flow = out["flow"]

path = extract_path(phi, starts[0])

# ------------------------------------------------------------
# visualize
# ------------------------------------------------------------

img_input = (
    obs[0,0]
    + obs[0,1]
    + 0.7 * obs[0,3]
).cpu().numpy()

img_target = target[0,0].cpu().numpy()
img_prob = prob[0,0].cpu().numpy()
img_phi = phi[0,0].cpu().numpy()

fig, axes = plt.subplots(2,2, figsize=(10,10))

axes[0,0].imshow(img_input, cmap="gray")
axes[0,0].set_title("input")
axes[0,0].axis("off")

axes[0,1].imshow(img_target, cmap="hot")
axes[0,1].set_title("target route")
axes[0,1].axis("off")

axes[1,0].imshow(img_prob, cmap="hot")
axes[1,0].set_title("predicted probability")
axes[1,0].axis("off")

axes[1,1].imshow(img_phi, cmap="viridis")
axes[1,1].set_title("potential field")
axes[1,1].axis("off")

px = [p[0] for p in path]
py = [p[1] for p in path]

axes[1,1].plot(px, py)

plt.tight_layout()
plt.show()

import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import numpy as np
import matplotlib.pyplot as plt
import json
import csv

# ============================================================
# PF²V GEODESIC FLOW PROBE v2
#   - potential field + wave field
#   - route-point supervision on the target corridor
#   - Dice + obstacle + eikonal losses
#   - step sweep and threshold sweep
#   - path extraction from potential field
# ============================================================

# ----------------------
# Setup
# ----------------------
torch.manual_seed(0)
np.random.seed(0)
random.seed(0)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("device:", device)

# ----------------------
# Basic operators
# ----------------------
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

# ----------------------
# Synthetic world
# ----------------------
def gaussian_blob(size, x0, y0, sigma=1.5, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    dist2 = (x.float() - x0) ** 2 + (y.float() - y0) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def line_mask(size, x0, y0, x1, y1, sigma=1.5, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    x = x.float()
    y = y.float()

    vx = x1 - x0
    vy = y1 - y0
    denom = vx * vx + vy * vy + 1e-6

    t = ((x - x0) * vx + (y - y0) * vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px) ** 2 + (y - py) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def make_batch(batch_size=8, size=64, device="cpu"):
    """
    4-channel input:
      0 source blob
      1 goal blob
      2 charge = source - goal
      3 obstacle field
    """
    obs = torch.zeros(batch_size, 4, size, size, device=device)
    target = torch.zeros(batch_size, 1, size, size, device=device)

    starts_xy = torch.zeros(batch_size, 2, device=device)
    waypoints_xy = torch.zeros(batch_size, 2, device=device)
    goals_xy = torch.zeros(batch_size, 2, device=device)

    starts_px = []
    goals_px = []

    for b in range(batch_size):
        x0 = random.randint(6, size - 7)
        y0 = random.randint(6, size - 7)
        x1 = random.randint(6, size - 7)
        y1 = random.randint(6, size - 7)

        mx = 0.5 * (x0 + x1)
        my = 0.5 * (y0 + y1)

        obstacle = gaussian_blob(size, mx, my, sigma=5.0, device=device)
        obstacle = obstacle / obstacle.max().clamp_min(1e-6)

        dx = float(x1 - x0)
        dy = float(y1 - y0)
        dist = (dx * dx + dy * dy) ** 0.5 + 1e-6

        # bend around the obstacle
        ux = -dy / dist
        uy = dx / dist
        side = 1.0 if (y1 >= y0) else -1.0
        offset_px = max(8.0, 0.30 * dist)

        wx = np.clip(mx + side * ux * offset_px, 5, size - 6)
        wy = np.clip(my + side * uy * offset_px, 5, size - 6)

        source = gaussian_blob(size, x0, y0, sigma=1.2, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.2, device=device)
        charge = source - goal

        route_1 = line_mask(size, x0, y0, wx, wy, sigma=1.3, device=device)
        route_2 = line_mask(size, wx, wy, x1, y1, sigma=1.3, device=device)
        route = torch.maximum(route_1, route_2)

        obs[b:b+1, 0:1] = source
        obs[b:b+1, 1:2] = goal
        obs[b:b+1, 2:3] = charge
        obs[b:b+1, 3:4] = obstacle

        target[b:b+1] = route

        starts_xy[b] = torch.tensor([2.0 * x0 / (size - 1) - 1.0, 2.0 * y0 / (size - 1) - 1.0], device=device)
        waypoints_xy[b] = torch.tensor([2.0 * wx / (size - 1) - 1.0, 2.0 * wy / (size - 1) - 1.0], device=device)
        goals_xy[b] = torch.tensor([2.0 * x1 / (size - 1) - 1.0, 2.0 * y1 / (size - 1) - 1.0], device=device)

        starts_px.append((x0, y0))
        goals_px.append((x1, y1))

    return obs, target, starts_xy, waypoints_xy, goals_xy, starts_px, goals_px

# ----------------------
# Sampling utilities
# ----------------------
def sample_segment_probs(prob, start_xy, goal_xy, num=40, offset=0.0):
    """
    Samples probabilities along a straight segment in normalized coordinates [-1, 1].
    """
    B = prob.shape[0]
    t = torch.linspace(0, 1, num, device=prob.device).view(1, num, 1)

    start = start_xy.view(B, 1, 2)
    goal = goal_xy.view(B, 1, 2)

    direction = goal - start
    norm = torch.linalg.norm(direction, dim=-1, keepdim=True).clamp_min(1e-6)
    unit = direction / norm
    perp = torch.cat([-unit[..., 1:2], unit[..., 0:1]], dim=-1)

    pts = start * (1.0 - t) + goal * t + offset * perp
    pts = pts.clamp(-1.0, 1.0)

    grid = pts.view(B, num, 1, 2)
    sampled = F.grid_sample(prob, grid, mode="bilinear", padding_mode="zeros", align_corners=True)
    return sampled[:, 0, :, 0]

def sample_polyline_probs(prob, p0, p1, p2, num_per_segment=20, offset=0.0):
    a = sample_segment_probs(prob, p0, p1, num=num_per_segment, offset=offset)
    b = sample_segment_probs(prob, p1, p2, num=num_per_segment, offset=offset)
    return torch.cat([a, b], dim=1)

# ----------------------
# Metrics
# ----------------------
def soft_iou_from_prob(prob, target, eps=1e-6):
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def hard_iou_from_prob(prob, target, thresh=0.35, eps=1e-6):
    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()
    inter = (pred * tgt).sum(dim=(1, 2, 3))
    union = ((pred + tgt) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_prob(prob, target, eps=1e-6):
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    return (1.0 - (2.0 * inter + eps) / (union + eps)).mean()

def connectivity_estimate(prob, thresh=0.35):
    binary = (prob > thresh).float()
    horizontal = 0.0
    vertical = 0.0
    if binary.shape[-1] > 1:
        horizontal = (binary[:, :, :, 1:] * binary[:, :, :, :-1]).mean().item()
    if binary.shape[-2] > 1:
        vertical = (binary[:, :, 1:, :] * binary[:, :, :-1, :]).mean().item()
    return horizontal + vertical

def route_metrics(prob, start_xy, waypoint_xy, goal_xy, thresh=0.35, obstacle_mask=None):
    direct = sample_segment_probs(prob, start_xy, goal_xy, num=40, offset=0.0)
    route = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.0)
    side_p = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.08)
    side_m = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=-0.08)

    direct_mean = direct.mean().item()
    route_mean = route.mean().item()
    route_gap = (route < thresh).float().mean().item()
    route_ratio = route_mean / (direct_mean + 1e-6)

    out = {
        "direct_mean": direct_mean,
        "route_mean": route_mean,
        "route_gap": route_gap,
        "route_ratio": route_ratio,
        "side_mean": 0.5 * (side_p.mean().item() + side_m.mean().item()),
    }

    if obstacle_mask is not None:
        out["obstacle_overlap"] = ((prob * obstacle_mask).sum() / (obstacle_mask.sum() + 1e-6)).item()
    else:
        out["obstacle_overlap"] = float("nan")

    return out

def eval_metrics_from_prob(
    prob, target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
    thresh=0.35, phi_prob=None
):
    soft_iou = soft_iou_from_prob(prob, target)
    hard_iou = hard_iou_from_prob(prob, target, thresh=thresh)
    mass = prob.mean()
    sharpness = (prob * (1.0 - prob)).mean()
    conn = connectivity_estimate(prob, thresh=thresh)

    source = obs[:, 0:1]
    goal = obs[:, 1:2]
    source_hit = ((prob * source).sum() / (source.sum() + 1e-6))
    goal_hit = ((prob * goal).sum() / (goal.sum() + 1e-6))

    route = route_metrics(prob, start_xy, waypoint_xy, goal_xy, thresh=thresh, obstacle_mask=obstacle_mask)

    active = (prob > thresh).float().sum().item()
    target_active = (target > 0.5).float().sum().item()
    compactness = target_active / (active + target_active + 1e-6)

    out = {
        "soft_iou": float(soft_iou.item()),
        "hard_iou": float(hard_iou.item()),
        "mass": float(mass.item()),
        "sharpness": float(sharpness.item()),
        "connectivity": float(conn),
        "source_hit": float(source_hit.item()),
        "goal_hit": float(goal_hit.item()),
        "compactness": float(compactness),
        **route,
    }

    if phi_prob is not None:
        out["phi_mass"] = float(phi_prob.mean().item())
        out["phi_sharpness"] = float((phi_prob * (1.0 - phi_prob)).mean().item())

    return out

def print_table(rows, title, keys):
    print("\n" + "=" * 146)
    print(title)
    print("=" * 146)
    header = f"{'setting':<24}" + "".join([f"{k:>12}" for k in keys])
    print(header)
    print("-" * len(header))
    for i, r in enumerate(rows, 1):
        label = r.get("setting", f"row_{i}")
        line = f"{label:<24}"
        for k in keys:
            line += f"{r.get(k, float('nan')):>12.4f}"
        print(line)
    print("=" * 146)

def print_ranked(rows, key, reverse=True, topk=5):
    ranked = sorted(rows, key=lambda r: r[key], reverse=reverse)[:topk]
    print(f"\nTop {topk} by {key} ({'high' if reverse else 'low'} is better):")
    for r in ranked:
        print(
            f"  {r['setting']:<22} | {key}={r[key]:.4f} | "
            f"hard_iou={r['hard_iou']:.4f} | route_ratio={r['route_ratio']:.4f} | "
            f"obs_ov={r['obstacle_overlap']:.4f} | conn={r['connectivity']:.4f}"
        )

def save_results_json_csv(results_dict, json_path, csv_path):
    with open(json_path, "w") as f:
        json.dump(results_dict, f, indent=2)

    all_rows = []
    for group_name, rows in results_dict.items():
        if not isinstance(rows, list):
            continue
        for r in rows:
            if isinstance(r, dict):
                rr = dict(r)
            else:
                continue
            rr["group"] = group_name
            all_rows.append(rr)

    if len(all_rows) == 0:
        print("No tabular rows found for CSV export.")
        return

    fieldnames = sorted(set().union(*[r.keys() for r in all_rows]))
    with open(csv_path, "w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for r in all_rows:
            writer.writerow(r)

# ----------------------
# Model
# ----------------------
class GeodesicFlowNet(nn.Module):
    """
    A potential-flow model with explicit route-point supervision.
    """
    def __init__(self, hidden=32, steps=16):
        super().__init__()
        self.steps = steps

        self.encoder = nn.Sequential(
            nn.Conv2d(4, hidden, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(hidden, hidden, 3, padding=1),
            nn.GELU(),
        )

        self.phi_head = nn.Conv2d(hidden, 1, 1)
        self.wave_head = nn.Conv2d(hidden, 1, 1)

        self.diffusion = nn.Parameter(torch.tensor(0.15))
        self.transport = nn.Parameter(torch.tensor(0.20))
        self.repulsion = nn.Parameter(torch.tensor(0.55))
        self.commit_gain = nn.Parameter(torch.tensor(1.25))
        self.phi_gain = nn.Parameter(torch.tensor(0.85))
        self.obstacle_gain = nn.Parameter(torch.tensor(1.15))

    def forward(self, obs, max_steps=None, temperature=0.85):
        h = self.encoder(obs)

        phi = self.phi_head(h)
        wave = self.wave_head(h)

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        obstacle = obs[:, 3:4]

        if max_steps is None:
            max_steps = self.steps

        for _ in range(max_steps):
            gx = grad_x(phi)
            gy = grad_y(phi)
            flow_mag = torch.sqrt(gx**2 + gy**2 + 1e-6)

            phi_update = (
                self.diffusion * laplacian(phi)
                + 1.25 * source
                - 1.05 * goal
                - self.repulsion * obstacle
                - 0.10 * flow_mag
            )

            wave_update = (
                0.35 * laplacian(wave)
                + self.transport * torch.tanh(phi)
                + 0.18 * source
                - 0.25 * obstacle
            )

            phi = phi + 0.10 * torch.tanh(phi_update)
            wave = wave + 0.10 * torch.tanh(wave_update)

        gx = grad_x(phi)
        gy = grad_y(phi)
        flow_mag = torch.sqrt(gx**2 + gy**2 + 1e-6)

        # Normalize wave/phi per-sample to prevent all-zero collapse
        wave_mu = wave.mean(dim=(2, 3), keepdim=True)
        wave_sd = wave.std(dim=(2, 3), keepdim=True).clamp_min(1e-6)
        phi_mu = phi.mean(dim=(2, 3), keepdim=True)
        phi_sd = phi.std(dim=(2, 3), keepdim=True).clamp_min(1e-6)

        wave_z = (wave - wave_mu) / wave_sd
        phi_z = (phi - phi_mu) / phi_sd

        logits = (
            self.commit_gain * wave_z
            + self.phi_gain * phi_z
            - self.obstacle_gain * obstacle
            - 0.45 * flow_mag
        )

        prob = torch.sigmoid(logits / temperature)

        return {
            "phi": phi,
            "wave": wave,
            "flow_mag": flow_mag,
            "logits": logits,
            "prob": prob,
        }

# ----------------------
# Path extraction
# ----------------------
def extract_path(phi, start_px, steps=140, alpha=0.9):
    """
    Gradient descent on the potential field in pixel space.
    """
    phi = phi[0, 0].detach().cpu().numpy()
    H, W = phi.shape

    x, y = float(start_px[0]), float(start_px[1])
    pts = []

    for _ in range(steps):
        x0 = int(np.clip(x, 1, W - 2))
        y0 = int(np.clip(y, 1, H - 2))

        gx = phi[y0, x0 + 1] - phi[y0, x0 - 1]
        gy = phi[y0 + 1, x0] - phi[y0 - 1, x0]

        norm = (gx * gx + gy * gy) ** 0.5 + 1e-6
        x = x - alpha * gx / norm
        y = y - alpha * gy / norm
        pts.append((x, y))

    return pts

# ----------------------
# Training
# ----------------------
def train_model(model, epochs=50, batch_size=8, size=64):
    opt = torch.optim.Adam(model.parameters(), lr=1e-3)

    for epoch in range(1, epochs + 1):
        model.train()

        obs, target, start_xy, waypoint_xy, goal_xy, _, _ = make_batch(
            batch_size=batch_size,
            size=size,
            device=device,
        )

        out = model(obs, max_steps=model.steps, temperature=1.0)

        prob = out["prob"]
        logits = out["logits"]
        phi = out["phi"]
        obstacle = obs[:, 3:4]

        pos = target.sum().clamp_min(1.0)
        neg = target.numel() - pos
        pos_weight = (neg / pos).clamp(1.0, 40.0)

        bce = F.binary_cross_entropy_with_logits(logits, target, pos_weight=pos_weight)
        dice = dice_loss_from_prob(prob, target)
        smooth = grad_x(prob).abs().mean() + grad_y(prob).abs().mean()
        obstacle_penalty = (prob * obstacle).mean()

        gx = grad_x(phi)
        gy = grad_y(phi)
        eikonal = ((torch.sqrt(gx**2 + gy**2 + 1e-6) - 1.0) ** 2).mean()

        # Route supervision on sampled points
        route_pred = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.0)
        route_tgt = sample_polyline_probs(target, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.0)
        route_loss = F.mse_loss(route_pred, route_tgt)

        side_pred_p = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.08)
        side_pred_m = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=-0.08)
        side_tgt_p = sample_polyline_probs(target, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.08)
        side_tgt_m = sample_polyline_probs(target, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=-0.08)
        side_loss = 0.5 * (
            F.mse_loss(side_pred_p, side_tgt_p) +
            F.mse_loss(side_pred_m, side_tgt_m)
        )

        direct_pred = sample_segment_probs(prob, start_xy, goal_xy, num=40, offset=0.0)
        direct_tgt = sample_segment_probs(target, start_xy, goal_xy, num=40, offset=0.0)
        direct_loss = F.mse_loss(direct_pred, direct_tgt)

        # Encourage wave to stay nontrivial
        mass_floor = F.relu(0.04 - prob.mean())

        loss = (
            0.90 * bce +
            0.55 * dice +
            0.10 * smooth +
            0.20 * obstacle_penalty +
            0.05 * eikonal +
            0.45 * route_loss +
            0.15 * side_loss +
            0.10 * direct_loss +
            0.20 * mass_floor
        )

        opt.zero_grad()
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
        opt.step()

        if epoch == 1 or epoch % 5 == 0:
            model.eval()
            with torch.no_grad():
                out_e = model(obs, max_steps=model.steps, temperature=1.0)
                m = eval_metrics_from_prob(
                    out_e["prob"], target, obstacle, obs, start_xy, waypoint_xy, goal_xy,
                    thresh=0.35, phi_prob=torch.sigmoid(out_e["phi"])
                )

            print(
                f"epoch {epoch:03d} | loss {loss.item():.4f} | "
                f"soft_iou {m['soft_iou']:.4f} | hard_iou {m['hard_iou']:.4f} | "
                f"route_ratio {m['route_ratio']:.4f} | obs_ov {m['obstacle_overlap']:.4f}"
            )

    return model

# ----------------------
# Evaluation sweeps
# ----------------------
def evaluate_step_sweep(model, obs, target, obstacle, start_xy, waypoint_xy, goal_xy, step_list):
    rows = []
    model.eval()
    with torch.no_grad():
        for s in step_list:
            out = model(obs, max_steps=s, temperature=1.0)
            m = eval_metrics_from_prob(
                out["prob"], target, obstacle, obs, start_xy, waypoint_xy, goal_xy,
                thresh=0.35, phi_prob=torch.sigmoid(out["phi"])
            )
            m["setting"] = f"steps_{s}"
            m["steps_used"] = float(s)
            rows.append(m)
    return rows

def evaluate_threshold_sweep(model, obs, target, obstacle, start_xy, waypoint_xy, goal_xy, step_value, thresholds):
    rows = []
    model.eval()
    with torch.no_grad():
        out = model(obs, max_steps=step_value, temperature=1.0)
        for th in thresholds:
            m = eval_metrics_from_prob(
                out["prob"], target, obstacle, obs, start_xy, waypoint_xy, goal_xy,
                thresh=th, phi_prob=torch.sigmoid(out["phi"])
            )
            m["setting"] = f"step_{step_value}_th_{th:.2f}"
            m["step"] = float(step_value)
            m["threshold"] = float(th)
            rows.append(m)
    return rows

# ----------------------
# Run experiment
# ----------------------
model = GeodesicFlowNet(hidden=32, steps=16).to(device)
print("\nTraining geodesic-flow probe...")
model = train_model(model, epochs=50, batch_size=8, size=64)

# Held-out batch
eval_batch_size = 32
with torch.no_grad():
    obs_eval, target_eval, start_eval, waypoint_eval, goal_eval, starts_px, goals_px = make_batch(
        batch_size=eval_batch_size,
        size=64,
        device=device,
    )
    obstacle_eval = obs_eval[:, 3:4]

# Step sweep
step_list = [4, 8, 12, 16]
step_rows = evaluate_step_sweep(
    model,
    obs_eval,
    target_eval,
    obstacle_eval,
    start_eval,
    waypoint_eval,
    goal_eval,
    step_list=step_list
)

# Threshold sweep at each step
thresholds = [0.25, 0.35, 0.50]
threshold_rows = []
for s in step_list:
    threshold_rows.extend(
        evaluate_threshold_sweep(
            model,
            obs_eval,
            target_eval,
            obstacle_eval,
            start_eval,
            waypoint_eval,
            goal_eval,
            step_value=s,
            thresholds=thresholds
        )
    )

# Tables
keys_step = ["soft_iou", "hard_iou", "route_ratio", "obstacle_overlap", "route_gap", "sharpness", "connectivity", "steps_used"]
keys_thresh = ["soft_iou", "hard_iou", "route_ratio", "obstacle_overlap", "route_gap", "sharpness", "connectivity", "threshold"]

print_table(step_rows, "GEODESIC FLOW: step sweep on held-out batch", keys_step)

for s in step_list:
    rows_s = [r for r in threshold_rows if int(r["step"]) == s]
    print_table(rows_s, f"GEODESIC FLOW: threshold sweep at step = {s}", keys_thresh)

print_ranked(step_rows, key="hard_iou", reverse=True, topk=5)
