import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import numpy as np
import matplotlib.pyplot as plt
import json
import csv

# ============================================================
# PF²V FINAL PAPER PACK
#   1) base
#   2) additive memory
#   3) material memory
#   4) material-thin
#   5) harder generalization test
#   6) negative control: soft shortest-path baseline
# ============================================================

# ----------------------
# Setup
# ----------------------
torch.manual_seed(42)
np.random.seed(42)
random.seed(42)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# ----------------------
# Basic operators
# ----------------------
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

def gaussian_blob(size, x0, y0, sigma=1.5, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    dist2 = (x.float() - x0) ** 2 + (y.float() - y0) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def soft_line_mask(size, x0, y0, x1, y1, sigma=1.5, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    x = x.float()
    y = y.float()

    x0 = float(x0)
    y0 = float(y0)
    x1 = float(x1)
    y1 = float(y1)

    vx = x1 - x0
    vy = y1 - y0
    denom = vx * vx + vy * vy + 1e-6

    t = ((x - x0) * vx + (y - y0) * vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px) ** 2 + (y - py) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

# ----------------------
# Synthetic routing world
# ----------------------
def make_batch(
    batch_size=8,
    size=48,
    device="cpu",
    corridor_sigma=1.40,
    core_sigma=0.42,
    obstacle_sigma=4.5,
    hard=False,
    multi_obstacles=False,
):
    """
    8-channel input:
      0 source blob
      1 goal blob
      2 charge = source - goal
      3 obstacle field
      4 x coordinate
      5 y coordinate
      6 direction x
      7 direction y
    """
    obs = torch.zeros(batch_size, 8, size, size, device=device)
    corridor_target = torch.zeros(batch_size, 1, size, size, device=device)
    core_target = torch.zeros(batch_size, 1, size, size, device=device)
    obstacle_mask = torch.zeros(batch_size, 1, size, size, device=device)

    start_xy = torch.zeros(batch_size, 2, device=device)
    waypoint_xy = torch.zeros(batch_size, 2, device=device)
    goal_xy = torch.zeros(batch_size, 2, device=device)

    yy, xx = torch.meshgrid(
        torch.linspace(-1, 1, size, device=device),
        torch.linspace(-1, 1, size, device=device),
        indexing="ij"
    )
    coord_x = xx.unsqueeze(0).unsqueeze(0)
    coord_y = yy.unsqueeze(0).unsqueeze(0)

    for b in range(batch_size):
        x0 = random.randint(7, size - 8)
        y0 = random.randint(7, size - 8)
        x1 = random.randint(7, size - 8)
        y1 = random.randint(7, size - 8)

        dx = float(x1 - x0)
        dy = float(y1 - y0)
        dist = (dx * dx + dy * dy) ** 0.5 + 1e-6

        bend_strength = 0.42 if hard else 0.30
        offset_px = max(6.0, bend_strength * dist)

        ux = -dy / dist
        uy = dx / dist
        side = 1.0 if (y1 >= y0) else -1.0

        mx = 0.5 * (x0 + x1)
        my = 0.5 * (y0 + y1)

        wx = np.clip(mx + side * ux * offset_px, 5, size - 6)
        wy = np.clip(my + side * uy * offset_px, 5, size - 6)

        source = gaussian_blob(size, x0, y0, sigma=1.15, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.15, device=device)
        charge = source - goal

        route_1 = soft_line_mask(size, x0, y0, wx, wy, sigma=corridor_sigma, device=device)
        route_2 = soft_line_mask(size, wx, wy, x1, y1, sigma=corridor_sigma, device=device)
        corridor = torch.maximum(route_1, route_2)

        core_1 = soft_line_mask(size, x0, y0, wx, wy, sigma=core_sigma, device=device)
        core_2 = soft_line_mask(size, wx, wy, x1, y1, sigma=core_sigma, device=device)
        core = torch.maximum(core_1, core_2)

        obstacle = gaussian_blob(size, mx, my, sigma=obstacle_sigma if not hard else obstacle_sigma * 1.20, device=device)
        if hard and multi_obstacles and random.random() < 0.55:
            dx2 = np.clip(mx + random.choice([-1, 1]) * random.uniform(5.0, 9.0), 4, size - 5)
            dy2 = np.clip(my + random.choice([-1, 1]) * random.uniform(5.0, 9.0), 4, size - 5)
            obstacle2 = gaussian_blob(size, dx2, dy2, sigma=obstacle_sigma * 0.90, device=device)
            obstacle = torch.maximum(obstacle, obstacle2)

        obstacle = obstacle / obstacle.max().clamp_min(1e-6)

        dir_x = torch.full((1, 1, size, size), dx / dist, device=device)
        dir_y = torch.full((1, 1, size, size), dy / dist, device=device)

        obs[b:b+1, 0:1] = source
        obs[b:b+1, 1:2] = goal
        obs[b:b+1, 2:3] = charge
        obs[b:b+1, 3:4] = obstacle
        obs[b:b+1, 4:5] = coord_x
        obs[b:b+1, 5:6] = coord_y
        obs[b:b+1, 6:7] = dir_x
        obs[b:b+1, 7:8] = dir_y

        corridor_target[b:b+1] = corridor
        core_target[b:b+1] = core
        obstacle_mask[b:b+1] = obstacle

        start_xy[b] = torch.tensor([2.0 * x0 / (size - 1) - 1.0, 2.0 * y0 / (size - 1) - 1.0], device=device)
        waypoint_xy[b] = torch.tensor([2.0 * wx / (size - 1) - 1.0, 2.0 * wy / (size - 1) - 1.0], device=device)
        goal_xy[b] = torch.tensor([2.0 * x1 / (size - 1) - 1.0, 2.0 * y1 / (size - 1) - 1.0], device=device)

    return obs, corridor_target, core_target, obstacle_mask, start_xy, waypoint_xy, goal_xy

# ----------------------
# Sampling utilities
# ----------------------
def sample_segment_probs(prob, start_xy, goal_xy, num=40, offset=0.0):
    B = prob.shape[0]
    t = torch.linspace(0, 1, num, device=prob.device).view(1, num, 1)

    start = start_xy.view(B, 1, 2)
    goal = goal_xy.view(B, 1, 2)

    direction = goal - start
    norm = torch.linalg.norm(direction, dim=-1, keepdim=True).clamp_min(1e-6)
    unit = direction / norm
    perp = torch.cat([-unit[..., 1:2], unit[..., 0:1]], dim=-1)

    pts = start * (1.0 - t) + goal * t + offset * perp
    pts = pts.clamp(-1.0, 1.0)

    grid = pts.view(B, num, 1, 2)
    sampled = F.grid_sample(prob, grid, mode="bilinear", padding_mode="zeros", align_corners=True)
    return sampled[:, 0, :, 0]

def sample_polyline_probs(prob, p0, p1, p2, num_per_segment=20, offset=0.0):
    a = sample_segment_probs(prob, p0, p1, num=num_per_segment, offset=offset)
    b = sample_segment_probs(prob, p1, p2, num=num_per_segment, offset=offset)
    return torch.cat([a, b], dim=1)

# ----------------------
# Metrics
# ----------------------
def soft_iou_from_prob(prob, target, eps=1e-6):
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def hard_iou_from_prob(prob, target, thresh=0.35, eps=1e-6):
    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()
    inter = (pred * tgt).sum(dim=(1, 2, 3))
    union = ((pred + tgt) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_prob(prob, target, eps=1e-6):
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    return (1.0 - (2.0 * inter + eps) / (union + eps)).mean()

def connectivity_estimate(prob, thresh=0.35):
    binary = (prob > thresh).float()
    horizontal = 0.0
    vertical = 0.0
    if binary.shape[-1] > 1:
        horizontal = (binary[:, :, :, 1:] * binary[:, :, :, :-1]).mean().item()
    if binary.shape[-2] > 1:
        vertical = (binary[:, :, 1:, :] * binary[:, :, :-1, :]).mean().item()
    return horizontal + vertical

def route_metrics(prob, start_xy, waypoint_xy, goal_xy, thresh=0.35, obstacle_mask=None):
    direct = sample_segment_probs(prob, start_xy, goal_xy, num=40, offset=0.0)
    route = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.0)
    side_p = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.08)
    side_m = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=-0.08)

    direct_mean = direct.mean().item()
    route_mean = route.mean().item()
    route_gap = (route < thresh).float().mean().item()
    route_ratio = route_mean / (direct_mean + 1e-6)

    out = {
        "direct_mean": direct_mean,
        "route_mean": route_mean,
        "route_gap": route_gap,
        "route_ratio": route_ratio,
        "side_mean": 0.5 * (side_p.mean().item() + side_m.mean().item()),
    }

    if obstacle_mask is not None:
        out["obstacle_overlap"] = ((prob * obstacle_mask).sum() / (obstacle_mask.sum() + 1e-6)).item()
    else:
        out["obstacle_overlap"] = float("nan")

    return out

def sample_scalar(x):
    return float(x.detach().cpu().item())

def eval_metrics_from_prob(
    prob,
    target,
    obstacle_mask,
    obs,
    start_xy,
    waypoint_xy,
    goal_xy,
    thresh=0.35,
    core_prob=None,
    spread_prob=None,
    phi_prob=None,
    **_ignored,
):
    soft_iou = soft_iou_from_prob(prob, target)
    hard_iou = hard_iou_from_prob(prob, target, thresh=thresh)
    mass = prob.mean()
    sharpness = (prob * (1.0 - prob)).mean()
    conn = connectivity_estimate(prob, thresh=thresh)

    source = obs[:, 0:1]
    goal = obs[:, 1:2]
    source_hit = ((prob * source).sum() / (source.sum() + 1e-6))
    goal_hit = ((prob * goal).sum() / (goal.sum() + 1e-6))

    route = route_metrics(
        prob, start_xy, waypoint_xy, goal_xy,
        thresh=thresh,
        obstacle_mask=obstacle_mask
    )

    active = (prob > thresh).float().sum().item()
    target_active = (target > 0.5).float().sum().item()
    compactness = target_active / (active + target_active + 1e-6)

    out = {
        "soft_iou": sample_scalar(soft_iou),
        "hard_iou": sample_scalar(hard_iou),
        "mass": sample_scalar(mass),
        "sharpness": sample_scalar(sharpness),
        "connectivity": float(conn),
        "source_hit": sample_scalar(source_hit),
        "goal_hit": sample_scalar(goal_hit),
        "compactness": float(compactness),
        **route,
    }

    if core_prob is not None:
        core_route = route_metrics(core_prob, start_xy, waypoint_xy, goal_xy, thresh=thresh)
        out["core_route_mean"] = core_route["route_mean"]
        out["core_route_gap"] = core_route["route_gap"]
        out["core_route_ratio"] = core_route["route_ratio"]
        out["core_mass"] = sample_scalar(core_prob.mean())
        out["core_sharpness"] = sample_scalar((core_prob * (1.0 - core_prob)).mean())

    if spread_prob is not None:
        out["spread_mass"] = sample_scalar(spread_prob.mean())

    if phi_prob is not None:
        out["phi_mass"] = sample_scalar(phi_prob.mean())
        out["phi_sharpness"] = sample_scalar((phi_prob * (1.0 - phi_prob)).mean())

    return out

def print_table(rows, title, keys):
    print("\n" + "=" * 146)
    print(title)
    print("=" * 146)
    header = f"{'setting':<24}" + "".join([f"{k:>12}" for k in keys])
    print(header)
    print("-" * len(header))
    for i, r in enumerate(rows, 1):
        label = r.get("setting", f"row_{i}")
        line = f"{label:<24}"
        for k in keys:
            line += f"{r.get(k, float('nan')):>12.4f}"
        print(line)
    print("=" * 146)

def print_ranked(rows, key, reverse=True, topk=5):
    ranked = sorted(rows, key=lambda r: r[key], reverse=reverse)[:topk]
    print(f"\nTop {topk} by {key} ({'high' if reverse else 'low'} is better):")
    for r in ranked:
        print(
            f"  {r['setting']:<22} | {key}={r[key]:.4f} | "
            f"hard_iou={r['hard_iou']:.4f} | route_ratio={r['route_ratio']:.4f} | "
            f"obs_ov={r['obstacle_overlap']:.4f} | conn={r['connectivity']:.4f}"
        )

def save_results_json_csv(results_dict, json_path, csv_path):
    def to_jsonable(v):
        if isinstance(v, dict):
            return {str(k): to_jsonable(val) for k, val in v.items()}
        if isinstance(v, list):
            return [to_jsonable(x) for x in v]
        if isinstance(v, tuple):
            return [to_jsonable(x) for x in v]
        if isinstance(v, (np.integer, np.floating)):
            return v.item()
        return v

    with open(json_path, "w") as f:
        json.dump(to_jsonable(results_dict), f, indent=2)

    all_rows = []
    for group_name, rows in results_dict.items():
        if not isinstance(rows, list):
            continue
        for r in rows:
            if isinstance(r, dict):
                rr = dict(r)
                rr["group"] = group_name
                all_rows.append(rr)

    if len(all_rows) == 0:
        print("No tabular rows found for CSV export.")
        return

    fieldnames = sorted(set().union(*[r.keys() for r in all_rows]))
    with open(csv_path, "w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for r in all_rows:
            writer.writerow(r)

# ----------------------
# Memory update
# ----------------------
def harden_memory(prev_memory, core, obstacle, decay=0.82, gain=0.35):
    mem = decay * prev_memory + gain * core.detach()
    mem = mem * (1.0 - 0.35 * obstacle)
    return mem.clamp(0.0, 1.0)

# ----------------------
# PF²V model family
# ----------------------
class MaterialPF2V(nn.Module):
    """
    memory_mode:
      - "none"
      - "additive"
      - "material"
    """
    def __init__(self, memory_mode="material", inner_steps=8, size=48):
        super().__init__()
        assert memory_mode in ("none", "additive", "material")
        self.memory_mode = memory_mode
        self.inner_steps = inner_steps
        in_ch = 9 if memory_mode == "additive" else 8

        self.encoder = nn.Sequential(
            nn.Conv2d(in_ch, 24, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(24, 12, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(12, 1, 3, padding=1),
        )
        self.core_init = nn.Sequential(
            nn.Conv2d(in_ch, 12, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(12, 1, 3, padding=1),
        )
        self.spread_init = nn.Sequential(
            nn.Conv2d(in_ch, 12, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(12, 1, 3, padding=1),
        )
        self.readout = nn.Sequential(
            nn.Conv2d(3, 12, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(12, 1, 1),
        )

        self.qdmn_log_stiff = nn.Parameter(torch.zeros(4))
        self.log_gc = nn.Parameter(torch.tensor(-0.8))
        self.register_buffer("spiral_bias", self._make_spiral(size))

    def _make_spiral(self, size):
        y, x = torch.meshgrid(torch.arange(size), torch.arange(size), indexing="ij")
        y = y.float()
        x = x.float()
        cx = size / 2
        cy = size / 2
        r = torch.sqrt((x - cx) ** 2 + (y - cy) ** 2) + 1e-6
        theta = torch.atan2(y - cy, x - cx)
        spiral = torch.sin(2.5 * theta + 1.1 * torch.log(r))
        return (1.0 + 0.05 * spiral).view(1, 1, size, size)

    def forward(
        self,
        obs,
        memory=None,
        core_scale=6.0,
        spread_scale=4.5,
        l_value=0.40,
        spiral_scale=1.0,
        qdmn_scale=1.0,
        obstacle_push=0.35,
        bridge_scale=0.12,
        dir_scale=0.06,
        phi_drive_scale=0.35,
        spread_penalty=0.18,
        readout_scale=0.15,
        memory_gain=0.18,
        max_steps=None,
        stop_tol=1e-4,
    ):
        if self.memory_mode == "additive":
            if memory is None:
                memory = torch.zeros_like(obs[:, :1])
            x = torch.cat([obs, memory], dim=1)
        else:
            x = obs

        phi = self.encoder(x)
        z_core = self.core_init(x)
        z_spread = self.spread_init(x)

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        charge = obs[:, 2:3]
        dir_x = obs[:, 6:7]
        dir_y = obs[:, 7:8]
        obstacle = obs[:, 3:4]
        endpoints = source + goal

        obstacle_repulsion = F.avg_pool2d(obstacle, kernel_size=7, stride=1, padding=3)

        spiral_mod = 1.0 + spiral_scale * (self.spiral_bias.to(obs.device, obs.dtype) - 1.0)
        gc = torch.exp(self.log_gc) * spiral_mod
        stiff = (F.softplus(self.qdmn_log_stiff) + 0.10) * qdmn_scale

        if max_steps is None:
            max_steps = self.inner_steps

        if memory is None:
            mem_field = torch.zeros_like(obstacle)
        else:
            mem_field = memory.clamp(0.0, 1.0)

        local_l = (l_value * (1.0 - 0.35 * mem_field)).clamp(0.12, 1.50)
        local_gc = gc * (1.0 - 0.30 * mem_field)
        local_obs_push = obstacle_push * (1.0 - 0.60 * mem_field)
        local_spread_pen = spread_penalty * (1.0 + 0.20 * mem_field)
        mem_term = memory_gain * mem_field if self.memory_mode == "additive" else 0.0

        prev_core = None
        prev_spread = None
        steps_used = 0

        for k in range(max_steps):
            core = torch.sigmoid(core_scale * z_core)
            spread = torch.sigmoid(spread_scale * z_spread)

            if prev_core is not None:
                delta = (core - prev_core).abs().mean() + (spread - prev_spread).abs().mean()
                if delta.item() < stop_tol:
                    break

            phi_x = grad_x(phi)
            phi_y = grad_y(phi)
            phi_grad_mag = torch.sqrt(phi_x**2 + phi_y**2 + 1e-6)

            elastic = 0.5 * (
                stiff[0] * phi_y**2 +
                stiff[1] * (-phi_y)**2 +
                stiff[2] * phi_x**2 +
                stiff[3] * (-phi_x)**2
            )
            degraded = (1.0 - core) ** 2 * elastic

            core_drive = (
                bridge_scale * endpoints
                + 0.08 * charge.abs()
                + dir_scale * (dir_x.abs() + dir_y.abs())
                + phi_drive_scale * phi_grad_mag
                + 0.10 * degraded
                + mem_term
                - local_obs_push * obstacle_repulsion
                - local_gc * (
                    core / local_l
                    + 0.20 * laplacian(core)
                    + 2.0 * core * (1.0 - core) * (1.0 - 2.0 * core)
                )
            )

            spread_drive = (
                0.25 * core
                + 0.10 * phi_grad_mag
                - local_spread_pen * (spread - 0.35)
                + 0.5 * mem_term
                - local_obs_push * 0.75 * obstacle_repulsion
                - local_gc * (
                    spread / (local_l * 1.2)
                    + 0.12 * laplacian(spread)
                    + 2.0 * spread * (1.0 - spread) * (1.0 - 2.0 * spread)
                )
            )

            phi_drive = (
                0.55 * laplacian(phi)
                + 0.65 * charge
                + 0.25 * endpoints
                + 0.15 * (dir_x + dir_y)
                + (0.03 * mem_term if self.memory_mode == "additive" else 0.0)
                - 0.08 * obstacle_repulsion
                - 0.06 * phi
                - 0.10 * core * phi
            )

            z_core = z_core + 0.15 * torch.tanh(core_drive)
            z_spread = z_spread + 0.11 * torch.tanh(spread_drive)
            phi = phi + 0.04 * torch.tanh(phi_drive)

            prev_core = core.detach()
            prev_spread = spread.detach()
            steps_used = k + 1

        core = torch.sigmoid(core_scale * z_core)
        spread = torch.sigmoid(spread_scale * z_spread)
        final_prob = core * spread
        logits = 8.0 * (final_prob - 0.5) + readout_scale * self.readout(torch.cat([core, spread, phi], dim=1))
        return logits, final_prob, core, spread, phi, steps_used

# ----------------------
# Training: PF²V family
# ----------------------
def train_pf2v_model(
    model,
    memory_mode="none",
    epochs=20,
    batch_size=4,
    size=48,
    max_steps_train=8,
    use_thinness=False,
):
    opt = torch.optim.Adam(model.parameters(), lr=8e-4)

    for epoch in range(1, epochs + 1):
        model.train()

        t = (epoch - 1) / max(1, (epochs - 1))
        core_scale = 3.0 + 4.0 * t
        spread_scale = 2.5 + 3.0 * t
        l_value = 0.55 - 0.15 * t
        obstacle_push = 0.18 + 0.25 * t
        corridor_sigma = 1.60 - 0.30 * t
        core_sigma = 0.50 - 0.08 * t
        spread_penalty = 0.10 + 0.10 * t

        obs, corridor_target, core_target, obstacle_mask, start_xy, waypoint_xy, goal_xy = make_batch(
            batch_size=batch_size,
            size=size,
            device=device,
            corridor_sigma=corridor_sigma,
            core_sigma=core_sigma,
            hard=False,
        )

        memory_in = None
        if memory_mode in ("additive", "material"):
            blur = F.avg_pool2d(core_target, kernel_size=3, stride=1, padding=1)
            hint_mask = (torch.rand(batch_size, 1, 1, 1, device=device) < 0.5).float()
            memory_in = hint_mask * blur

        logits, prob, core, spread, phi, steps_used = model(
            obs,
            memory=memory_in,
            core_scale=core_scale,
            spread_scale=spread_scale,
            l_value=l_value,
            obstacle_push=obstacle_push,
            spread_penalty=spread_penalty,
            max_steps=max_steps_train,
        )

        pos = corridor_target.sum().clamp_min(1.0)
        neg = corridor_target.numel() - pos
        pos_weight = (neg / pos).clamp(1.0, 40.0)

        bce_pred = F.binary_cross_entropy_with_logits(logits, corridor_target, pos_weight=pos_weight)
        bce_core = F.binary_cross_entropy(core.clamp(1e-4, 1 - 1e-4), core_target)
        bce_spread = F.binary_cross_entropy(spread.clamp(1e-4, 1 - 1e-4), corridor_target)
        dice = dice_loss_from_prob(prob, corridor_target)

        edge_loss = (
            F.mse_loss(grad_x(prob), grad_x(corridor_target)) +
            F.mse_loss(grad_y(prob), grad_y(corridor_target))
        )
        lap_loss = F.mse_loss(laplacian(prob), laplacian(corridor_target))
        outside_loss = ((1.0 - corridor_target) * prob).mean()
        obstacle_penalty = ((prob * obstacle_mask).sum() / (obstacle_mask.sum() + 1e-6))

        route_center = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.0)
        route_side_p = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.08)
        route_side_m = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=-0.08)
        direct_line = sample_segment_probs(prob, start_xy, goal_xy, num=40, offset=0.0)

        route_center_loss = F.binary_cross_entropy(route_center.clamp(1e-4, 1 - 1e-4), torch.ones_like(route_center))
        route_side_loss = 0.5 * (
            F.binary_cross_entropy(route_side_p.clamp(1e-4, 1 - 1e-4), torch.zeros_like(route_side_p)) +
            F.binary_cross_entropy(route_side_m.clamp(1e-4, 1 - 1e-4), torch.zeros_like(route_side_m))
        )
        direct_loss = F.binary_cross_entropy(direct_line.clamp(1e-4, 1 - 1e-4), torch.zeros_like(direct_line))
        route_gap_loss = F.relu(0.80 - route_center).mean()

        loss = (
            1.00 * bce_pred +
            0.35 * bce_core +
            0.16 * bce_spread +
            0.45 * dice +
            0.12 * edge_loss +
            0.08 * lap_loss +
            0.05 * outside_loss +
            0.14 * route_center_loss +
            0.10 * route_side_loss +
            0.08 * direct_loss +
            0.10 * route_gap_loss +
            0.12 * obstacle_penalty
        )

        if use_thinness:
            core_line = sample_polyline_probs(core, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.0)
            core_side_p = sample_polyline_probs(core, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.08)
            core_side_m = sample_polyline_probs(core, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=-0.08)

            thin_loss = F.binary_cross_entropy(core.clamp(1e-4, 1 - 1e-4), core_target)
            core_line_loss = F.binary_cross_entropy(core_line.clamp(1e-4, 1 - 1e-4), torch.ones_like(core_line))
            core_side_loss = 0.5 * (
                F.binary_cross_entropy(core_side_p.clamp(1e-4, 1 - 1e-4), torch.zeros_like(core_side_p)) +
                F.binary_cross_entropy(core_side_m.clamp(1e-4, 1 - 1e-4), torch.zeros_like(core_side_m))
            )
            area_loss = core.mean()
            skeleton_reg = 0.5 * (grad_x(core).abs().mean() + grad_y(core).abs().mean())

            loss = (
                loss +
                0.25 * thin_loss +
                0.15 * core_line_loss +
                0.10 * core_side_loss +
                0.10 * area_loss +
                0.08 * skeleton_reg
            )

        opt.zero_grad()
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
        opt.step()

        if epoch == 1 or epoch % 5 == 0:
            model.eval()
            with torch.no_grad():
                logits_e, prob_e, core_e, spread_e, _, steps_e = model(
                    obs,
                    memory=memory_in,
                    core_scale=core_scale,
                    spread_scale=spread_scale,
                    l_value=l_value,
                    obstacle_push=obstacle_push,
                    spread_penalty=spread_penalty,
                    max_steps=max_steps_train,
                )
                m = eval_metrics_from_prob(
                    prob_e, corridor_target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
                    thresh=0.35, core_prob=core_e, spread_prob=spread_e
                )

            tag = "NONE" if memory_mode == "none" else ("ADDITIVE" if memory_mode == "additive" else "MATERIAL")
            if use_thinness:
                tag = "MAT-THIN"

            print(
                f"[{tag:>9}] epoch {epoch:03d} | loss {loss.item():.4f} | "
                f"soft_iou {m['soft_iou']:.4f} | hard_iou {m['hard_iou']:.4f} | "
                f"route_ratio {m['route_ratio']:.4f} | obs_ov {m['obstacle_overlap']:.4f} | "
                f"steps {steps_e}"
            )

    return model

# ----------------------
# Evaluation helpers
# ----------------------
def run_repeated_passes(model, memory_mode, obs, target, obstacle_mask, start_xy, waypoint_xy, goal_xy, passes=3, cfg=None):
    rows = []
    cfg = cfg or {}
    memory = torch.zeros_like(obstacle_mask)

    with torch.no_grad():
        for p in range(passes):
            mem_in = memory if memory_mode in ("additive", "material") else None

            logits, prob, core, spread, phi, steps_used = model(
                obs,
                memory=mem_in,
                core_scale=cfg.get("core_scale", 6.0),
                spread_scale=cfg.get("spread_scale", 4.5),
                l_value=cfg.get("l_value", 0.40),
                spiral_scale=cfg.get("spiral_scale", 1.0),
                qdmn_scale=cfg.get("qdmn_scale", 1.0),
                obstacle_push=cfg.get("obstacle_push", 0.35),
                bridge_scale=cfg.get("bridge_scale", 0.12),
                dir_scale=cfg.get("dir_scale", 0.06),
                phi_drive_scale=cfg.get("phi_drive_scale", 0.35),
                spread_penalty=cfg.get("spread_penalty", 0.18),
                readout_scale=cfg.get("readout_scale", 0.15),
                memory_gain=cfg.get("memory_gain", 0.18),
                max_steps=cfg.get("max_steps", None),
                stop_tol=cfg.get("stop_tol", 1e-4),
            )

            m = eval_metrics_from_prob(
                prob, target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
                thresh=cfg.get("thresh", 0.35), core_prob=core, spread_prob=spread
            )
            m["setting"] = f"pass_{p+1}"
            m["steps_used"] = float(steps_used)
            rows.append(m)

            if memory_mode in ("additive", "material"):
                memory = harden_memory(
                    memory, core, obstacle_mask,
                    decay=cfg.get("memory_decay", 0.82),
                    gain=cfg.get("memory_gain", 0.18),
                )

    return rows, prob, core, memory

def sweep_steps(model, memory_mode, obs, target, obstacle_mask, start_xy, waypoint_xy, goal_xy, step_list, cfg=None):
    cfg = cfg or {}
    rows = []

    with torch.no_grad():
        for s in step_list:
            mem_in = torch.zeros_like(obstacle_mask) if memory_mode in ("additive", "material") else None
            logits, prob, core, spread, phi, steps_used = model(
                obs,
                memory=mem_in,
                core_scale=cfg.get("core_scale", 6.0),
                spread_scale=cfg.get("spread_scale", 4.5),
                l_value=cfg.get("l_value", 0.40),
                spiral_scale=cfg.get("spiral_scale", 1.0),
                qdmn_scale=cfg.get("qdmn_scale", 1.0),
                obstacle_push=cfg.get("obstacle_push", 0.35),
                bridge_scale=cfg.get("bridge_scale", 0.12),
                dir_scale=cfg.get("dir_scale", 0.06),
                phi_drive_scale=cfg.get("phi_drive_scale", 0.35),
                spread_penalty=cfg.get("spread_penalty", 0.18),
                readout_scale=cfg.get("readout_scale", 0.15),
                memory_gain=cfg.get("memory_gain", 0.18),
                max_steps=s,
                stop_tol=cfg.get("stop_tol", 1e-4),
            )
            m = eval_metrics_from_prob(
                prob, target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
                thresh=cfg.get("thresh", 0.35), core_prob=core, spread_prob=spread
            )
            m["setting"] = f"steps_{s}"
            m["steps_used"] = float(steps_used)
            rows.append(m)

    return rows

def sweep_thresholds(model, memory_mode, obs, target, obstacle_mask, start_xy, waypoint_xy, goal_xy, step_value, thresholds, cfg=None):
    cfg = cfg or {}
    rows = []
    with torch.no_grad():
        mem_in = torch.zeros_like(obstacle_mask) if memory_mode in ("additive", "material") else None
        logits, prob, core, spread, phi, steps_used = model(
            obs,
            memory=mem_in,
            core_scale=cfg.get("core_scale", 6.0),
            spread_scale=cfg.get("spread_scale", 4.5),
            l_value=cfg.get("l_value", 0.40),
            spiral_scale=cfg.get("spiral_scale", 1.0),
            qdmn_scale=cfg.get("qdmn_scale", 1.0),
            obstacle_push=cfg.get("obstacle_push", 0.35),
            bridge_scale=cfg.get("bridge_scale", 0.12),
            dir_scale=cfg.get("dir_scale", 0.06),
            phi_drive_scale=cfg.get("phi_drive_scale", 0.35),
            spread_penalty=cfg.get("spread_penalty", 0.18),
            readout_scale=cfg.get("readout_scale", 0.15),
            memory_gain=cfg.get("memory_gain", 0.18),
            max_steps=step_value,
            stop_tol=cfg.get("stop_tol", 1e-4),
        )

        for th in thresholds:
            m = eval_metrics_from_prob(
                prob, target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
                thresh=th, core_prob=core, spread_prob=spread
            )
            m["setting"] = f"step_{step_value}_th_{th:.2f}"
            m["step"] = float(step_value)
            m["threshold"] = float(th)
            m["steps_used"] = float(steps_used)
            rows.append(m)

    return rows

# ----------------------
# Negative control: soft shortest-path baseline
# ----------------------
class SoftShortestPathNet(nn.Module):
    def __init__(self, hidden=32, steps=24):
        super().__init__()
        self.steps = steps
        self.encoder = nn.Sequential(
            nn.Conv2d(8, hidden, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(hidden, hidden, 3, padding=1),
            nn.GELU(),
        )
        self.cost_head = nn.Conv2d(hidden, 1, 1)
        self.value_head = nn.Conv2d(hidden, 1, 1)

        self.diffusion = nn.Parameter(torch.tensor(0.16))
        self.goal_pull = nn.Parameter(torch.tensor(1.10))
        self.source_push = nn.Parameter(torch.tensor(1.20))
        self.obstacle_repulse = nn.Parameter(torch.tensor(1.35))
        self.value_gain = nn.Parameter(torch.tensor(0.80))

    def forward(self, obs, max_steps=None, temperature=1.0):
        h = self.encoder(obs)
        cost = F.softplus(self.cost_head(h))
        value = self.value_head(h)

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        obstacle = obs[:, 3:4]

        if max_steps is None:
            max_steps = self.steps

        for _ in range(max_steps):
            value_update = (
                self.diffusion * laplacian(value)
                + self.value_gain * torch.tanh(-cost)
                + self.source_push * source
                - self.goal_pull * goal
                - self.obstacle_repulse * obstacle
            )
            value = value + 0.10 * torch.tanh(value_update)

        value_z = (value - value.mean(dim=(2, 3), keepdim=True)) / value.std(dim=(2, 3), keepdim=True).clamp_min(1e-6)
        cost_z = (cost - cost.mean(dim=(2, 3), keepdim=True)) / cost.std(dim=(2, 3), keepdim=True).clamp_min(1e-6)

        logits = -0.85 * cost_z + 1.05 * value_z - 1.20 * obstacle
        prob = torch.sigmoid(logits / temperature)

        return {
            "cost": cost,
            "value": value,
            "logits": logits,
            "prob": prob,
        }

def train_soft_control(model, epochs=20, batch_size=4, size=48, train_steps=24):
    opt = torch.optim.Adam(model.parameters(), lr=8e-4)

    for epoch in range(1, epochs + 1):
        model.train()

        obs, target, core_target, obstacle_mask, start_xy, waypoint_xy, goal_xy = make_batch(
            batch_size=batch_size,
            size=size,
            device=device,
            hard=False
        )

        out = model(obs, max_steps=train_steps, temperature=1.0)
        prob = out["prob"]
        logits = out["logits"]
        value = out["value"]
        obstacle = obs[:, 3:4]

        pos = target.sum().clamp_min(1.0)
        neg = target.numel() - pos
        pos_weight = (neg / pos).clamp(1.0, 40.0)

        bce = F.binary_cross_entropy_with_logits(logits, target, pos_weight=pos_weight)
        dice = dice_loss_from_prob(prob, target)
        smooth = grad_x(prob).abs().mean() + grad_y(prob).abs().mean()
        obstacle_penalty = (prob * obstacle).mean()

        value_gx = grad_x(value)
        value_gy = grad_y(value)
        eikonal = ((torch.sqrt(value_gx**2 + value_gy**2 + 1e-6) - 1.0) ** 2).mean()

        route_pred = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.0)
        route_tgt = sample_polyline_probs(target, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.0)
        route_loss = F.mse_loss(route_pred, route_tgt)

        loss = (
            0.90 * bce +
            0.55 * dice +
            0.10 * smooth +
            0.20 * obstacle_penalty +
            0.08 * eikonal +
            0.35 * route_loss
        )

        opt.zero_grad()
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
        opt.step()

        if epoch == 1 or epoch % 5 == 0:
            model.eval()
            with torch.no_grad():
                out_e = model(obs, max_steps=train_steps, temperature=1.0)
                m = eval_metrics_from_prob(
                    out_e["prob"], target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
                    thresh=0.35, phi_prob=torch.sigmoid(out_e["value"])
                )
            print(
                f"[SOFT] epoch {epoch:03d} | loss {loss.item():.4f} | "
                f"soft_iou {m['soft_iou']:.4f} | hard_iou {m['hard_iou']:.4f} | "
                f"route_ratio {m['route_ratio']:.4f} | obs_ov {m['obstacle_overlap']:.4f}"
            )

    return model

def eval_soft_control(model, obs, target, obstacle_mask, start_xy, waypoint_xy, goal_xy, step_list, thresholds):
    rows_step = []
    rows_th = []

    model.eval()
    with torch.no_grad():
        for s in step_list:
            out = model(obs, max_steps=s, temperature=1.0)
            prob = out["prob"]
            value = out["value"]
            m = eval_metrics_from_prob(
                prob, target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
                thresh=0.35, phi_prob=torch.sigmoid(value)
            )
            m["setting"] = f"steps_{s}"
            m["steps_used"] = float(s)
            rows_step.append(m)

            for th in thresholds:
                mt = eval_metrics_from_prob(
                    prob, target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
                    thresh=th, phi_prob=torch.sigmoid(value)
                )
                mt["setting"] = f"steps_{s}_th_{th:.2f}"
                mt["step"] = float(s)
                mt["threshold"] = float(th)
                rows_th.append(mt)

    return rows_step, rows_th

# ============================================================
# Train PF²V family
# ============================================================
base_model = MaterialPF2V(memory_mode="none", inner_steps=8, size=48).to(device)
add_model = MaterialPF2V(memory_mode="additive", inner_steps=8, size=48).to(device)
mat_model = MaterialPF2V(memory_mode="material", inner_steps=8, size=48).to(device)
mat_thin_model = MaterialPF2V(memory_mode="material", inner_steps=8, size=48).to(device)

print("\nTraining base model...")
base_model = train_pf2v_model(base_model, memory_mode="none", epochs=20, batch_size=4, size=48, max_steps_train=8, use_thinness=False)

print("\nTraining additive-memory model...")
add_model = train_pf2v_model(add_model, memory_mode="additive", epochs=20, batch_size=4, size=48, max_steps_train=8, use_thinness=False)

print("\nTraining material-memory model...")
mat_model = train_pf2v_model(mat_model, memory_mode="material", epochs=20, batch_size=4, size=48, max_steps_train=8, use_thinness=False)

print("\nTraining material-thin model...")
mat_thin_model = train_pf2v_model(mat_thin_model, memory_mode="material", epochs=20, batch_size=4, size=48, max_steps_train=8, use_thinness=True)

# ============================================================
# Held-out standard batch
# ============================================================
eval_batch_size = 32
with torch.no_grad():
    obs_eval, corridor_eval, core_eval, obstacle_eval, start_eval, waypoint_eval, goal_eval = make_batch(
        batch_size=eval_batch_size,
        size=48,
        device=device,
        corridor_sigma=1.35,
        core_sigma=0.42,
        hard=False
    )

step_list = [4, 8, 12, 16]
thresholds = [0.25, 0.35, 0.50]

base_repeat_rows, base_prob_last, base_core_last, _ = run_repeated_passes(
    base_model, "none", obs_eval, corridor_eval, obstacle_eval, start_eval, waypoint_eval, goal_eval,
    passes=3, cfg=dict(max_steps=8)
)
add_repeat_rows, add_prob_last, add_core_last, add_mem_last = run_repeated_passes(
    add_model, "additive", obs_eval, corridor_eval, obstacle_eval, start_eval, waypoint_eval, goal_eval,
    passes=3, cfg=dict(max_steps=8, memory_gain=0.18, memory_decay=0.82)
)
mat_repeat_rows, mat_prob_last, mat_core_last, mat_mem_last = run_repeated_passes(
    mat_model, "material", obs_eval, corridor_eval, obstacle_eval, start_eval, waypoint_eval, goal_eval,
    passes=3, cfg=dict(max_steps=8, memory_gain=0.18, memory_decay=0.82)
)
thin_repeat_rows, thin_prob_last, thin_core_last, thin_mem_last = run_repeated_passes(
    mat_thin_model, "material", obs_eval, corridor_eval, obstacle_eval, start_eval, waypoint_eval, goal_eval,
    passes=3, cfg=dict(max_steps=8, memory_gain=0.18, memory_decay=0.82)
)

base_step_rows = sweep_steps(base_model, "none", obs_eval, corridor_eval, obstacle_eval, start_eval, waypoint_eval, goal_eval, step_list)
add_step_rows = sweep_steps(add_model, "additive", obs_eval, corridor_eval, obstacle_eval, start_eval, waypoint_eval, goal_eval, step_list)
mat_step_rows = sweep_steps(mat_model, "material", obs_eval, corridor_eval, obstacle_eval, start_eval, waypoint_eval, goal_eval, step_list)
thin_step_rows = sweep_steps(mat_thin_model, "material", obs_eval, corridor_eval, obstacle_eval, start_eval, waypoint_eval, goal_eval, step_list)

thin_threshold_rows = []
for s in step_list:
    thin_threshold_rows.extend(
        sweep_thresholds(mat_thin_model, "material", obs_eval, corridor_eval, obstacle_eval, start_eval, waypoint_eval, goal_eval, s, thresholds)
    )

best_base_step = max(base_step_rows, key=lambda r: (r["hard_iou"], r["route_ratio"]))
best_add_step = max(add_step_rows, key=lambda r: (r["hard_iou"], r["route_ratio"]))
best_mat_step = max(mat_step_rows, key=lambda r: (r["hard_iou"], r["route_ratio"]))
best_thin_step = max(thin_step_rows, key=lambda r: (r["hard_iou"], r["route_ratio"]))

best_thin_035_rows = [r for r in thin_threshold_rows if abs(r["threshold"] - 0.35) < 1e-8]
best_thin_035 = max(best_thin_035_rows, key=lambda r: (r["hard_iou"], r["route_ratio"]))
best_thin_all_thresh = max(thin_threshold_rows, key=lambda r: (r["hard_iou"], r["route_ratio"]))

keys_step = ["soft_iou", "hard_iou", "route_ratio", "obstacle_overlap", "route_gap", "sharpness", "connectivity", "steps_used"]
keys_thresh = ["soft_iou", "hard_iou", "route_ratio", "obstacle_overlap", "route_gap", "sharpness", "connectivity", "threshold"]

print_table(base_repeat_rows, "BASE MODEL: repeated passes on held-out batch", keys_step)
