hard_gen_best_step = max(hard_gen_step_rows, key=lambda r: (r["hard_iou"], r["route_ratio"]))
hard_gen_best_th = max(hard_gen_th_rows, key=lambda r: (r["hard_iou"], r["route_ratio"]))

