import numpy as np
import pandas as pd
import random
import torch
import csv
import json

# ------------------------------------------------------------
# Robustness evaluation for the already-trained models
# Assumes these objects already exist in memory:
#   base_model, add_model, mat_model, mat_thin_model, soft_model
#   make_batch, sweep_steps, sweep_thresholds, eval_soft_control
#   device
# ------------------------------------------------------------

def set_all_seeds(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

def best_row(rows, key="hard_iou"):
    return max(rows, key=lambda r: (r[key], r["route_ratio"]))

def summarize_rows(rows, label):
    bstep = best_row(rows)
    return {
        "label": label,
        "best_step": int(bstep.get("steps_used", bstep.get("step", -1))),
        "best_hard_iou": float(bstep["hard_iou"]),
        "best_soft_iou": float(bstep["soft_iou"]),
        "best_route_ratio": float(bstep["route_ratio"]),
        "best_obstacle_overlap": float(bstep["obstacle_overlap"]),
        "best_connectivity": float(bstep["connectivity"]),
    }

def run_pf2v_robustness(
    seeds=(0, 1, 2, 3, 4),
    batch_size=32,
    size=48,
    step_list=(4, 8, 12, 16),
    thresholds=(0.25, 0.35, 0.50),
):
    records = []

    for seed in seeds:
        set_all_seeds(seed)

        # Standard held-out batch
        obs, corridor, core, obstacle, start_xy, waypoint_xy, goal_xy = make_batch(
            batch_size=batch_size,
            size=size,
            device=device,
            corridor_sigma=1.35,
            core_sigma=0.42,
            hard=False,
        )

        # Harder generalization batch
        obs_h, corridor_h, core_h, obstacle_h, start_xy_h, waypoint_xy_h, goal_xy_h = make_batch(
            batch_size=batch_size,
            size=size,
            device=device,
            corridor_sigma=1.25,
            core_sigma=0.38,
            obstacle_sigma=6.0,
            hard=True,
            multi_obstacles=True,
        )

        # PF²V material-thin on standard set
        thin_step_std = sweep_steps(mat_thin_model, "material", obs, corridor, obstacle, start_xy, waypoint_xy, goal_xy, list(step_list))
        thin_th_std = []
        for s in step_list:
            thin_th_std.extend(
                sweep_thresholds(
                    mat_thin_model, "material",
                    obs, corridor, obstacle, start_xy, waypoint_xy, goal_xy,
                    s, list(thresholds)
                )
            )

        # PF²V material-thin on hard set
        thin_step_hard = sweep_steps(mat_thin_model, "material", obs_h, corridor_h, obstacle_h, start_xy_h, waypoint_xy_h, goal_xy_h, list(step_list))
        thin_th_hard = []
        for s in step_list:
            thin_th_hard.extend(
                sweep_thresholds(
                    mat_thin_model, "material",
                    obs_h, corridor_h, obstacle_h, start_xy_h, waypoint_xy_h, goal_xy_h,
                    s, list(thresholds)
                )
            )

        # Soft control on standard set
        soft_step_std, soft_th_std = eval_soft_control(
            soft_model, obs, corridor, obstacle, start_xy, waypoint_xy, goal_xy,
            step_list=[8, 16, 24, 32],
            thresholds=[0.20, 0.30, 0.35, 0.50],
        )

        # Soft control on hard set
        soft_step_hard, soft_th_hard = eval_soft_control(
            soft_model, obs_h, corridor_h, obstacle_h, start_xy_h, waypoint_xy_h, goal_xy_h,
            step_list=[8, 16, 24, 32],
            thresholds=[0.20, 0.30, 0.35, 0.50],
        )

        # Summaries
        records.append({
            "seed": seed,
            **summarize_rows(thin_step_std, "thin_std_step"),
            "set": "std",
            "model": "material-thin",
        })
        records.append({
            "seed": seed,
            **summarize_rows(thin_th_std, "thin_std_thresh"),
            "set": "std",
            "model": "material-thin-thresh",
        })
        records.append({
            "seed": seed,
            **summarize_rows(thin_step_hard, "thin_hard_step"),
            "set": "hard",
            "model": "material-thin",
        })
        records.append({
            "seed": seed,
            **summarize_rows(thin_th_hard, "thin_hard_thresh"),
            "set": "hard",
            "model": "material-thin-thresh",
        })
        records.append({
            "seed": seed,
            **summarize_rows(soft_step_std, "soft_std_step"),
            "set": "std",
            "model": "soft-control",
        })
        records.append({
            "seed": seed,
            **summarize_rows(soft_th_std, "soft_std_thresh"),
            "set": "std",
            "model": "soft-control-thresh",
        })
        records.append({
            "seed": seed,
            **summarize_rows(soft_step_hard, "soft_hard_step"),
            "set": "hard",
            "model": "soft-control",
        })
        records.append({
            "seed": seed,
            **summarize_rows(soft_th_hard, "soft_hard_thresh"),
            "set": "hard",
            "model": "soft-control-thresh",
        })

        print(f"Finished seed {seed}")

    df = pd.DataFrame(records)

    # Aggregate into mean/std by model and set
    agg = (
        df.groupby(["model", "set"])
          .agg(
              best_hard_iou_mean=("best_hard_iou", "mean"),
              best_hard_iou_std=("best_hard_iou", "std"),
              best_route_ratio_mean=("best_route_ratio", "mean"),
              best_route_ratio_std=("best_route_ratio", "std"),
              best_obstacle_overlap_mean=("best_obstacle_overlap", "mean"),
              best_obstacle_overlap_std=("best_obstacle_overlap", "std"),
              best_connectivity_mean=("best_connectivity", "mean"),
              best_connectivity_std=("best_connectivity", "std"),
          )
          .reset_index()
    )

    print("\nROBUSTNESS SUMMARY")
    print(agg.to_string(index=False))

    df.to_csv("pf2v_robustness_rows.csv", index=False)
    agg.to_csv("pf2v_robustness_summary.csv", index=False)
    print("\nSaved: pf2v_robustness_rows.csv")
    print("Saved: pf2v_robustness_summary.csv")

    return df, agg

# Run it
robust_rows, robust_summary = run_pf2v_robustness(
    seeds=(0, 1, 2),
    batch_size=32,
    size=48,
    step_list=(4, 8, 12, 16),
    thresholds=(0.25, 0.35, 0.50),
)

