import torch
import torch.nn as nn
import torch.nn.functional as F
import random
import numpy as np
import matplotlib.pyplot as plt
import json
import csv
import pandas as pd

# ============================================================
# PF²V FINAL FOCUS RUN
#   Goal:
#     - strengthen core commitment
#     - improve visible connectivity if possible
#     - test standard + harder generalization batches
#     - compare step sweep + threshold sweep
#     - save final paper assets
# ============================================================

# ----------------------
# Setup
# ----------------------
torch.manual_seed(42)
np.random.seed(42)
random.seed(42)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", device)

# ----------------------
# Basic operators
# ----------------------
def grad_x(x):
    dx = x[:, :, :, 1:] - x[:, :, :, :-1]
    return F.pad(dx, (0, 1, 0, 0))

def grad_y(x):
    dy = x[:, :, 1:, :] - x[:, :, :-1, :]
    return F.pad(dy, (0, 0, 0, 1))

def laplacian(x):
    kernel = torch.tensor(
        [[0.0, 1.0, 0.0],
         [1.0, -4.0, 1.0],
         [0.0, 1.0, 0.0]],
        device=x.device, dtype=x.dtype
    ).view(1, 1, 3, 3)
    return F.conv2d(x, kernel, padding=1)

def gaussian_blob(size, x0, y0, sigma=1.5, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    dist2 = (x.float() - x0) ** 2 + (y.float() - y0) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def soft_line_mask(size, x0, y0, x1, y1, sigma=1.5, device="cpu"):
    y, x = torch.meshgrid(
        torch.arange(size, device=device),
        torch.arange(size, device=device),
        indexing="ij"
    )
    x = x.float()
    y = y.float()

    x0 = float(x0)
    y0 = float(y0)
    x1 = float(x1)
    y1 = float(y1)

    vx = x1 - x0
    vy = y1 - y0
    denom = vx * vx + vy * vy + 1e-6

    t = ((x - x0) * vx + (y - y0) * vy) / denom
    t = torch.clamp(t, 0.0, 1.0)

    px = x0 + t * vx
    py = y0 + t * vy

    dist2 = (x - px) ** 2 + (y - py) ** 2
    return torch.exp(-dist2 / (2 * sigma ** 2)).unsqueeze(0).unsqueeze(0)

def hard_iou_from_prob(prob, target, thresh=0.35, eps=1e-6):
    pred = (prob > thresh).float()
    tgt = (target > 0.5).float()
    inter = (pred * tgt).sum(dim=(1, 2, 3))
    union = ((pred + tgt) > 0).float().sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def soft_iou_from_prob(prob, target, eps=1e-6):
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = (prob + target - prob * target).sum(dim=(1, 2, 3))
    return ((inter + eps) / (union + eps)).mean()

def dice_loss_from_prob(prob, target, eps=1e-6):
    inter = (prob * target).sum(dim=(1, 2, 3))
    union = prob.sum(dim=(1, 2, 3)) + target.sum(dim=(1, 2, 3))
    return (1.0 - (2.0 * inter + eps) / (union + eps)).mean()

def connectivity_estimate(prob, thresh=0.35):
    binary = (prob > thresh).float()
    horizontal = 0.0
    vertical = 0.0
    if binary.shape[-1] > 1:
        horizontal = (binary[:, :, :, 1:] * binary[:, :, :, :-1]).mean().item()
    if binary.shape[-2] > 1:
        vertical = (binary[:, :, 1:, :] * binary[:, :, :-1, :]).mean().item()
    return horizontal + vertical

def sample_segment_probs(prob, start_xy, goal_xy, num=40, offset=0.0):
    B = prob.shape[0]
    t = torch.linspace(0, 1, num, device=prob.device).view(1, num, 1)

    start = start_xy.view(B, 1, 2)
    goal = goal_xy.view(B, 1, 2)

    direction = goal - start
    norm = torch.linalg.norm(direction, dim=-1, keepdim=True).clamp_min(1e-6)
    unit = direction / norm
    perp = torch.cat([-unit[..., 1:2], unit[..., 0:1]], dim=-1)

    pts = start * (1.0 - t) + goal * t + offset * perp
    pts = pts.clamp(-1.0, 1.0)

    grid = pts.view(B, num, 1, 2)
    sampled = F.grid_sample(prob, grid, mode="bilinear", padding_mode="zeros", align_corners=True)
    return sampled[:, 0, :, 0]

def sample_polyline_probs(prob, p0, p1, p2, num_per_segment=20, offset=0.0):
    a = sample_segment_probs(prob, p0, p1, num=num_per_segment, offset=offset)
    b = sample_segment_probs(prob, p1, p2, num=num_per_segment, offset=offset)
    return torch.cat([a, b], dim=1)

def route_metrics(prob, start_xy, waypoint_xy, goal_xy, thresh=0.35, obstacle_mask=None):
    direct = sample_segment_probs(prob, start_xy, goal_xy, num=40, offset=0.0)
    route = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.0)
    side_p = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=0.08)
    side_m = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=20, offset=-0.08)

    direct_mean = direct.mean().item()
    route_mean = route.mean().item()
    route_gap = (route < thresh).float().mean().item()
    route_ratio = route_mean / (direct_mean + 1e-6)

    out = {
        "direct_mean": direct_mean,
        "route_mean": route_mean,
        "route_gap": route_gap,
        "route_ratio": route_ratio,
        "side_mean": 0.5 * (side_p.mean().item() + side_m.mean().item()),
    }

    if obstacle_mask is not None:
        out["obstacle_overlap"] = ((prob * obstacle_mask).sum() / (obstacle_mask.sum() + 1e-6)).item()
    else:
        out["obstacle_overlap"] = float("nan")

    return out

def eval_metrics_from_prob(
    prob,
    target,
    obstacle_mask,
    obs,
    start_xy,
    waypoint_xy,
    goal_xy,
    thresh=0.35,
    core_prob=None,
    spread_prob=None,
):
    soft_iou = soft_iou_from_prob(prob, target)
    hard_iou = hard_iou_from_prob(prob, target, thresh=thresh)
    mass = prob.mean()
    sharpness = (prob * (1.0 - prob)).mean()
    conn = connectivity_estimate(prob, thresh=thresh)

    source = obs[:, 0:1]
    goal = obs[:, 1:2]
    source_hit = ((prob * source).sum() / (source.sum() + 1e-6))
    goal_hit = ((prob * goal).sum() / (goal.sum() + 1e-6))

    route = route_metrics(
        prob, start_xy, waypoint_xy, goal_xy,
        thresh=thresh,
        obstacle_mask=obstacle_mask
    )

    active = (prob > thresh).float().sum().item()
    target_active = (target > 0.5).float().sum().item()
    compactness = target_active / (active + target_active + 1e-6)

    out = {
        "soft_iou": float(soft_iou.item()),
        "hard_iou": float(hard_iou.item()),
        "mass": float(mass.item()),
        "sharpness": float(sharpness.item()),
        "connectivity": float(conn),
        "source_hit": float(source_hit.item()),
        "goal_hit": float(goal_hit.item()),
        "compactness": float(compactness),
        **route,
    }

    if core_prob is not None:
        core_route = route_metrics(core_prob, start_xy, waypoint_xy, goal_xy, thresh=thresh)
        out["core_route_mean"] = core_route["route_mean"]
        out["core_route_gap"] = core_route["route_gap"]
        out["core_route_ratio"] = core_route["route_ratio"]
        out["core_mass"] = float(core_prob.mean().item())
        out["core_sharpness"] = float((core_prob * (1.0 - core_prob)).mean().item())

    if spread_prob is not None:
        out["spread_mass"] = float(spread_prob.mean().item())

    return out

def print_table(rows, title, keys):
    print("\n" + "=" * 146)
    print(title)
    print("=" * 146)
    header = f"{'setting':<24}" + "".join([f"{k:>12}" for k in keys])
    print(header)
    print("-" * len(header))
    for i, r in enumerate(rows, 1):
        label = r.get("setting", f"row_{i}")
        line = f"{label:<24}"
        for k in keys:
            line += f"{r.get(k, float('nan')):>12.4f}"
        print(line)
    print("=" * 146)

def print_ranked(rows, key, reverse=True, topk=5):
    ranked = sorted(rows, key=lambda r: r[key], reverse=reverse)[:topk]
    print(f"\nTop {topk} by {key} ({'high' if reverse else 'low'} is better):")
    for r in ranked:
        print(
            f"  {r['setting']:<22} | {key}={r[key]:.4f} | "
            f"hard_iou={r['hard_iou']:.4f} | route_ratio={r['route_ratio']:.4f} | "
            f"obs_ov={r['obstacle_overlap']:.4f} | conn={r['connectivity']:.4f}"
        )

def save_results_json_csv(results_dict, json_path, csv_path):
    def to_jsonable(v):
        if isinstance(v, dict):
            return {str(k): to_jsonable(val) for k, val in v.items()}
        if isinstance(v, list):
            return [to_jsonable(x) for x in v]
        if isinstance(v, tuple):
            return [to_jsonable(x) for x in v]
        if isinstance(v, (np.integer, np.floating)):
            return v.item()
        return v

    with open(json_path, "w") as f:
        json.dump(to_jsonable(results_dict), f, indent=2)

    all_rows = []
    for group_name, rows in results_dict.items():
        if not isinstance(rows, list):
            continue
        for r in rows:
            if isinstance(r, dict):
                rr = dict(r)
                rr["group"] = group_name
                all_rows.append(rr)

    if len(all_rows) == 0:
        print("No tabular rows found for CSV export.")
        return

    fieldnames = sorted(set().union(*[r.keys() for r in all_rows]))
    with open(csv_path, "w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for r in all_rows:
            writer.writerow(r)

# ----------------------
# Synthetic world
# ----------------------
def make_batch(
    batch_size=8,
    size=48,
    device="cpu",
    corridor_sigma=1.40,
    core_sigma=0.42,
    obstacle_sigma=4.5,
    hard=False,
    multi_obstacles=False,
):
    """
    8-channel input:
      0 source blob
      1 goal blob
      2 charge = source - goal
      3 obstacle field
      4 x coordinate
      5 y coordinate
      6 direction x
      7 direction y
    """
    obs = torch.zeros(batch_size, 8, size, size, device=device)
    corridor_target = torch.zeros(batch_size, 1, size, size, device=device)
    core_target = torch.zeros(batch_size, 1, size, size, device=device)
    obstacle_mask = torch.zeros(batch_size, 1, size, size, device=device)

    start_xy = torch.zeros(batch_size, 2, device=device)
    waypoint_xy = torch.zeros(batch_size, 2, device=device)
    goal_xy = torch.zeros(batch_size, 2, device=device)

    yy, xx = torch.meshgrid(
        torch.linspace(-1, 1, size, device=device),
        torch.linspace(-1, 1, size, device=device),
        indexing="ij"
    )
    coord_x = xx.unsqueeze(0).unsqueeze(0)
    coord_y = yy.unsqueeze(0).unsqueeze(0)

    for b in range(batch_size):
        x0 = random.randint(7, size - 8)
        y0 = random.randint(7, size - 8)
        x1 = random.randint(7, size - 8)
        y1 = random.randint(7, size - 8)

        dx = float(x1 - x0)
        dy = float(y1 - y0)
        dist = (dx * dx + dy * dy) ** 0.5 + 1e-6

        bend_strength = 0.42 if hard else 0.30
        offset_px = max(6.0, bend_strength * dist)

        ux = -dy / dist
        uy = dx / dist
        side = 1.0 if (y1 >= y0) else -1.0

        mx = 0.5 * (x0 + x1)
        my = 0.5 * (y0 + y1)

        wx = np.clip(mx + side * ux * offset_px, 5, size - 6)
        wy = np.clip(my + side * uy * offset_px, 5, size - 6)

        source = gaussian_blob(size, x0, y0, sigma=1.15, device=device)
        goal = gaussian_blob(size, x1, y1, sigma=1.15, device=device)
        charge = source - goal

        route_1 = soft_line_mask(size, x0, y0, wx, wy, sigma=corridor_sigma, device=device)
        route_2 = soft_line_mask(size, wx, wy, x1, y1, sigma=corridor_sigma, device=device)
        corridor = torch.maximum(route_1, route_2)

        core_1 = soft_line_mask(size, x0, y0, wx, wy, sigma=core_sigma, device=device)
        core_2 = soft_line_mask(size, wx, wy, x1, y1, sigma=core_sigma, device=device)
        core = torch.maximum(core_1, core_2)

        obstacle = gaussian_blob(size, mx, my, sigma=obstacle_sigma if not hard else obstacle_sigma * 1.20, device=device)
        if hard and multi_obstacles and random.random() < 0.55:
            dx2 = np.clip(mx + random.choice([-1, 1]) * random.uniform(5.0, 9.0), 4, size - 5)
            dy2 = np.clip(my + random.choice([-1, 1]) * random.uniform(5.0, 9.0), 4, size - 5)
            obstacle2 = gaussian_blob(size, dx2, dy2, sigma=obstacle_sigma * 0.90, device=device)
            obstacle = torch.maximum(obstacle, obstacle2)

        obstacle = obstacle / obstacle.max().clamp_min(1e-6)

        dir_x = torch.full((1, 1, size, size), dx / dist, device=device)
        dir_y = torch.full((1, 1, size, size), dy / dist, device=device)

        obs[b:b+1, 0:1] = source
        obs[b:b+1, 1:2] = goal
        obs[b:b+1, 2:3] = charge
        obs[b:b+1, 3:4] = obstacle
        obs[b:b+1, 4:5] = coord_x
        obs[b:b+1, 5:6] = coord_y
        obs[b:b+1, 6:7] = dir_x
        obs[b:b+1, 7:8] = dir_y

        corridor_target[b:b+1] = corridor
        core_target[b:b+1] = core
        obstacle_mask[b:b+1] = obstacle

        start_xy[b] = torch.tensor([2.0 * x0 / (size - 1) - 1.0, 2.0 * y0 / (size - 1) - 1.0], device=device)
        waypoint_xy[b] = torch.tensor([2.0 * wx / (size - 1) - 1.0, 2.0 * wy / (size - 1) - 1.0], device=device)
        goal_xy[b] = torch.tensor([2.0 * x1 / (size - 1) - 1.0, 2.0 * y1 / (size - 1) - 1.0], device=device)

    return obs, corridor_target, core_target, obstacle_mask, start_xy, waypoint_xy, goal_xy

# ----------------------
# Memory update
# ----------------------
def harden_memory(prev_memory, core, obstacle, decay=0.82, gain=0.35):
    mem = decay * prev_memory + gain * core.detach()
    mem = mem * (1.0 - 0.35 * obstacle)
    return mem.clamp(0.0, 1.0)

# ----------------------
# Focus model: material-memory with stronger commitment
# ----------------------
class MaterialPF2VFocus(nn.Module):
    def __init__(self, memory_mode="material", inner_steps=8, size=48):
        super().__init__()
        assert memory_mode in ("none", "additive", "material")
        self.memory_mode = memory_mode
        self.inner_steps = inner_steps

        in_ch = 9 if memory_mode == "additive" else 8

        self.encoder = nn.Sequential(
            nn.Conv2d(in_ch, 24, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(24, 12, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(12, 1, 3, padding=1),
        )
        self.core_init = nn.Sequential(
            nn.Conv2d(in_ch, 12, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(12, 1, 3, padding=1),
        )
        self.spread_init = nn.Sequential(
            nn.Conv2d(in_ch, 12, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(12, 1, 3, padding=1),
        )
        self.readout = nn.Sequential(
            nn.Conv2d(3, 12, 3, padding=1),
            nn.GELU(),
            nn.Conv2d(12, 1, 1),
        )

        self.qdmn_log_stiff = nn.Parameter(torch.zeros(4))
        self.log_gc = nn.Parameter(torch.tensor(-0.8))
        self.register_buffer("spiral_bias", self._make_spiral(size))

    def _make_spiral(self, size):
        y, x = torch.meshgrid(torch.arange(size), torch.arange(size), indexing="ij")
        y = y.float()
        x = x.float()
        cx = size / 2
        cy = size / 2
        r = torch.sqrt((x - cx) ** 2 + (y - cy) ** 2) + 1e-6
        theta = torch.atan2(y - cy, x - cx)
        spiral = torch.sin(2.5 * theta + 1.1 * torch.log(r))
        return (1.0 + 0.05 * spiral).view(1, 1, size, size)

    def forward(
        self,
        obs,
        memory=None,
        core_scale=6.0,
        spread_scale=4.5,
        l_value=0.40,
        spiral_scale=1.0,
        qdmn_scale=1.0,
        obstacle_push=0.35,
        bridge_scale=0.12,
        dir_scale=0.06,
        phi_drive_scale=0.35,
        spread_penalty=0.18,
        readout_scale=0.15,
        memory_gain=0.18,
        max_steps=None,
        stop_tol=1e-4,
    ):
        if self.memory_mode == "additive":
            if memory is None:
                memory = torch.zeros_like(obs[:, :1])
            x = torch.cat([obs, memory], dim=1)
        else:
            x = obs

        phi = self.encoder(x)
        z_core = self.core_init(x)
        z_spread = self.spread_init(x)

        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        charge = obs[:, 2:3]
        obstacle = obs[:, 3:4]
        dir_x = obs[:, 6:7]
        dir_y = obs[:, 7:8]
        endpoints = source + goal

        obstacle_repulsion = F.avg_pool2d(obstacle, kernel_size=7, stride=1, padding=3)

        spiral_mod = 1.0 + spiral_scale * (self.spiral_bias.to(obs.device, obs.dtype) - 1.0)
        gc = torch.exp(self.log_gc) * spiral_mod
        stiff = (F.softplus(self.qdmn_log_stiff) + 0.10) * qdmn_scale

        if max_steps is None:
            max_steps = self.inner_steps

        if memory is None:
            mem_field = torch.zeros_like(obstacle)
        else:
            mem_field = memory.clamp(0.0, 1.0)

        local_l = (l_value * (1.0 - 0.35 * mem_field)).clamp(0.12, 1.50)
        local_gc = gc * (1.0 - 0.30 * mem_field)
        local_obs_push = obstacle_push * (1.0 - 0.60 * mem_field)
        local_spread_pen = spread_penalty * (1.0 + 0.20 * mem_field)
        mem_term = memory_gain * mem_field if self.memory_mode == "additive" else 0.0

        prev_core = None
        prev_spread = None
        steps_used = 0

        for k in range(max_steps):
            core = torch.sigmoid(core_scale * z_core)
            spread = torch.sigmoid(spread_scale * z_spread)

            if prev_core is not None:
                delta = (core - prev_core).abs().mean() + (spread - prev_spread).abs().mean()
                if delta.item() < stop_tol:
                    break

            phi_x = grad_x(phi)
            phi_y = grad_y(phi)
            phi_grad_mag = torch.sqrt(phi_x**2 + phi_y**2 + 1e-6)

            elastic = 0.5 * (
                stiff[0] * phi_y**2 +
                stiff[1] * (-phi_y)**2 +
                stiff[2] * phi_x**2 +
                stiff[3] * (-phi_x)**2
            )
            degraded = (1.0 - core) ** 2 * elastic

            core_drive = (
                bridge_scale * endpoints
                + 0.08 * charge.abs()
                + dir_scale * (dir_x.abs() + dir_y.abs())
                + phi_drive_scale * phi_grad_mag
                + 0.12 * degraded
                + mem_term
                - local_obs_push * obstacle_repulsion
                - local_gc * (
                    core / local_l
                    + 0.20 * laplacian(core)
                    + 2.0 * core * (1.0 - core) * (1.0 - 2.0 * core)
                )
            )

            spread_drive = (
                0.22 * core
                + 0.10 * phi_grad_mag
                - local_spread_pen * (spread - 0.35)
                + 0.5 * mem_term
                - local_obs_push * 0.75 * obstacle_repulsion
                - local_gc * (
                    spread / (local_l * 1.2)
                    + 0.12 * laplacian(spread)
                    + 2.0 * spread * (1.0 - spread) * (1.0 - 2.0 * spread)
                )
            )

            phi_drive = (
                0.55 * laplacian(phi)
                + 0.65 * charge
                + 0.25 * endpoints
                + 0.15 * (dir_x + dir_y)
                + (0.03 * mem_term if self.memory_mode == "additive" else 0.0)
                - 0.10 * obstacle_repulsion
                - 0.06 * phi
                - 0.12 * core * phi
            )

            z_core = z_core + 0.16 * torch.tanh(core_drive)
            z_spread = z_spread + 0.12 * torch.tanh(spread_drive)
            phi = phi + 0.05 * torch.tanh(phi_drive)

            prev_core = core.detach()
            prev_spread = spread.detach()
            steps_used = k + 1

        core = torch.sigmoid(core_scale * z_core)
        spread = torch.sigmoid(spread_scale * z_spread)
        final_prob = core * spread
        logits = 8.0 * (final_prob - 0.5) + readout_scale * self.readout(torch.cat([core, spread, phi], dim=1))
        return logits, final_prob, core, spread, phi, steps_used

# ----------------------
# Focus training
# ----------------------
def train_focus_model(
    model,
    epochs=28,
    batch_size=4,
    size=48,
    max_steps_train=8,
    hard_mix_prob=0.35,
):
    opt = torch.optim.Adam(model.parameters(), lr=8e-4)

    for epoch in range(1, epochs + 1):
        model.train()
        t = (epoch - 1) / max(1, epochs - 1)

        core_scale = 3.2 + 4.2 * t
        spread_scale = 2.6 + 3.2 * t
        l_value = 0.54 - 0.18 * t
        obstacle_push = 0.20 + 0.35 * t
        spread_penalty = 0.10 + 0.12 * t

        corridor_sigma = 1.50 - 0.25 * t
        core_sigma = 0.48 - 0.14 * t
        obstacle_sigma = 4.8 + 0.8 * t

        hard_case = (random.random() < hard_mix_prob)
        obs, corridor_target, core_target, obstacle_mask, start_xy, waypoint_xy, goal_xy = make_batch(
            batch_size=batch_size,
            size=size,
            device=device,
            corridor_sigma=corridor_sigma,
            core_sigma=core_sigma,
            obstacle_sigma=obstacle_sigma,
            hard=hard_case,
            multi_obstacles=hard_case,
        )

        memory_in = None
        if model.memory_mode in ("additive", "material"):
            blur = F.avg_pool2d(core_target, kernel_size=3, stride=1, padding=1)
            hint_mask = (torch.rand(batch_size, 1, 1, 1, device=device) < 0.55).float()
            memory_in = hint_mask * blur

        logits, prob, core, spread, phi, steps_used = model(
            obs,
            memory=memory_in,
            core_scale=core_scale,
            spread_scale=spread_scale,
            l_value=l_value,
            obstacle_push=obstacle_push,
            spread_penalty=spread_penalty,
            max_steps=max_steps_train,
        )

        pos = corridor_target.sum().clamp_min(1.0)
        neg = corridor_target.numel() - pos
        pos_weight = (neg / pos).clamp(1.0, 40.0)

        bce_pred = F.binary_cross_entropy_with_logits(logits, corridor_target, pos_weight=pos_weight)
        bce_core = F.binary_cross_entropy(core.clamp(1e-4, 1 - 1e-4), core_target)
        bce_spread = F.binary_cross_entropy(spread.clamp(1e-4, 1 - 1e-4), corridor_target)
        dice = dice_loss_from_prob(prob, corridor_target)

        edge_loss = (
            F.mse_loss(grad_x(prob), grad_x(corridor_target)) +
            F.mse_loss(grad_y(prob), grad_y(corridor_target))
        )
        lap_loss = F.mse_loss(laplacian(prob), laplacian(corridor_target))
        outside_loss = ((1.0 - corridor_target) * prob).mean()
        obstacle_penalty = ((prob * obstacle_mask).sum() / (obstacle_mask.sum() + 1e-6))

        route_center = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=0.0)
        route_side_p = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=0.08)
        route_side_m = sample_polyline_probs(prob, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=-0.08)
        direct_line = sample_segment_probs(prob, start_xy, goal_xy, num=48, offset=0.0)

        route_center_loss = F.binary_cross_entropy(route_center.clamp(1e-4, 1 - 1e-4), torch.ones_like(route_center))
        route_side_loss = 0.5 * (
            F.binary_cross_entropy(route_side_p.clamp(1e-4, 1 - 1e-4), torch.zeros_like(route_side_p)) +
            F.binary_cross_entropy(route_side_m.clamp(1e-4, 1 - 1e-4), torch.zeros_like(route_side_m))
        )
        direct_loss = F.binary_cross_entropy(direct_line.clamp(1e-4, 1 - 1e-4), torch.zeros_like(direct_line))
        route_gap_loss = F.relu(0.74 - route_center).mean()

        core_line = sample_polyline_probs(core, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=0.0)
        core_side_p = sample_polyline_probs(core, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=0.08)
        core_side_m = sample_polyline_probs(core, start_xy, waypoint_xy, goal_xy, num_per_segment=24, offset=-0.08)
        source = obs[:, 0:1]
        goal = obs[:, 1:2]
        source_touch = 1.0 - ((core * source).sum() / (source.sum() + 1e-6))
        goal_touch = 1.0 - ((core * goal).sum() / (goal.sum() + 1e-6))
        core_center_loss = F.binary_cross_entropy(core_line.clamp(1e-4, 1 - 1e-4), torch.ones_like(core_line))
        core_side_loss = 0.5 * (
            F.binary_cross_entropy(core_side_p.clamp(1e-4, 1 - 1e-4), torch.zeros_like(core_side_p)) +
            F.binary_cross_entropy(core_side_m.clamp(1e-4, 1 - 1e-4), torch.zeros_like(core_side_m))
        )
        core_area_loss = core.mean()
        skeleton_reg = 0.5 * (grad_x(core).abs().mean() + grad_y(core).abs().mean())

        # Stronger commitment run: centerline + endpoints + thinness + obstacle avoidance
        loss = (
            1.00 * bce_pred +
            0.42 * bce_core +
            0.18 * bce_spread +
            0.50 * dice +
            0.12 * edge_loss +
            0.08 * lap_loss +
            0.06 * outside_loss +
            0.18 * route_center_loss +
            0.12 * route_side_loss +
            0.10 * direct_loss +
            0.12 * route_gap_loss +
            0.14 * obstacle_penalty +
            0.42 * core_center_loss +
            0.16 * core_side_loss +
            0.10 * core_area_loss +
            0.10 * skeleton_reg +
            0.18 * source_touch +
            0.18 * goal_touch
        )

        opt.zero_grad()
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
        opt.step()

        if epoch == 1 or epoch % 5 == 0:
            model.eval()
            with torch.no_grad():
                logits_e, prob_e, core_e, spread_e, _, steps_e = model(
                    obs,
                    memory=memory_in,
                    core_scale=core_scale,
                    spread_scale=spread_scale,
                    l_value=l_value,
                    obstacle_push=obstacle_push,
                    spread_penalty=spread_penalty,
                    max_steps=max_steps_train,
                )
                m = eval_metrics_from_prob(
                    prob_e, corridor_target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
                    thresh=0.35, core_prob=core_e, spread_prob=spread_e
                )

            print(
                f"[FOCUS] epoch {epoch:03d} | loss {loss.item():.4f} | "
                f"soft_iou {m['soft_iou']:.4f} | hard_iou {m['hard_iou']:.4f} | "
                f"route_ratio {m['route_ratio']:.4f} | obs_ov {m['obstacle_overlap']:.4f} | "
                f"conn {m['connectivity']:.4f} | steps {steps_e}"
            )

    return model

# ----------------------
# Evaluation helpers
# ----------------------
def sweep_steps(model, obs, target, obstacle_mask, start_xy, waypoint_xy, goal_xy, step_list, thresh=0.35):
    rows = []
    model.eval()
    with torch.no_grad():
        for s in step_list:
            logits, prob, core, spread, phi, steps_used = model(
                obs,
                memory=torch.zeros_like(obstacle_mask),
                core_scale=6.0,
                spread_scale=4.5,
                l_value=0.40,
                obstacle_push=0.35,
                spread_penalty=0.18,
                max_steps=s,
            )
            m = eval_metrics_from_prob(
                prob, target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
                thresh=thresh, core_prob=core, spread_prob=spread
            )
            m["setting"] = f"steps_{s}"
            m["steps_used"] = float(steps_used)
            rows.append(m)
    return rows

def sweep_thresholds(model, obs, target, obstacle_mask, start_xy, waypoint_xy, goal_xy, step_value, thresholds):
    rows = []
    model.eval()
    with torch.no_grad():
        logits, prob, core, spread, phi, steps_used = model(
            obs,
            memory=torch.zeros_like(obstacle_mask),
            core_scale=6.0,
            spread_scale=4.5,
            l_value=0.40,
            obstacle_push=0.35,
            spread_penalty=0.18,
            max_steps=step_value,
        )
        for th in thresholds:
            m = eval_metrics_from_prob(
                prob, target, obstacle_mask, obs, start_xy, waypoint_xy, goal_xy,
                thresh=th, core_prob=core, spread_prob=spread
            )
            m["setting"] = f"step_{step_value}_th_{th:.2f}"
            m["step"] = float(step_value)
            m["threshold"] = float(th)
            m["steps_used"] = float(steps_used)
            rows.append(m)
    return rows

def eval_on_batch(model, obs, target, obstacle_mask, start_xy, waypoint_xy, goal_xy, step_list, thresholds):
    step_rows = sweep_steps(model, obs, target, obstacle_mask, start_xy, waypoint_xy, goal_xy, step_list)
    th_rows = []
    for s in step_list:
        th_rows.extend(sweep_thresholds(model, obs, target, obstacle_mask, start_xy, waypoint_xy, goal_xy, s, thresholds))
    return step_rows, th_rows

def best_row(rows):
    return max(rows, key=lambda r: (r["hard_iou"], r["connectivity"], r["route_ratio"]))

# ----------------------
# Train or initialize from prior material-thin model if available
# ----------------------
focus_model = MaterialPF2VFocus(memory_mode="material", inner_steps=8, size=48).to(device)

